  ('583bcc0e-9bc0-5fee-a41c-118f55791137', '6458d333-4432-5d93-98d7-1604ab9c6360', 1, 'val', 'Vad heter ''katt'' på engelska?', '["cat","dog","cow","rat"]'::jsonb, '0'::jsonb, 'Katt heter cat. Dog är hund, cow är ko och rat är råtta.'),
  ('261d2d14-660c-5381-afb1-609284de578d', '6458d333-4432-5d93-98d7-1604ab9c6360', 2, 'val', 'Vilket tal är ''fifteen''?', '["5","15","50","13"]'::jsonb, '1'::jsonb, 'Fifteen är femton. Tal som slutar på -teen ligger mellan 13 och 19, och tal som slutar på -ty är tiotal, som fifty (50).'),
  ('b211108f-f749-50ba-9f93-41e5c360346f', '6458d333-4432-5d93-98d7-1604ab9c6360', 3, 'val', 'Vad heter ''gul'' på engelska?', '["yellow","green","blue","orange"]'::jsonb, '0'::jsonb, 'Gul heter yellow. Green är grön och blue är blå.'),
  ('1d99d490-326e-5afd-b9be-e5c79151232b', '6458d333-4432-5d93-98d7-1604ab9c6360', 4, 'val', 'Vad betyder ''horse''?', '["häst","hus","ko"]'::jsonb, '0'::jsonb, 'Horse betyder häst. Hus heter house, med u i stället för r, och ko heter cow.'),
  ('dd452b5e-ccdf-509b-acc7-862caecb319e', '6458d333-4432-5d93-98d7-1604ab9c6360', 5, 'skriv', 'Skriv talet 12 med bokstäver på engelska.', null, '["twelve"]'::jsonb, 'Tolv heter twelve. Talen 11 och 12 har egna namn: eleven och twelve.'),
