  ('a2792ac0-c5f7-514a-91fd-b8e535dd9c7b', '6458d333-4432-5d93-98d7-1604ab9c6360', 7, 'ordna', 'Ordna talen från minst till störst.', null, '["three","eight","eleven","twenty"]'::jsonb, 'Three är 3, eight är 8, eleven är 11 och twenty är 20.'),
  ('b801ced5-ba53-5ab5-b0dd-37661883dfa2', '6458d333-4432-5d93-98d7-1604ab9c6360', 8, 'ordna', 'Bygg meningen: Jag har en svart katt.', null, '["I","have","a","black","cat."]'::jsonb, 'Färgen står före djuret, precis som på svenska: a black cat.'),
  ('c629fb24-5754-5851-a23c-7c6f6142d8a0', 'ecf1f8ff-9fbe-5707-bb5b-28032d0fe4d6', 1, 'val', 'Vad heter ''måndag'' på engelska?', '["Monday","Sunday","Tuesday","Thursday"]'::jsonb, '0'::jsonb, 'Måndag heter Monday. Sunday är söndag och Tuesday är tisdag.'),
  ('6cda64a8-e9e6-5426-9afe-cde3427629fe', 'ecf1f8ff-9fbe-5707-bb5b-28032d0fe4d6', 2, 'val', 'Vilken dag är ''Thursday''?', '["tisdag","torsdag","fredag"]'::jsonb, '1'::jsonb, 'Thursday är torsdag. Båda orden kommer från guden Tor. Tisdag heter Tuesday.'),
  ('6f57697a-7b82-5157-b240-ca250374062f', 'ecf1f8ff-9fbe-5707-bb5b-28032d0fe4d6', 3, 'skriv', 'Skriv ''onsdag'' på engelska.', null, '["Wednesday"]'::jsonb, 'Onsdag heter Wednesday. Det uttalas ungefär "wensdej", men stavas med ett d före n: Wed-nes-day.'),
  ('2a306f34-4d06-5c9c-974d-fdabc3b12e31', 'ecf1f8ff-9fbe-5707-bb5b-28032d0fe4d6', 4, 'skriv', 'Vilken dag kommer efter Friday? Skriv den på engelska.', null, '["Saturday"]'::jsonb, 'Friday är fredag. Efter fredag kommer lördag, och lördag heter Saturday.'),
  ('1cf52897-61d9-5501-b747-db1bd64ea321', 'ecf1f8ff-9fbe-5707-bb5b-28032d0fe4d6', 5, 'val', 'Vad heter ''juli'' på engelska?', '["June","July","January"]'::jsonb, '1'::jsonb, 'Juli heter July och juni heter June. På engelska skrivs månaderna med stor bokstav.'),
  ('fddb7eb7-f951-58db-8404-c415f264acd2', 'ecf1f8ff-9fbe-5707-bb5b-28032d0fe4d6', 6, 'val', 'Vilken månad kommer före March?', '["February","April","May"]'::jsonb, '0'::jsonb, 'March är mars. Före mars kommer februari, och februari heter February.'),
  ('21e4b831-f08f-578e-99d4-5f8b074eb7eb', 'ecf1f8ff-9fbe-5707-bb5b-28032d0fe4d6', 7, 'ordna', 'Ordna veckodagarna i rätt ordning.', null, '["Monday","Tuesday","Wednesday","Thursday"]'::jsonb, 'Måndag, tisdag, onsdag, torsdag heter Monday, Tuesday, Wednesday, Thursday.'),
  ('8fd9ab02-d4c2-5d60-ac6d-bf5f2646a9b1', 'ecf1f8ff-9fbe-5707-bb5b-28032d0fe4d6', 8, 'ordna', 'Bygg meningen: Min födelsedag är i augusti.', null, '["My","birthday","is","in","August."]'::jsonb, 'Före en månad står in: in August. Månaden skrivs med stor bokstav på engelska.'),
  ('be23abf3-99b5-5aea-a5a5-bbe82d44f977', 'cbbb8576-5e5c-567c-a230-4f7c300d2557', 1, 'val', 'Vad heter ''bror'' på engelska?', '["brother","mother","father","sister"]'::jsonb, '0'::jsonb, 'Bror heter brother. Mother är mamma, father är pappa och sister är syster.'),
  ('d7ffdb47-ac25-5607-991f-41e8d7c310c8', 'cbbb8576-5e5c-567c-a230-4f7c300d2557', 2, 'val', 'Vem är ''grandfather''?', '["farfar eller morfar","farbror eller morbror","kusin"]'::jsonb, '0'::jsonb, 'Grandfather är pappas eller mammas pappa. Farbror och morbror heter uncle, och kusin heter cousin.'),
  ('0e2f00db-8d36-5277-a05c-894d8b1875f2', 'cbbb8576-5e5c-567c-a230-4f7c300d2557', 3, 'val', 'Vad heter ''huvud'' på engelska?', '["head","hand","hair","heart"]'::jsonb, '0'::jsonb, 'Huvud heter head. Hand är hand, hair är hår och heart är hjärta.'),
  ('d3bf57d4-a6e6-5983-95bc-11cd8bfb20a3', 'cbbb8576-5e5c-567c-a230-4f7c300d2557', 4, 'val', 'Vad betyder ''feet''?', '["fötter","fot","tår"]'::jsonb, '0'::jsonb, 'Feet betyder fötter. En fot heter foot, och flera fötter heter feet, inte foots.'),
  ('36c96b76-7f9d-59f4-9506-a34e8401f1ce', 'cbbb8576-5e5c-567c-a230-4f7c300d2557', 5, 'skriv', 'Skriv ''syster'' på engelska.', null, '["sister"]'::jsonb, 'Syster heter sister. Orden låter nästan likadant, men på engelska stavas det med i.'),
  ('c5aea0fd-9e26-5bf4-a3f5-f05ae944b0cf', 'cbbb8576-5e5c-567c-a230-4f7c300d2557', 6, 'skriv', 'Skriv ''näsa'' på engelska.', null, '["nose"]'::jsonb, 'Näsa heter nose. E:et på slutet hörs inte, men det ska vara med.'),
  ('d04fe155-2fcb-5e3c-8a78-02b4a412f89d', 'cbbb8576-5e5c-567c-a230-4f7c300d2557', 7, 'skriv', 'Skriv ''öga'' på engelska.', null, '["eye"]'::jsonb, 'Öga heter eye. Två ögon heter eyes.'),
  ('72a2c6c0-6144-5b40-bbfd-e68538446a6b', 'cbbb8576-5e5c-567c-a230-4f7c300d2557', 8, 'ordna', 'Bygg meningen: Min mamma har långt hår.', null, '["My","mother","has","long","hair."]'::jsonb, 'Efter he, she och my mother säger man has, inte have. Long står före hair, precis som långt står före hår.'),
  ('8418284d-e5f9-5d58-ad10-68b741475d92', '85507ecc-dcba-5d66-a002-70a5b08534ff', 1, 'val', 'Välj rätt ord: I ___ ten years old.', '["am","is","are"]'::jsonb, '0'::jsonb, 'Till I hör am: I am. Is och are passar inte ihop med I.'),
  ('1614187d-ffe1-5776-b1a8-958c1af951e5', '85507ecc-dcba-5d66-a002-70a5b08534ff', 2, 'val', 'Välj rätt ord: She ___ my friend.', '["am","is","are"]'::jsonb, '1'::jsonb, 'She betyder hon. Efter he, she och it kommer is.'),
  ('2b7aa148-f4d2-58dd-b76d-2b9bd81876a9', '85507ecc-dcba-5d66-a002-70a5b08534ff', 3, 'val', 'Välj rätt ord: They ___ in the garden.', '["am","is","are"]'::jsonb, '2'::jsonb, 'They betyder de. Efter we, you och they kommer are.'),
  ('580fac10-482b-5f47-957e-7312c3962b17', '85507ecc-dcba-5d66-a002-70a5b08534ff', 4, 'val', 'Välj rätt ord: My cat ___ black.', '["am","is","are"]'::jsonb, '1'::jsonb, 'My cat är ett djur, som man kan byta mot it. Efter it kommer is.'),
  ('86b82da8-552c-58fe-8ac4-6589a2334897', '85507ecc-dcba-5d66-a002-70a5b08534ff', 5, 'skriv', 'Skriv am, is eller are: We ___ friends.', null, '["are"]'::jsonb, 'We betyder vi, och det är flera personer. Efter we kommer are.'),
  ('504a1ce4-a60d-5356-9201-d5fd6cff2d4d', '85507ecc-dcba-5d66-a002-70a5b08534ff', 6, 'ordna', 'Bygg meningen: Jag är elva år gammal.', null, '["I","am","eleven","years","old."]'::jsonb, 'På engelska säger man I am eleven years old, med am direkt efter I.'),
  ('a44381a1-88b1-5867-9989-a69034ea6ed7', '85507ecc-dcba-5d66-a002-70a5b08534ff', 7, 'ordna', 'Bygg meningen: De är mina vänner.', '["is"]'::jsonb, '["They","are","my","friends."]'::jsonb, 'They betyder de. Efter they kommer are, inte is.'),
  ('8b98f058-7f6e-5147-8b0f-145ca9974ff7', '85507ecc-dcba-5d66-a002-70a5b08534ff', 8, 'ordna', 'Bygg frågan: Är du glad?', null, '["Are","you","happy?"]'::jsonb, 'I en fråga kommer are först, före you: Are you happy?'),
  ('ae7232a3-ba56-5f08-a08d-ca2c650914eb', '6fc9ab79-3c3a-525a-8472-640cc190beac', 1, 'val', 'Vad är plural av ''child''?', '["childs","children","childrens"]'::jsonb, '1'::jsonb, 'Child är oregelbundet och får -ren i plural: one child, two children.'),
  ('f82f8c8d-6cdb-544d-8723-8574f9972cd9', '6fc9ab79-3c3a-525a-8472-640cc190beac', 2, 'val', 'Vad är plural av ''mouse''?', '["mouses","mice","mices"]'::jsonb, '1'::jsonb, 'Mouse byter form i plural: one mouse, two mice.'),
  ('ac2f5a5f-632a-5b99-b524-8e30fcf8da6a', '6fc9ab79-3c3a-525a-8472-640cc190beac', 3, 'val', 'Vad är plural av ''knife''?', '["knifes","knives","knive"]'::jsonb, '1'::jsonb, 'Många ord som slutar på -f eller -fe får -ves i plural: knife – knives, wolf – wolves.'),
  ('3d2a163c-3d39-5d10-bddc-c0489af5b8da', '6fc9ab79-3c3a-525a-8472-640cc190beac', 4, 'val', 'Vad är plural av ''sheep''?', '["sheep","sheeps","sheepes"]'::jsonb, '0'::jsonb, 'Sheep ser likadant ut i plural: one sheep, ten sheep. Så är det också med deer (hjort).'),
  ('8cc92a22-23df-5275-8b76-652259c3d623', '6fc9ab79-3c3a-525a-8472-640cc190beac', 5, 'skriv', 'Skriv plural av ''foot''.', null, '["feet"]'::jsonb, 'Foot blir feet. Vokalen ändras i stället för att ordet får -s.'),
  ('e40bcf34-22e5-561b-a3a4-b73357041699', '6fc9ab79-3c3a-525a-8472-640cc190beac', 6, 'skriv', 'Skriv plural av ''tooth''.', null, '["teeth"]'::jsonb, 'Tooth blir teeth, på samma sätt som foot blir feet.'),
  ('1a8c8ac9-545e-5018-9a3b-e89ba7f239ea', '6fc9ab79-3c3a-525a-8472-640cc190beac', 7, 'skriv', 'Skriv plural av ''woman''.', null, '["women"]'::jsonb, 'Woman blir women, precis som man blir men.'),
  ('87025b8b-7ffc-5d7a-a1f4-de71fe986ea5', '6fc9ab79-3c3a-525a-8472-640cc190beac', 8, 'ordna', 'Bygg meningen: Tre män har stora fötter.', '["has"]'::jsonb, '["Three","men","have","big","feet."]'::jsonb, 'Men är plural av man, och när det är flera blir det have, inte has.'),
  ('3d66ebbb-f965-5c1f-a76e-9320d1a5ddbf', '441e61ef-a97f-5b4d-9f11-4a58648ec8b3', 1, 'val', 'Välj rätt form: She ___ football every Saturday.', '["play","plays","playing"]'::jsonb, '1'::jsonb, 'Efter he, she och it får verbet ett -s i presens: she plays.'),
  ('f7f566d6-3cf7-568f-aff1-996a700fb95f', '441e61ef-a97f-5b4d-9f11-4a58648ec8b3', 2, 'val', 'Välj rätt form: My friends ___ in Stockholm.', '["live","lives","living"]'::jsonb, '0'::jsonb, 'My friends är flera, som they. Då får verbet inget -s: they live.'),
  ('1c309c84-a406-597d-aac8-b1ed29324b82', '441e61ef-a97f-5b4d-9f11-4a58648ec8b3', 3, 'val', 'Vilken mening är rätt?', '["He don''t like fish.","He doesn''t like fish.","He not like fish."]'::jsonb, '1'::jsonb, 'Med he, she och it blir nekandet doesn''t. Verbet efter, like, får då inget -s.'),
  ('89dfd65e-c8a5-59ca-b5ad-499b83d38be8', '441e61ef-a97f-5b4d-9f11-4a58648ec8b3', 4, 'val', 'Välj rätt ord: ___ your sister speak English?', '["Do","Does","Is"]'::jsonb, '1'::jsonb, 'Your sister kan bytas mot she. När det finns ett annat verb, här speak, börjar frågan med does: Does she speak …?'),
  ('81375ee8-0925-52ce-8db6-dfd15984bd2c', '441e61ef-a97f-5b4d-9f11-4a58648ec8b3', 5, 'skriv', 'Skriv ''go'' i presens: He ___ to school by bus.', null, '["goes"]'::jsonb, 'Verb som slutar på -o får -es efter he, she och it: go blir goes, do blir does.'),
  ('47bea200-7eb0-552d-a5cc-372486aaad87', '441e61ef-a97f-5b4d-9f11-4a58648ec8b3', 6, 'skriv', 'Skriv ''watch'' i presens: My dad ___ the news every evening.', null, '["watches"]'::jsonb, 'Verb som slutar på -ch, -sh, -s eller -x får -es: watch blir watches.'),
  ('ffc9d612-1484-5a77-af62-cf3efc1f8e48', '441e61ef-a97f-5b4d-9f11-4a58648ec8b3', 7, 'skriv', 'Skriv ''have'' i presens: She ___ a new bike.', null, '["has","has got"]'::jsonb, 'Have är oregelbundet: I have, men he, she och it has. I brittisk engelska säger man också she has got, och det är lika rätt.'),
  ('afc1ca97-2b2f-5ac3-8226-45bb51635a8a', '441e61ef-a97f-5b4d-9f11-4a58648ec8b3', 8, 'ordna', 'Bygg meningen: Min bror spelar tennis varje dag.', '["play"]'::jsonb, '["My","brother","plays","tennis","every","day."]'::jsonb, 'My brother kan bytas mot he, och då får verbet -s: plays. Every day står sist.'),
  ('fd783691-b3ad-54eb-a25f-a20d3ffe10e6', '9a71070b-4f43-5504-a984-69ea19865248', 1, 'val', 'Välj rätt form: Yesterday I ___ football.', '["play","played","plays"]'::jsonb, '1'::jsonb, 'Yesterday betyder igår. Det som redan hänt skrivs i preteritum, och regelbundna verb får -ed: played.'),
  ('100778ec-d497-512f-bc86-1df794ba2c74', '9a71070b-4f43-5504-a984-69ea19865248', 2, 'val', 'Hur stavas ''study'' i preteritum?', '["studyed","studied","studid"]'::jsonb, '1'::jsonb, 'Slutar verbet på en konsonant och y byts y mot i före -ed: study blir studied.'),
  ('ee575800-0831-5023-b400-3b38985d64f1', '9a71070b-4f43-5504-a984-69ea19865248', 3, 'val', 'Hur stavas ''like'' i preteritum?', '["likeed","liked","likked"]'::jsonb, '1'::jsonb, 'Slutar verbet redan på -e lägger man bara till -d: like blir liked.'),
  ('b7f1d5ca-8a0c-514b-ba10-afa0207cd5bb', '9a71070b-4f43-5504-a984-69ea19865248', 4, 'val', 'Vilken mening handlar om något som redan har hänt?', '["I watch TV every day.","I watched TV yesterday.","I am watching TV now."]'::jsonb, '1'::jsonb, 'Watched har -ed och står i preteritum, och yesterday betyder igår.'),
  ('c93abf77-9a34-5689-9aca-3c443ffad202', '9a71070b-4f43-5504-a984-69ea19865248', 5, 'skriv', 'Skriv ''walk'' i preteritum: We ___ to the park last Sunday.', null, '["walked"]'::jsonb, 'Regelbundna verb får -ed i preteritum: walk blir walked.'),
  ('6893baca-8736-51c2-8d7b-8c293b12accc', '9a71070b-4f43-5504-a984-69ea19865248', 6, 'skriv', 'Skriv ''stop'' i preteritum: The bus ___ outside our school.', null, '["stopped"]'::jsonb, 'Korta verb som slutar på en enda vokal och en konsonant dubblar konsonanten: stop blir stopped. Rain har två vokaler före n och blir bara rained.'),
  ('ba63a830-4d52-5d3e-b58e-cd7e05ef5084', '9a71070b-4f43-5504-a984-69ea19865248', 7, 'skriv', 'Skriv ''enjoy'' i preteritum: We ___ the film.', null, '["enjoyed"]'::jsonb, 'Står det en vokal före y behålls y: enjoy blir enjoyed. Jämför study – studied, där det står en konsonant före y.'),
  ('7d27c546-2c4e-53e2-890a-87ec4fab9739', '9a71070b-4f43-5504-a984-69ea19865248', 8, 'ordna', 'Bygg meningen: Hon hjälpte sin mamma igår.', '["helps"]'::jsonb, '["She","helped","her","mother","yesterday."]'::jsonb, 'Helped är preteritum av help, eftersom det hände igår. Her betyder hennes eller sin när det gäller en kvinna eller flicka.'),
  ('45b00fc0-9be2-5e00-8a84-48ccb7c5e504', '386b8b06-5651-54b1-ad5b-1922f16940bf', 1, 'val', 'Vilket frågeord betyder ''var''?', '["where","when","what","who"]'::jsonb, '0'::jsonb, 'Where betyder var och when betyder när. De två blandas lätt ihop.'),
  ('d082ba67-8dc4-51da-bd12-7895515fa623', '386b8b06-5651-54b1-ad5b-1922f16940bf', 2, 'val', 'Vilket frågeord passar? ___ is your birthday? – In May.', '["Where","When","Who"]'::jsonb, '1'::jsonb, 'Svaret är en tid, i maj. Då frågar man med when, som betyder när.'),
  ('4c01aeaa-e4ea-582e-b6d1-fd74bae56f37', '386b8b06-5651-54b1-ad5b-1922f16940bf', 3, 'val', 'Vilket frågeord passar? ___ is your teacher? – Anna.', '["Who","What","Where"]'::jsonb, '0'::jsonb, 'Svaret är en person. Då frågar man med who, som betyder vem.'),
  ('3103dc97-484e-52bc-89f6-9839e66a9ded', '386b8b06-5651-54b1-ad5b-1922f16940bf', 4, 'val', 'Vilket frågeord passar? ___ do you live? – In Farsta.', '["Where","When","Why"]'::jsonb, '0'::jsonb, 'Svaret är en plats. Då frågar man med where, som betyder var.'),
  ('5dcb61ef-13f2-56c6-a47d-a4e45b5131a5', '386b8b06-5651-54b1-ad5b-1922f16940bf', 5, 'skriv', 'Skriv frågeordet som betyder ''varför''.', null, '["why"]'::jsonb, 'Varför heter why. Svaret börjar ofta med because, som betyder eftersom.'),
  ('28453367-be39-504a-bd7a-aea2f625a3f3', '386b8b06-5651-54b1-ad5b-1922f16940bf', 6, 'skriv', 'Skriv frågeordet som fattas: ___ old are you? – I''m twelve.', null, '["how"]'::jsonb, 'How betyder hur, och how old betyder hur gammal.'),
  ('753152b9-a630-5b46-9126-fa5b3fb1072a', '386b8b06-5651-54b1-ad5b-1922f16940bf', 7, 'ordna', 'Bygg frågan: Vad heter du?', null, '["What","is","your","name?"]'::jsonb, 'På engelska frågar man vad ditt namn är: What is your name?'),
  ('cad6695e-181f-5174-bd0d-3e7815eb7940', '386b8b06-5651-54b1-ad5b-1922f16940bf', 8, 'ordna', 'Bygg frågan: Var bor din kusin?', '["lives?"]'::jsonb, '["Where","does","your","cousin","live?"]'::jsonb, 'Frågor i presens om en annan person byggs med does, och då får verbet inget -s: Where does your cousin live?'),
  ('bd455bbd-aca7-5bed-85e5-7706c897c071', '29714b7b-af59-5b2a-aa52-701483625ede', 1, 'val', 'What is the past tense of ''go''?', '["goed","went","gone"]'::jsonb, '1'::jsonb, 'Go är oregelbundet: go – went – gone. Went är preteritum, och gone används efter have och has.'),
  ('2e9ecce0-d5b7-528f-9afe-cc2a8b9f440c', '29714b7b-af59-5b2a-aa52-701483625ede', 2, 'val', 'Choose the right form: I have ___ my homework.', '["did","done","doed"]'::jsonb, '1'::jsonb, 'Efter have står tredje formen, perfekt particip: do – did – done.'),
  ('64f7c81d-82db-5e76-8c03-f51f99aa9dd3', '29714b7b-af59-5b2a-aa52-701483625ede', 3, 'val', 'Which verb is irregular?', '["walk","take","jump","open"]'::jsonb, '1'::jsonb, 'Take är oregelbundet: take – took – taken. De andra får bara -ed: walked, jumped, opened.'),
  ('106a7796-d998-5bc3-a3c4-7c0bf9d6e6d1', '29714b7b-af59-5b2a-aa52-701483625ede', 4, 'val', 'Which sentence is correct?', '["She has went home.","She has gone home.","She has go home."]'::jsonb, '1'::jsonb, 'Efter has och have står tredje formen: gone. Went står ensamt: she went home.'),
  ('f8e68547-e75f-54a0-b9f8-ce3fe3003eee', '29714b7b-af59-5b2a-aa52-701483625ede', 5, 'skriv', 'Write the past tense of ''see'': Yesterday I ___ a fox in the garden.', null, '["saw"]'::jsonb, 'See är oregelbundet: see – saw – seen.'),
  ('48c4aa24-2040-5a21-a9a0-c6775325086f', '29714b7b-af59-5b2a-aa52-701483625ede', 6, 'skriv', 'Write the past tense of ''buy'': Last week she ___ new shoes.', null, '["bought"]'::jsonb, 'Buy – bought – bought. Samma mönster finns i think – thought och bring – brought.'),
  ('f5e21a20-b77b-530d-92d5-5a425fb24de1', '29714b7b-af59-5b2a-aa52-701483625ede', 7, 'skriv', 'Write the past tense of ''write'': He ___ a letter to his grandmother.', null, '["wrote"]'::jsonb, 'Write är oregelbundet: write – wrote – written.'),
  ('d92e7099-ddcc-56bc-a62b-0acea430cea0', '29714b7b-af59-5b2a-aa52-701483625ede', 8, 'ordna', 'Build the sentence: Vi åt pizza efter matchen.', '["eated"]'::jsonb, '["We","ate","pizza","after","the","match."]'::jsonb, 'Eat är oregelbundet: eat – ate – eaten. Formen eated finns inte.'),
  ('9973e0a9-28ef-5dad-95f8-7022a6684141', 'dd08ad18-e213-5c8f-a505-d30d7517bab9', 1, 'val', 'Choose the right form: I ___ in Stockholm since 2020.', '["live","lived","have lived"]'::jsonb, '2'::jsonb, 'Since visar att något började vid en tidpunkt och pågår fortfarande. Då används present perfect: have lived.'),
  ('d5fef266-b9f6-596e-85c5-9b277b567a7f', 'dd08ad18-e213-5c8f-a505-d30d7517bab9', 2, 'val', 'Choose the right form: We ___ to London last summer.', '["went","have gone","have been going"]'::jsonb, '0'::jsonb, 'Last summer är en tid som är över. Då används past simple: went.'),
  ('75cc9add-8f71-51b5-b657-8feda581886c', 'dd08ad18-e213-5c8f-a505-d30d7517bab9', 3, 'val', 'Which question is correct?', '["Have you ever eaten sushi?","Did you ever ate sushi?","Have you ever ate sushi?"]'::jsonb, '0'::jsonb, 'Ever betyder någonsin, och frågan gäller hela livet fram till nu. Då används present perfect: have + eaten. Efter did står grundformen, aldrig ate.'),
  ('f77ebed6-8ddc-5845-9420-b996b2aa1d12', 'dd08ad18-e213-5c8f-a505-d30d7517bab9', 4, 'val', 'Which sentence is correct?', '["I have seen that film yesterday.","I saw that film yesterday.","I have saw that film yesterday."]'::jsonb, '1'::jsonb, 'Med yesterday används past simple. Present perfect går inte ihop med en tidpunkt som redan är över.'),
  ('50681bc1-1b0f-54f0-bd38-d1867c8002da', 'dd08ad18-e213-5c8f-a505-d30d7517bab9', 5, 'skriv', 'Write has or have: My parents ___ never been to Italy.', null, '["have"]'::jsonb, 'My parents är flera, som they. Då blir det have, inte has.'),
  ('2c87a1fd-90f6-5f34-b793-49c9c7c7401e', 'dd08ad18-e213-5c8f-a505-d30d7517bab9', 6, 'skriv', 'Write the past simple of ''be'': I ___ at home yesterday.', null, '["was"]'::jsonb, 'Yesterday är en tid som är över, så det blir past simple. Be blir was efter I, he, she och it.'),
  ('77b44e93-4eab-56cc-9b11-ce8a0ba0630a', 'dd08ad18-e213-5c8f-a505-d30d7517bab9', 7, 'skriv', 'Write the right form of ''know'': I have ___ her since we were six.', null, '["known"]'::jsonb, 'Efter have står tredje formen: know – knew – known.'),
  ('944364d9-2781-50f3-9936-85b2a749db7e', 'dd08ad18-e213-5c8f-a505-d30d7517bab9', 8, 'ordna', 'Build the question: Har du någonsin varit i Paris?', '["was"]'::jsonb, '["Have","you","ever","been","to","Paris?"]'::jsonb, 'I frågan kommer have först och sedan you. Ever står före been, och been to betyder varit i.'),
  ('9db04203-c693-578c-912a-cb599568cd5f', '48c6f60e-3d58-51bb-928e-3862baa96c25', 1, 'val', 'What is the comparative of ''big''?', '["biger","bigger","more big"]'::jsonb, '1'::jsonb, 'Korta adjektiv som slutar på en enda vokal och en konsonant dubblar konsonanten: big – bigger – biggest.'),
  ('0edbd777-8eeb-59b6-918f-e514361c4e61', '48c6f60e-3d58-51bb-928e-3862baa96c25', 2, 'val', 'Choose the right form: This book is ___ than the film.', '["more interesting","interestinger","most interesting"]'::jsonb, '0'::jsonb, 'Långa adjektiv jämförs med more och most. Det är två saker som jämförs, så det blir more: more interesting than.'),
  ('43a2a387-4c7f-506b-bc2d-d57edc86980a', '48c6f60e-3d58-51bb-928e-3862baa96c25', 3, 'val', 'Choose the right form: Elin is the ___ runner in our class.', '["fast","faster","fastest"]'::jsonb, '2'::jsonb, 'När man jämför med alla i en grupp används superlativ, med the före: the fastest.'),
  ('af73b834-6c15-59ac-b069-ede827676012', '48c6f60e-3d58-51bb-928e-3862baa96c25', 4, 'val', 'Which sentence is correct?', '["Stockholm is bigger than Uppsala.","Stockholm is more bigger than Uppsala.","Stockholm is bigger that Uppsala."]'::jsonb, '0'::jsonb, 'Man jämför med than, och bigger har redan -er, så more ska inte stå framför.'),
  ('183dc024-ae19-57b8-9875-f5fd77fc1d11', '48c6f60e-3d58-51bb-928e-3862baa96c25', 5, 'skriv', 'Write the superlative of ''good'': This is the ___ pizza in town.', null, '["best"]'::jsonb, 'Good är oregelbundet: good – better – best.'),
  ('7512db38-63ed-5913-8c1f-323a01b5b2fa', '48c6f60e-3d58-51bb-928e-3862baa96c25', 6, 'skriv', 'Write the comparative of ''bad'': My cold is ___ today than yesterday.', null, '["worse"]'::jsonb, 'Bad är oregelbundet: bad – worse – worst.'),
  ('d63ff29c-8346-5f04-8997-127aaf5a924e', '48c6f60e-3d58-51bb-928e-3862baa96c25', 7, 'skriv', 'Write the comparative of ''many'': There are ___ students in my class than in yours.', null, '["more"]'::jsonb, 'Many är oregelbundet: many – more – most.'),
  ('56ee2220-56db-544b-a7a6-50f22487aac6', '48c6f60e-3d58-51bb-928e-3862baa96c25', 8, 'ordna', 'Build the sentence: Min syster är äldre än jag.', '["more"]'::jsonb, '["My","sister","is","older","than","me."]'::jsonb, 'Old är ett kort adjektiv och får -er: older. Efter older kommer than.'),
  ('78e0e7a7-f2a1-5bb6-a8b3-deceb8aff2c2', '7b88e6b8-e1d2-5444-9924-3908b5ed4c7d', 1, 'val', 'Choose the right word: The film starts ___ seven o''clock.', '["in","on","at"]'::jsonb, '2'::jsonb, 'Före ett klockslag står at: at seven o''clock.'),
  ('0fe8c3df-f131-5047-96e0-c3fc3f9fd88f', '7b88e6b8-e1d2-5444-9924-3908b5ed4c7d', 2, 'val', 'Choose the right word: My birthday is ___ June.', '["in","on","at"]'::jsonb, '0'::jsonb, 'Före månader, årstider och år står in: in June.'),
  ('815a5f8f-87db-5d1f-a11c-c73d37d60a14', '7b88e6b8-e1d2-5444-9924-3908b5ed4c7d', 3, 'val', 'Choose the right word: I was born ___ 2012.', '["in","on","at"]'::jsonb, '0'::jsonb, 'Före ett årtal står in: in 2012.'),
  ('baf530ab-6153-5f25-9011-825b29dd4948', '7b88e6b8-e1d2-5444-9924-3908b5ed4c7d', 4, 'val', 'Choose the right word: They live ___ Stockholm.', '["in","on","at"]'::jsonb, '0'::jsonb, 'Före städer och länder står in: in Stockholm.'),
  ('a805c570-ae8a-5141-ba46-8a53e0fec4d0', '7b88e6b8-e1d2-5444-9924-3908b5ed4c7d', 5, 'skriv', 'Write in, on or at: We have football practice ___ Tuesdays.', null, '["on"]'::jsonb, 'Före veckodagar står on: on Tuesdays.'),
  ('aad33aa2-8675-5781-ab99-db8bac9283af', '7b88e6b8-e1d2-5444-9924-3908b5ed4c7d', 6, 'skriv', 'Write in, on or at: Your keys are ___ the table.', null, '["on"]'::jsonb, 'Något som ligger ovanpå en yta är on: on the table.'),
  ('79c50bb9-dd8d-5bae-8534-724fb791463f', '7b88e6b8-e1d2-5444-9924-3908b5ed4c7d', 7, 'ordna', 'Build the sentence: Vi spelar alltid fotboll på lördagar.', null, '["We","always","play","football","on","Saturdays."]'::jsonb, 'Always står före verbet på engelska: we always play. Före veckodagar står on.'),
  ('d889e348-019a-566e-8ae4-dd71333f865b', '7b88e6b8-e1d2-5444-9924-3908b5ed4c7d', 8, 'ordna', 'Build the question: Vad gör du på söndagar?', null, '["What","do","you","do","on","Sundays?"]'::jsonb, 'Frågor i presens byggs med do före you. Det andra do är verbet göra, och före veckodagar står on.'),
  ('5db29dc5-2c3b-5bb3-827a-7fb007665f04', 'eed7a9f3-722d-56a4-a2fb-7fd3e01a3c65', 1, 'val', 'Vad är −3 + 7?', '["4","−10","−4","10"]'::jsonb, '0'::jsonb, 'Börja på −3 på tallinjen och gå 7 steg åt höger. Du passerar noll och hamnar på 4.'),
  ('2c7fa72d-c472-5a90-b7d7-04f24e3f981f', 'eed7a9f3-722d-56a4-a2fb-7fd3e01a3c65', 2, 'val', 'Vad är 2 − 9?', '["−7","7","−11","11"]'::jsonb, '0'::jsonb, 'Börja på 2 och gå 9 steg åt vänster. Efter 2 steg är du på noll, och 7 steg till ger −7.'),
  ('72584146-39fc-5b0c-9c5a-32ffd5c60324', 'eed7a9f3-722d-56a4-a2fb-7fd3e01a3c65', 3, 'skriv', 'På morgonen är det −6 °C. Till lunch har det blivit 9 grader varmare. Hur många grader är det vid lunch?', null, '["3"]'::jsonb, 'Varmare betyder uppåt på termometern: −6 + 9 = 3. Det är 3 grader vid lunch.'),
  ('28e70434-ae63-59b0-a9d8-19bed5a853dd', 'eed7a9f3-722d-56a4-a2fb-7fd3e01a3c65', 4, 'val', 'Vad är 6 − (−2)?', '["8","4","−8","−4"]'::jsonb, '0'::jsonb, 'Att dra bort ett negativt tal är samma sak som att lägga till: 6 − (−2) = 6 + 2 = 8.'),
  ('09b16615-ad5c-561d-8c72-9c5ba62e707a', 'eed7a9f3-722d-56a4-a2fb-7fd3e01a3c65', 5, 'val', 'Vad är −4 · 3?', '["−12","12","−7","−1"]'::jsonb, '0'::jsonb, 'Minus gånger plus blir minus. 4 · 3 = 12, så −4 · 3 = −12.'),
  ('fbcda135-5ebc-5832-a335-60152760f52c', 'eed7a9f3-722d-56a4-a2fb-7fd3e01a3c65', 6, 'skriv', 'Vad är (−6) · (−5)?', null, '["30"]'::jsonb, 'Minus gånger minus blir plus. 6 · 5 = 30, så svaret är 30.'),
  ('f3425361-0fe9-5b00-934b-f7b2f7c27f61', 'eed7a9f3-722d-56a4-a2fb-7fd3e01a3c65', 7, 'skriv', 'Vad är −20 / 4?', null, '["-5","- 5","(-5)"]'::jsonb, 'Ett negativt tal delat med ett positivt blir negativt. 20 / 4 = 5, så svaret är −5.'),
  ('503a7e74-ba9c-5d2c-a73e-d1d5073aaadc', 'eed7a9f3-722d-56a4-a2fb-7fd3e01a3c65', 8, 'ordna', 'Ordna talen från minst till störst.', null, '["−7","−4","−1","3","6"]'::jsonb, 'Ju längre till vänster på tallinjen, desto mindre tal. −7 är mindre än −4, för det ligger längre bort från noll åt minushållet.'),
  ('8181edd0-58a6-582a-a7fe-2cbed9915aaf', 'aea2acc4-cba4-571c-8db3-8220afa34feb', 1, 'val', 'Vad är 2 + 3 · 4?', '["14","20","24","9"]'::jsonb, '0'::jsonb, 'Multiplikation räknas före addition: 3 · 4 = 12, och sedan 2 + 12 = 14.'),
  ('61f7e30a-7b0e-5643-a1b8-9e84362a1ee2', 'aea2acc4-cba4-571c-8db3-8220afa34feb', 2, 'val', 'Vad är (2 + 3) · 4?', '["20","14","9"]'::jsonb, '0'::jsonb, 'Parentesen räknas först: 2 + 3 = 5. Sedan 5 · 4 = 20.'),
  ('01040221-020e-5f46-a993-289b733c8c9e', 'aea2acc4-cba4-571c-8db3-8220afa34feb', 3, 'skriv', 'Vad är 20 − 12 / 4?', null, '["17"]'::jsonb, 'Division räknas före subtraktion: 12 / 4 = 3, och sedan 20 − 3 = 17.'),
  ('46a67323-baac-5467-93cb-20592fcba679', 'aea2acc4-cba4-571c-8db3-8220afa34feb', 4, 'val', 'Vad är 10 − 4 − 3?', '["3","9","11"]'::jsonb, '0'::jsonb, 'Plus och minus räknas från vänster till höger: 10 − 4 = 6, och sedan 6 − 3 = 3.'),
  ('e63513a3-d654-5dec-9fda-9ec6a86a0742', 'aea2acc4-cba4-571c-8db3-8220afa34feb', 5, 'val', 'Vad är 2 · 3²?', '["18","36","12"]'::jsonb, '0'::jsonb, 'Potensen räknas före multiplikationen: 3² = 9, och 2 · 9 = 18.'),
  ('f87c81ee-8ca2-562d-b277-5f90913527b1', 'aea2acc4-cba4-571c-8db3-8220afa34feb', 6, 'skriv', 'Vad är 18 / (4 + 2)?', null, '["3"]'::jsonb, 'Parentesen först: 4 + 2 = 6. Sedan 18 / 6 = 3.'),
  ('35b3ec27-223e-567c-bca8-16e90cbd9cfc', 'aea2acc4-cba4-571c-8db3-8220afa34feb', 7, 'skriv', 'Vad är 4 · 5 − 2 · 6?', null, '["8"]'::jsonb, 'Båda multiplikationerna räknas före minus: 20 − 12 = 8.'),
  ('c727bb76-0388-529b-894d-425ce7a47eec', 'aea2acc4-cba4-571c-8db3-8220afa34feb', 8, 'ordna', 'Räkna ut 7 + 2 · (8 − 3). Ordna stegen i den ordning du räknar dem. En bricka blir över.', '["7 + 2 = 9"]'::jsonb, '["8 − 3 = 5","2 · 5 = 10","7 + 10 = 17"]'::jsonb, 'Parentesen först, sedan multiplikationen och sist additionen. 7 + 2 får inte räknas först, för 2 hör ihop med multiplikationen.'),
  ('05add185-197e-5d49-a885-989df8be5358', 'c10ebd4a-9240-5960-866d-00c262dec944', 1, 'val', 'Hur mycket är 10 % av 350?', '["35","3,5","340","360"]'::jsonb, '0'::jsonb, 'Tio procent är en tiondel. 350 / 10 = 35.'),
  ('97d4d6e8-7e68-54ad-93b0-9be9ce3d9d58', 'c10ebd4a-9240-5960-866d-00c262dec944', 2, 'skriv', 'Hur mycket är 25 % av 80?', null, '["20"]'::jsonb, '25 % är en fjärdedel. 80 / 4 = 20.'),
  ('7f9b8297-452d-553f-b0b1-c5cf81a22b3c', 'c10ebd4a-9240-5960-866d-00c262dec944', 3, 'val', 'Vilket decimaltal är samma sak som 7 %?', '["0,07","0,7","0,007"]'::jsonb, '0'::jsonb, 'Procent betyder hundradelar. 7 % = 7/100 = 0,07.'),
  ('29663969-20ca-5e2f-9b83-6a6cb9e784fa', 'c10ebd4a-9240-5960-866d-00c262dec944', 4, 'skriv', 'Hur mycket är 15 % av 200?', null, '["30"]'::jsonb, '1 % av 200 är 2. Då är 15 % lika med 15 · 2 = 30.'),
  ('2d52817a-1fb2-53aa-a31c-e3c67f135a36', 'c10ebd4a-9240-5960-866d-00c262dec944', 5, 'val', 'En tröja kostar 400 kr. Priset sänks med 30 %. Hur många kronor billigare blir tröjan?', '["120 kr","280 kr","30 kr","12 kr"]'::jsonb, '0'::jsonb, '30 % av 400 kr är 0,3 · 400 = 120 kr. Så mycket billigare blir den, och det nya priset är 400 − 120 = 280 kr.'),
  ('a694a208-47a3-55bd-b4da-bad0301757af', 'c10ebd4a-9240-5960-866d-00c262dec944', 6, 'skriv', 'I en klass går 25 elever. 40 % av dem spelar ett instrument. Hur många elever är det?', null, '["10"]'::jsonb, '40 % = 0,4, och 0,4 · 25 = 10.'),
  ('076fb3b3-9e84-59a8-a8f9-6cdb1b50383b', 'c10ebd4a-9240-5960-866d-00c262dec944', 7, 'val', 'Hur mycket är 5 % av 60?', '["3","12","0,3"]'::jsonb, '0'::jsonb, '10 % av 60 är 6. 5 % är hälften av det, alltså 3.'),
  ('58a718da-74bb-505f-9326-b8d9d7816867', 'c10ebd4a-9240-5960-866d-00c262dec944', 8, 'ordna', 'Ordna från minst till störst.', null, '["10 % av 30","10 % av 50","50 % av 20","25 % av 100"]'::jsonb, 'Räkna ut varje: 10 % av 30 = 3, 10 % av 50 = 5, 50 % av 20 = 10 och 25 % av 100 = 25.'),
  ('416776e3-5ccd-55eb-82fd-814de06dfc14', '3cf49d8a-1327-5061-97d1-bcb568a48342', 1, 'val', 'Lös ekvationen x + 7 = 12. Vad är x?', '["5","19","−5"]'::jsonb, '0'::jsonb, 'Dra bort 7 från båda sidor: x = 12 − 7 = 5.'),
  ('a6bbbc97-7c06-568d-a47e-cf6478b2a77a', '3cf49d8a-1327-5061-97d1-bcb568a48342', 2, 'skriv', 'Lös ekvationen x − 4 = 9. Vad är x?', null, '["13","x = 13","x=13","x= 13","x =13"]'::jsonb, 'Lägg till 4 på båda sidor: x = 9 + 4 = 13.'),
  ('4591da3c-03aa-517a-8b64-4766e3e94f7e', '3cf49d8a-1327-5061-97d1-bcb568a48342', 3, 'val', 'Lös ekvationen 3x = 21. Vad är x?', '["7","18","63","24"]'::jsonb, '0'::jsonb, '3x betyder 3 · x. Dela båda sidor med 3: x = 21 / 3 = 7.'),
  ('40e1ff38-bedc-556f-b406-e269e582addc', '3cf49d8a-1327-5061-97d1-bcb568a48342', 4, 'skriv', 'Lös ekvationen x/5 = 6. Vad är x?', null, '["30","x = 30","x=30","x= 30","x =30"]'::jsonb, 'Multiplicera båda sidor med 5: x = 6 · 5 = 30.'),
  ('a26f228b-a162-5c83-98ec-4efca35df2cb', '3cf49d8a-1327-5061-97d1-bcb568a48342', 5, 'val', 'Lös ekvationen 2x + 3 = 11. Vad är x?', '["4","7","8"]'::jsonb, '0'::jsonb, 'Dra först bort 3 från båda sidor: 2x = 8. Dela sedan med 2: x = 4.'),
  ('d16d8c26-532f-53b7-bb0f-d69527ae6cab', '3cf49d8a-1327-5061-97d1-bcb568a48342', 6, 'skriv', 'Lös ekvationen 5x − 2 = 23. Vad är x?', null, '["5","x = 5","x=5","x= 5","x =5"]'::jsonb, 'Lägg till 2 på båda sidor: 5x = 25. Dela med 5: x = 5.'),
  ('6c1c9794-4267-50eb-a599-615f75e43f87', '3cf49d8a-1327-5061-97d1-bcb568a48342', 7, 'val', 'Vilket x gör att 4x + 1 = 13 stämmer?', '["3","12","3,5"]'::jsonb, '0'::jsonb, 'Pröva genom att sätta in: 4 · 3 + 1 = 12 + 1 = 13. Det stämmer.'),
  ('ad7593b5-66f5-53a9-af7f-f3850161ccc1', '3cf49d8a-1327-5061-97d1-bcb568a48342', 8, 'ordna', 'Ordna stegen för att lösa 3x + 5 = 26. En bricka blir över.', '["3x = 31"]'::jsonb, '["3x + 5 = 26","3x = 21","x = 7"]'::jsonb, 'Dra först bort 5 från båda sidor, så att 3x = 21. Dela sedan med 3: x = 7. 3x = 31 får man om man lägger till 5 i stället för att dra bort.'),
  ('460189bc-d9aa-5a49-a653-8ec317259b10', 'dbaeff07-800a-5f3a-b320-c53dee438bfb', 1, 'val', 'Vad betyder 5³?', '["5 · 5 · 5","5 · 3","5 + 5 + 5","3 · 3 · 3 · 3 · 3"]'::jsonb, '0'::jsonb, 'Exponenten 3 visar hur många femmor som multipliceras med varandra: 5 · 5 · 5.'),
  ('3068252a-8449-578d-95b0-5a285d211524', 'dbaeff07-800a-5f3a-b320-c53dee438bfb', 2, 'skriv', 'Vad är 2⁵?', null, '["32"]'::jsonb, '2⁵ = 2 · 2 · 2 · 2 · 2 = 32.'),
  ('569a65bb-3658-517e-9926-a894345627e3', 'dbaeff07-800a-5f3a-b320-c53dee438bfb', 3, 'val', 'Vad är 4²?', '["16","8","6"]'::jsonb, '0'::jsonb, '4² = 4 · 4 = 16. Det är inte 4 · 2.'),
  ('7cacd692-68e3-582f-b6a6-def8579108e6', 'dbaeff07-800a-5f3a-b320-c53dee438bfb', 4, 'val', 'I potensen 7⁴, vilket tal är basen?', '["7","4","28"]'::jsonb, '0'::jsonb, 'Basen är talet som multipliceras med sig själv. Exponenten 4 visar hur många sjuor det är: 7⁴ = 7 · 7 · 7 · 7.'),
  ('97b71ded-97b9-5d41-a0f9-bafd740307d6', 'dbaeff07-800a-5f3a-b320-c53dee438bfb', 5, 'skriv', 'Vad är 10⁴?', null, '["10 000"]'::jsonb, 'Exponenten i en tiopotens visar hur många nollor det blir: 10⁴ = 10 000.'),
  ('a221307a-1db2-5b42-bb6b-bcca39c726af', 'dbaeff07-800a-5f3a-b320-c53dee438bfb', 6, 'val', 'Vad är 3² + 4²?', '["25","49","14"]'::jsonb, '0'::jsonb, 'Räkna ut potenserna först: 9 + 16 = 25. (3 + 4)² = 49 är ett annat uttryck.'),
  ('a9bb61f4-1336-5569-a286-8f651eb433fc', 'dbaeff07-800a-5f3a-b320-c53dee438bfb', 7, 'skriv', 'Vad är (−3)²?', null, '["9"]'::jsonb, '(−3)² = (−3) · (−3). Minus gånger minus blir plus, så svaret är 9.'),
  ('5a076c37-ef8d-59e6-9508-f1c111ec0ea2', 'dbaeff07-800a-5f3a-b320-c53dee438bfb', 8, 'ordna', 'Ordna från minst till störst.', null, '["2³","3²","2⁴","5²"]'::jsonb, '2³ = 8, 3² = 9, 2⁴ = 16 och 5² = 25.'),
  ('10317b29-b840-55ca-9b62-fac9dba40f29', 'dca94a9c-5099-5811-ab2c-19dddd3c4930', 1, 'val', 'Förenkla 3x + 5x.', '["8x","15x","8x²","8"]'::jsonb, '0'::jsonb, 'Tre x plus fem x blir åtta x. Talen framför x läggs ihop, och x står kvar.'),
  ('70e30d69-8f2b-5185-b0c3-15a69a0982d0', 'dca94a9c-5099-5811-ab2c-19dddd3c4930', 2, 'val', 'Förenkla 4a + 3 + 2a + 5.', '["6a + 8","14a","6a + 15"]'::jsonb, '0'::jsonb, 'Slå ihop a-termerna för sig (4a + 2a = 6a) och talen för sig (3 + 5 = 8). En a-term och ett tal kan inte slås ihop.'),
  ('bd779dac-70e7-5474-a380-6ee95beeeb75', 'dca94a9c-5099-5811-ab2c-19dddd3c4930', 3, 'skriv', 'Förenkla 7y − 2y.', null, '["5y","5 y","5*y","5 * y","5* y","5 *y","5·y","5 · y","5×y","5 × y"]'::jsonb, 'Sju y minus två y blir fem y, alltså 5y.'),
  ('98a66301-2ddc-5957-b8d3-de7930d47211', 'dca94a9c-5099-5811-ab2c-19dddd3c4930', 4, 'val', 'Multiplicera in: 3(x + 4).', '["3x + 12","3x + 4","x + 12","3x + 7"]'::jsonb, '0'::jsonb, 'Både x och 4 ska multipliceras med 3: 3 · x + 3 · 4 = 3x + 12.'),
  ('a6eb78ee-f42c-53ad-98b1-6c528b27b66d', 'dca94a9c-5099-5811-ab2c-19dddd3c4930', 5, 'val', 'Förenkla 5x − (2x + 3).', '["3x − 3","3x + 3","7x + 3"]'::jsonb, '0'::jsonb, 'Minustecknet framför parentesen gäller allt inuti: 5x − 2x − 3 = 3x − 3.'),
  ('87fd1868-f868-50c4-952e-b123f83536b0', 'dca94a9c-5099-5811-ab2c-19dddd3c4930', 6, 'skriv', 'Vad är värdet av 2x + 7 om x = 4?', null, '["15"]'::jsonb, 'Sätt in 4 i stället för x: 2 · 4 + 7 = 8 + 7 = 15.'),
  ('36c7441b-1330-5825-bc7c-2e1d70187433', 'dca94a9c-5099-5811-ab2c-19dddd3c4930', 7, 'skriv', 'Vad är värdet av 3a − 5 om a = −2?', null, '["-11","- 11","(-11)"]'::jsonb, 'Sätt in −2 i stället för a: 3 · (−2) − 5 = −6 − 5 = −11.'),
  ('b5ceb4b2-dbab-521a-8423-9a812409ce71', 'dca94a9c-5099-5811-ab2c-19dddd3c4930', 8, 'ordna', 'Förenkla 2(x + 3) + 4x steg för steg. Ordna raderna. En bricka blir över.', '["2x + 3 + 4x"]'::jsonb, '["2(x + 3) + 4x","2x + 6 + 4x","6x + 6"]'::jsonb, 'Multiplicera först in 2 i parentesen: både x och 3 ska multipliceras med 2. Slå sedan ihop x-termerna: 2x + 4x = 6x.'),
  ('0654580e-9974-5029-9ac7-42873d191268', '520118c9-2d11-543e-b88d-2feff5c22962', 1, 'val', 'Lös 5x = 2x + 9. Vad är x?', '["3","9","27"]'::jsonb, '0'::jsonb, 'Dra bort 2x från båda sidor: 3x = 9. Dela med 3: x = 3.'),
  ('55c05909-690a-5b75-9596-918486f20260', '520118c9-2d11-543e-b88d-2feff5c22962', 2, 'skriv', 'Lös 4x + 3 = x + 15. Vad är x?', null, '["4","x = 4","x=4","x= 4","x =4"]'::jsonb, 'Dra bort x från båda sidor: 3x + 3 = 15. Dra bort 3: 3x = 12, så x = 4.'),
  ('6d288e4e-58b8-54f0-b353-06ddd9218af9', '520118c9-2d11-543e-b88d-2feff5c22962', 3, 'val', 'Du ska lösa 7x − 4 = 3x + 8. Vilket är ett bra första steg?', '["Dra bort 3x från båda sidor","Dra bort 3x bara från högra sidan","Lägg till 4 bara på vänstra sidan","Dela vänstra sidan med 7"]'::jsonb, '0'::jsonb, 'Det du gör på ena sidan måste du göra på den andra, annars stämmer inte likheten längre. Att dra bort 3x från båda sidor samlar x-termerna till vänster.'),
  ('8519ffbe-6fd0-525b-91fe-e6bf2865060d', '520118c9-2d11-543e-b88d-2feff5c22962', 4, 'skriv', 'Lös 7x − 4 = 3x + 8. Vad är x?', null, '["3","x = 3","x=3","x= 3","x =3"]'::jsonb, 'Dra bort 3x: 4x − 4 = 8. Lägg till 4: 4x = 12. Dela med 4: x = 3.'),
  ('14f8787f-41d6-5fb9-a0ef-faa37fdcc507', '520118c9-2d11-543e-b88d-2feff5c22962', 5, 'val', 'Lös 2(x + 5) = 4x. Vad är x?', '["5","2,5","10","−5"]'::jsonb, '0'::jsonb, 'Multiplicera in: 2x + 10 = 4x. Dra bort 2x: 10 = 2x, så x = 5.'),
  ('4d1d5d7e-4b16-5dfd-888c-b4e7d9e96619', '520118c9-2d11-543e-b88d-2feff5c22962', 6, 'val', 'Lös 6 − x = x + 2. Vad är x?', '["2","4","−2"]'::jsonb, '0'::jsonb, 'Lägg till x på båda sidor: 6 = 2x + 2. Dra bort 2: 4 = 2x, så x = 2.'),
  ('44474f29-7378-5874-859c-ec4cf58d4733', '520118c9-2d11-543e-b88d-2feff5c22962', 7, 'skriv', 'Lös x + 9 = 4x + 15. Vad är x?', null, '["-2","x = -2","x=-2","x= -2","x =-2","- 2","x = - 2"]'::jsonb, 'Dra bort x: 9 = 3x + 15. Dra bort 15: −6 = 3x, så x = −2.'),
  ('1ca46448-83a4-59f6-955f-314d97ce0737', '520118c9-2d11-543e-b88d-2feff5c22962', 8, 'ordna', 'Ordna stegen för att lösa 5x + 1 = 2x + 13.', null, '["5x + 1 = 2x + 13","3x + 1 = 13","3x = 12","x = 4"]'::jsonb, 'Samla först x-termerna på ena sidan genom att dra bort 2x. Dra sedan bort 1 och dela till sist med 3.'),
  ('69315b41-0740-528b-87fb-8b1864c5e2ea', 'c0d980f1-3f05-5b8b-baf8-8f4d7bdf80bd', 1, 'val', 'Ett pris höjs med 20 %. Vilken är förändringsfaktorn?', '["1,2","0,2","0,8","120"]'::jsonb, '0'::jsonb, 'Det nya priset är 100 % + 20 % = 120 % av det gamla, och 120 % = 1,2.'),
  ('9f096087-dde2-570a-bf7e-3b334af6ad83', 'c0d980f1-3f05-5b8b-baf8-8f4d7bdf80bd', 2, 'val', 'Ett pris sänks med 15 %. Vilken är förändringsfaktorn?', '["0,85","0,15","1,15"]'::jsonb, '0'::jsonb, 'Kvar blir 100 % − 15 % = 85 % av priset, och 85 % = 0,85.'),
  ('5c3b25c1-8c4e-565c-88fe-e48f296bda29', 'c0d980f1-3f05-5b8b-baf8-8f4d7bdf80bd', 3, 'skriv', 'En cykel kostar 3 000 kr. Priset höjs med 10 %. Hur många kronor kostar cykeln nu?', null, '["3300"]'::jsonb, 'Förändringsfaktorn är 1,1. 1,1 · 3 000 = 3 300 kr.'),
  ('111c8176-3111-5632-8540-5b52ab3e5a88', 'c0d980f1-3f05-5b8b-baf8-8f4d7bdf80bd', 4, 'skriv', 'En jacka kostar 800 kr och säljs med 25 % rabatt. Hur många kronor kostar den nu?', null, '["600"]'::jsonb, 'Förändringsfaktorn är 1 − 0,25 = 0,75, och 0,75 · 800 = 600 kr.'),
  ('7d5ac13e-4f41-5095-93a8-e406e47fe649', 'c0d980f1-3f05-5b8b-baf8-8f4d7bdf80bd', 5, 'val', 'Förändringsfaktorn är 1,06. Vad har hänt?', '["Ökat med 6 %","Ökat med 106 %","Minskat med 6 %","Ökat med 0,06 %"]'::jsonb, '0'::jsonb, '1,06 = 106 %. Det är 6 % mer än de 100 % man började med.'),
  ('f601f4d3-ae9f-5e3d-82d6-862ab2f22c59', 'c0d980f1-3f05-5b8b-baf8-8f4d7bdf80bd', 6, 'val', 'En biljett kostade 50 kr och kostar nu 60 kr. Med hur många procent har priset ökat?', '["20 %","10 %","17 %","120 %"]'::jsonb, '0'::jsonb, 'Priset har ökat med 10 kr. Jämför med det gamla priset: 10 / 50 = 0,2 = 20 %.'),
  ('8b1a5076-6c26-5111-9311-ccecd99f0ff9', 'c0d980f1-3f05-5b8b-baf8-8f4d7bdf80bd', 7, 'skriv', 'En mobil kostade 4 000 kr och kostar nu 3 400 kr. Med hur många procent har priset sänkts?', null, '["15"]'::jsonb, 'Sänkningen är 600 kr. Jämför med det gamla priset: 600 / 4 000 = 0,15 = 15 %.'),
  ('e10b0efb-6c52-5e09-a094-a11f2bd8ba6f', 'c0d980f1-3f05-5b8b-baf8-8f4d7bdf80bd', 8, 'ordna', 'Ordna förändringsfaktorerna från störst minskning till störst ökning.', null, '["0,7","0,95","1,05","1,3"]'::jsonb, '0,7 är en minskning med 30 % och 0,95 en minskning med 5 %. 1,05 är en ökning med 5 % och 1,3 en ökning med 30 %.'),
  ('96cd4a0b-1426-5f2d-aa02-2c93f02352d5', 'ee75bdce-c83e-510e-88e2-e0f66a5a3d60', 1, 'val', 'Vad kallas den längsta sidan i en rätvinklig triangel?', '["Hypotenusa","Katet","Bas","Diagonal"]'::jsonb, '0'::jsonb, 'Hypotenusan ligger mitt emot den räta vinkeln och är alltid längst. De två andra sidorna kallas kateter.'),
  ('9ac8d319-228f-552c-b00e-a92c89a80d0d', 'ee75bdce-c83e-510e-88e2-e0f66a5a3d60', 2, 'val', 'I en rätvinklig triangel är c hypotenusan och a och b kateterna. Vilken formel är Pythagoras sats?', '["a² + b² = c²","a + b = c","a² + c² = b²","a · b = c²"]'::jsonb, '0'::jsonb, 'Kateternas kvadrater tillsammans är lika med hypotenusans kvadrat.'),
  ('378b9d9e-6d0f-5fca-af09-556df687f380', 'ee75bdce-c83e-510e-88e2-e0f66a5a3d60', 3, 'skriv', 'Kateterna i en rätvinklig triangel är 3 cm och 4 cm. Hur många cm är hypotenusan?', null, '["5"]'::jsonb, '3² + 4² = 9 + 16 = 25, och √25 = 5.'),
  ('0850ae78-5a22-5d57-9e30-2ef488c1e32f', 'ee75bdce-c83e-510e-88e2-e0f66a5a3d60', 4, 'skriv', 'Kateterna i en rätvinklig triangel är 6 cm och 8 cm. Hur många cm är hypotenusan?', null, '["10"]'::jsonb, '6² + 8² = 36 + 64 = 100, och √100 = 10.'),
  ('59d214b1-2dcf-58fe-9d1c-0c78e7709beb', 'ee75bdce-c83e-510e-88e2-e0f66a5a3d60', 5, 'val', 'I en rätvinklig triangel är hypotenusan 25 cm och ena kateten 7 cm. Hur lång är den andra kateten?', '["24 cm","18 cm","cirka 26 cm","32 cm"]'::jsonb, '0'::jsonb, 'Här söks en katet, så du drar bort: 25² − 7² = 625 − 49 = 576, och √576 = 24.'),
  ('c173b654-44f0-5241-a76a-8fce5331330a', 'ee75bdce-c83e-510e-88e2-e0f66a5a3d60', 6, 'val', 'Här är sidorna i fyra trianglar. Vilken av trianglarna är rätvinklig?', '["9, 12 och 15 cm","5, 6 och 7 cm","4, 6 och 8 cm","7, 8 och 10 cm"]'::jsonb, '0'::jsonb, 'Pröva a² + b² = c² med den längsta sidan som c: 9² + 12² = 81 + 144 = 225, och 15² = 225.'),
  ('1133c254-ae5e-514d-9ba1-50b6f6bbdeff', 'ee75bdce-c83e-510e-88e2-e0f66a5a3d60', 7, 'skriv', 'En stege som är 2,5 m lång står lutad mot en lodrät vägg på plan mark. Stegens fot står 0,7 m från väggen. Hur många meter upp på väggen når stegen?', null, '["2,4"]'::jsonb, 'Stegen är hypotenusan, så du drar bort: 2,5² − 0,7² = 6,25 − 0,49 = 5,76, och √5,76 = 2,4.'),
  ('fe5bdfec-f4b4-5fc4-b934-7cdbb706ecb2', 'ee75bdce-c83e-510e-88e2-e0f66a5a3d60', 8, 'ordna', 'Kateterna är 5 cm och 12 cm. Ordna stegen för att räkna ut hypotenusan c.', null, '["c² = 5² + 12²","c² = 25 + 144","c² = 169","c = 13"]'::jsonb, 'Kvadrera kateterna, lägg ihop dem och dra till sist roten ur summan.'),
  ('0032df07-b1dc-5319-9744-d3f90b2e0fd1', '9181aaf7-c38c-5619-be42-893727874055', 1, 'val', 'Du slår en vanlig tärning. Hur stor är sannolikheten att få en sexa?', '["1/6","1/5","6/1","1/2"]'::jsonb, '0'::jsonb, 'Tärningen har 6 sidor som är lika troliga, och en av dem är en sexa.'),
  ('7c4acaf1-d6e4-5d7e-b468-c2dc73fb80a3', '9181aaf7-c38c-5619-be42-893727874055', 2, 'val', 'Du slår en vanlig tärning. Hur stor är sannolikheten att få ett jämnt tal?', '["1/2","1/3","1/6","2/3"]'::jsonb, '0'::jsonb, 'Tre av sex sidor är jämna: 2, 4 och 6. 3/6 = 1/2.'),
  ('6350b901-57f0-55f1-932e-b5f934f9be0f', '9181aaf7-c38c-5619-be42-893727874055', 3, 'skriv', 'I en påse finns 3 röda och 7 blå kulor. Du tar en kula utan att titta. Hur stor är sannolikheten att den är röd? Svara i procent.', null, '["30"]'::jsonb, '3 av 10 kulor är röda. 3/10 = 0,3 = 30 %.'),
  ('93721826-7c97-593a-9121-6ed000e58189', '9181aaf7-c38c-5619-be42-893727874055', 4, 'val', 'Vilken sannolikhet har något som är omöjligt?', '["0","1","0,5","100"]'::jsonb, '0'::jsonb, 'Sannolikheten 0 betyder att det aldrig händer, och 1 att det alltid händer. Alla sannolikheter ligger mellan 0 och 1.'),
  ('43c78167-e3bb-5e1b-aa7c-430c45829270', '9181aaf7-c38c-5619-be42-893727874055', 5, 'skriv', 'Sannolikheten att det regnar i morgon är 0,2. Hur stor är sannolikheten att det inte regnar? Svara med ett decimaltal.', null, '["0,8","4/5","4 / 5"]'::jsonb, 'Antingen regnar det eller inte, och tillsammans blir det 1. 1 − 0,2 = 0,8.'),
  ('2875f610-117d-52e9-8e38-f69436919598', '9181aaf7-c38c-5619-be42-893727874055', 6, 'val', 'Du singlar slant två gånger. Hur stor är sannolikheten att få krona båda gångerna?', '["1/4","1/2","1/3"]'::jsonb, '0'::jsonb, 'Det finns fyra lika troliga utfall: krona-krona, krona-klave, klave-krona och klave-klave. Ett av dem är krona båda gångerna.'),
  ('ddf82e0f-9cd0-50be-9a7c-02319015065b', '9181aaf7-c38c-5619-be42-893727874055', 7, 'skriv', 'Du slår en tärning 60 gånger. Hur många sexor kan du förvänta dig att få?', null, '["10"]'::jsonb, 'Sannolikheten för en sexa är 1/6, och 1/6 av 60 är 10. Det blir inte alltid exakt 10, men ungefär så många.'),
  ('9770388f-9d62-5ba0-9e3a-49737d8fd6bb', '9181aaf7-c38c-5619-be42-893727874055', 8, 'ordna', 'I en påse finns 8 gröna, 1 vit, 5 gula och 2 röda kulor. Du tar en kula utan att titta. Ordna färgerna från minst till mest sannolik.', null, '["Vit","Röd","Gul","Grön"]'::jsonb, 'Ju fler kulor av en färg, desto större chans. Av 16 kulor är 1 vit, 2 röda, 5 gula och 8 gröna.'),
  ('93283b27-e2f2-541e-98aa-ab121eb98a10', '4e968daa-47b5-5fec-a4d0-ec1cbc790f45', 1, 'val', 'Vad är k-värdet i y = 3x + 2?', '["3","2","5"]'::jsonb, '0'::jsonb, 'k är talet framför x. Det visar hur mycket y ökar när x ökar med 1.'),
  ('0da161b4-9268-5e55-b07f-8438bff9c5b4', '4e968daa-47b5-5fec-a4d0-ec1cbc790f45', 2, 'val', 'I vilken punkt skär linjen y = 2x − 5 y-axeln?', '["(0, −5)","(0, 2)","(−5, 0)","(0, 5)"]'::jsonb, '0'::jsonb, 'På y-axeln är x = 0. Då är y = 2 · 0 − 5 = −5, alltså m-värdet.'),
  ('134377aa-9a21-5f09-9ba6-91c3082e7f32', '4e968daa-47b5-5fec-a4d0-ec1cbc790f45', 3, 'skriv', 'y = 4x + 1. Vad är y när x = 3?', null, '["13","y = 13","y=13","y= 13","y =13"]'::jsonb, 'Sätt in x = 3: y = 4 · 3 + 1 = 12 + 1 = 13.'),
  ('cb579954-1c4e-53ea-9235-4f55aced6bff', '4e968daa-47b5-5fec-a4d0-ec1cbc790f45', 4, 'skriv', 'y = −2x + 6. Vad är y när x = 5?', null, '["-4","y = -4","y=-4","y= -4","y =-4","- 4","y = - 4"]'::jsonb, 'Sätt in x = 5: y = −2 · 5 + 6 = −10 + 6 = −4.'),
  ('598e8869-16be-5012-99e3-2924ab7eb7c2', '4e968daa-47b5-5fec-a4d0-ec1cbc790f45', 5, 'val', 'Vilken av linjerna lutar nedåt, från vänster till höger?', '["y = −3x + 4","y = 3x − 4","y = x + 10","y = 0,5x − 2"]'::jsonb, '0'::jsonb, 'En linje lutar nedåt när k är negativt. Här är k = −3. m-värdet påverkar inte lutningen.'),
  ('0000f825-3c2f-548b-ae57-2508d176e8f1', '4e968daa-47b5-5fec-a4d0-ec1cbc790f45', 6, 'val', 'En linje skär y-axeln i (0, 1). För varje steg åt höger går den 2 steg uppåt. Vilken är linjens ekvation?', '["y = 2x + 1","y = x + 2","y = 2x","y = −2x + 1"]'::jsonb, '0'::jsonb, 'k = 2 eftersom linjen går 2 steg uppåt per steg åt höger. m = 1 eftersom den skär y-axeln i (0, 1).'),
  ('78c990b2-5430-57e3-bdaa-dd5ca711f94f', '4e968daa-47b5-5fec-a4d0-ec1cbc790f45', 7, 'skriv', 'Ett gymkort kostar 200 kr i startavgift och sedan 50 kr per besök. Kostnaden är y = 50x + 200, där x är antalet besök. Hur många kronor kostar 6 besök?', null, '["500"]'::jsonb, 'Sätt in x = 6: y = 50 · 6 + 200 = 300 + 200 = 500.'),
  ('de9ec830-c49b-5397-a34f-87e782be3e1b', '4e968daa-47b5-5fec-a4d0-ec1cbc790f45', 8, 'ordna', 'Ordna linjerna efter k-värdet, från minst till störst.', null, '["y = −4x + 1","y = −x + 3","y = 2x","y = 5x − 2"]'::jsonb, 'k-värdena är −4, −1, 2 och 5. Negativt k lutar nedåt och positivt uppåt.'),
  ('fbc71b5d-dc79-5150-bb34-6335de0f5896', '38b58aa0-4ce7-5518-9fa3-812008c8de13', 1, 'val', 'Lös ekvationen x² = 25.', '["x = 5 eller x = −5","x = 5","x = 12,5","x = −5"]'::jsonb, '0'::jsonb, 'Både 5 · 5 och (−5) · (−5) blir 25. Därför har ekvationen två lösningar.'),
  ('24c07e30-12c2-5734-8894-a6c23eec9780', '38b58aa0-4ce7-5518-9fa3-812008c8de13', 2, 'skriv', 'x² = 49 och x är positivt. Vad är x?', null, '["7","x = 7","x=7","x= 7","x =7"]'::jsonb, '7 · 7 = 49. Lösningen −7 räknas inte här, eftersom x ska vara positivt.'),
  ('6dd033e4-dd44-55d4-aee6-367db440fefd', '38b58aa0-4ce7-5518-9fa3-812008c8de13', 3, 'val', 'Lös ekvationen x² − 16 = 0.', '["x = 4 eller x = −4","x = 4","x = 8 eller x = −8","x = 16"]'::jsonb, '0'::jsonb, 'Lägg till 16 på båda sidor: x² = 16. Både 4² och (−4)² är 16.'),
  ('d29ef9e3-9081-55e8-8816-6c3cec38e53f', '38b58aa0-4ce7-5518-9fa3-812008c8de13', 4, 'skriv', 'Lös ekvationen 3x² = 75. Vad är den positiva lösningen?', null, '["5","x = 5","x=5","x= 5","x =5"]'::jsonb, 'Dela båda sidor med 3: x² = 25. Den positiva lösningen är x = 5.'),
  ('61b59e35-a156-5cda-8e61-3dcf3530c0ae', '38b58aa0-4ce7-5518-9fa3-812008c8de13', 5, 'val', 'Lös ekvationen (x − 3)(x + 2) = 0.', '["x = 3 eller x = −2","x = −3 eller x = 2","x = 3 eller x = 2","x = 6"]'::jsonb, '0'::jsonb, 'En produkt är noll när någon av faktorerna är noll. x − 3 = 0 ger x = 3, och x + 2 = 0 ger x = −2.'),
  ('32eef3b7-cee7-5fd2-95df-6bb2586dc0ab', '38b58aa0-4ce7-5518-9fa3-812008c8de13', 6, 'val', 'Vilket av talen är en lösning till (x + 5)(x − 1) = 0?', '["−5","5","−1","0"]'::jsonb, '0'::jsonb, 'Om x = −5 blir första parentesen 0, och 0 gånger något är alltid 0.'),
  ('d2e00b5a-29e3-5022-bf55-ab1ac9efc7ce', '38b58aa0-4ce7-5518-9fa3-812008c8de13', 7, 'skriv', 'Lös ekvationen x² + 9 = 90. Vad är den positiva lösningen?', null, '["9","x = 9","x=9","x= 9","x =9"]'::jsonb, 'Dra bort 9 från båda sidor: x² = 81. 9 · 9 = 81, så den positiva lösningen är 9.'),
  ('9d94ab1e-eeb5-5bb8-b691-ec6e2894aadb', '38b58aa0-4ce7-5518-9fa3-812008c8de13', 8, 'ordna', 'Ordna stegen för att lösa 2x² − 8 = 42.', null, '["2x² − 8 = 42","2x² = 50","x² = 25","x = 5 eller x = −5"]'::jsonb, 'Lägg till 8, dela med 2 och dra sist roten ur. Glöm inte den negativa lösningen.'),
  ('d644f963-52ba-5746-b4b6-e7a9d4010e4a', '76cc8781-a0bd-5ef1-b947-725c61ec37be', 1, 'val', 'Hur skrivs 4 000 i grundpotensform?', '["4 · 10³","4 · 10⁴","40 · 10²","4 · 10²"]'::jsonb, '0'::jsonb, '4 000 = 4 · 1 000 = 4 · 10³. Talet framför tiopotensen ska vara minst 1 och mindre än 10.'),
  ('daa92d95-ba45-5b25-8ef0-9557c06583c5', '76cc8781-a0bd-5ef1-b947-725c61ec37be', 2, 'val', 'Alla fyra är samma tal. Vilket är skrivet i grundpotensform?', '["3,2 · 10⁵","32 · 10⁴","0,32 · 10⁶","320 000"]'::jsonb, '0'::jsonb, 'I grundpotensform är talet framför tiopotensen minst 1 och mindre än 10. Det gäller bara 3,2.'),
  ('c789cf99-7298-5f77-8ac9-1939afbcfac7', '76cc8781-a0bd-5ef1-b947-725c61ec37be', 3, 'skriv', 'Skriv 5 · 10⁴ som ett vanligt tal.', null, '["50 000"]'::jsonb, '10⁴ = 10 000, och 5 · 10 000 = 50 000.'),
  ('b2839f4e-d4ab-50e7-b48e-6f6465a539a5', '76cc8781-a0bd-5ef1-b947-725c61ec37be', 4, 'skriv', 'Skriv 2,7 · 10³ som ett vanligt tal.', null, '["2700"]'::jsonb, '10³ = 1 000, och 2,7 · 1 000 = 2 700. Kommat flyttas tre steg åt höger.'),
  ('f2c7d748-4bf1-50b7-ba05-e3b6c3a4fbe7', '76cc8781-a0bd-5ef1-b947-725c61ec37be', 5, 'val', 'Hur skrivs 0,003 i grundpotensform?', '["3 · 10⁻³","3 · 10³","3 · 10⁻²","0,3 · 10⁻²"]'::jsonb, '0'::jsonb, '0,003 = 3/1 000 = 3 · 10⁻³. En negativ exponent betyder ett tal mindre än 1.'),
  ('9e136715-3393-51e5-818b-7d835b9a95a2', '76cc8781-a0bd-5ef1-b947-725c61ec37be', 6, 'val', 'Hur skrivs 8 miljarder i grundpotensform?', '["8 · 10⁹","8 · 10⁶","8 · 10¹²","8 · 10⁸"]'::jsonb, '0'::jsonb, 'En miljard är 1 000 000 000, en etta med nio nollor. Därför är 8 miljarder 8 · 10⁹.'),
  ('fb769e5e-a75f-52a9-a01a-953e2606f167', '76cc8781-a0bd-5ef1-b947-725c61ec37be', 7, 'skriv', 'Skriv 6 · 10⁻² som ett decimaltal.', null, '["0,06"]'::jsonb, '10⁻² = 0,01, och 6 · 0,01 = 0,06.'),
  ('b43061b6-93fd-5c7b-a44b-b8a24a17e9d2', '76cc8781-a0bd-5ef1-b947-725c61ec37be', 8, 'ordna', 'Ordna talen från minst till störst.', null, '["5 · 10⁻³","2 · 10⁻²","9 · 10²","1,2 · 10³"]'::jsonb, 'Jämför först exponenterna: större exponent, större tal. 9 · 10² = 900 är mindre än 1,2 · 10³ = 1 200, och 5 · 10⁻³ = 0,005 är mindre än 2 · 10⁻² = 0,02.'),
  ('c9688096-775b-58a9-a413-b0cb6efba6c7', '09309afb-19ed-5314-b032-da6452434ae7', 1, 'val', 'En karta har skalan 1 : 10 000. Vad betyder det?', '["1 cm på kartan är 10 000 cm i verkligheten","1 cm på kartan är 10 000 m i verkligheten","10 000 cm på kartan är 1 cm i verkligheten"]'::jsonb, '0'::jsonb, 'Skalan jämför samma enhet: 1 cm på kartan är 10 000 cm, alltså 100 m, i verkligheten.'),
  ('8b763f64-e8e2-5374-b395-c9902600ffe6', '09309afb-19ed-5314-b032-da6452434ae7', 2, 'skriv', 'På en karta i skala 1 : 50 000 är en väg 4 cm lång. Hur många km är vägen i verkligheten?', null, '["2"]'::jsonb, '4 · 50 000 = 200 000 cm. 100 000 cm är 1 km, så vägen är 2 km.'),
  ('0be2ceb3-bd28-5053-9c51-b6d8ac8668ee', '09309afb-19ed-5314-b032-da6452434ae7', 3, 'val', 'En modellbil är byggd i skala 1 : 20. Modellen är 22 cm lång. Hur lång är den riktiga bilen?', '["4,4 m","1,1 cm","44 m","2,2 m"]'::jsonb, '0'::jsonb, 'Den riktiga bilen är 20 gånger längre: 22 · 20 = 440 cm, och 440 cm = 4,4 m.'),
  ('b7182215-d824-5f1b-b66b-c448ba878d5a', '09309afb-19ed-5314-b032-da6452434ae7', 4, 'val', 'En teckning av en myra är gjord i skala 5 : 1. Vad betyder det?', '["Teckningen är 5 gånger så stor som myran","Myran är 5 gånger så stor som teckningen","Myran är 5 cm lång"]'::jsonb, '0'::jsonb, 'Första talet gäller bilden. 5 : 1 betyder att 5 cm på teckningen är 1 cm på den riktiga myran.'),
  ('89ada29f-b924-5e28-8a69-aedb3b0cd625', '09309afb-19ed-5314-b032-da6452434ae7', 5, 'skriv', 'Två trianglar är likformiga. Den lilla har sidorna 3, 4 och 5 cm. Den stora triangelns kortaste sida är 9 cm. Hur många cm är den stora triangelns längsta sida?', null, '["15"]'::jsonb, 'Den stora triangeln är 9 / 3 = 3 gånger så stor. Då är längsta sidan 5 · 3 = 15 cm.'),
  ('ea659aa0-9da7-5805-82cc-b7766b3cd3ef', '09309afb-19ed-5314-b032-da6452434ae7', 6, 'val', 'En rektangel är 2 cm bred och 5 cm lång. Vilken av rektanglarna är likformig med den?', '["6 cm bred och 15 cm lång","4 cm bred och 7 cm lång","5 cm bred och 8 cm lång"]'::jsonb, '0'::jsonb, 'Likformiga figurer är förstorade lika mycket åt alla håll: 2 · 3 = 6 och 5 · 3 = 15. Att lägga till samma tal på båda sidorna ger inte samma form.'),
  ('f345c370-3c20-533b-af5f-707933657012', '09309afb-19ed-5314-b032-da6452434ae7', 7, 'skriv', 'På en ritning i skala 1 : 50 är ett rum 8 cm långt. Hur många meter är rummet i verkligheten?', null, '["4"]'::jsonb, '8 · 50 = 400 cm, och 400 cm är 4 m.'),
  ('b09d16eb-b032-5fae-b9bf-43bed401c019', '09309afb-19ed-5314-b032-da6452434ae7', 8, 'ordna', 'Ordna skalorna från den som förminskar mest till den som förstorar mest.', null, '["1 : 1 000","1 : 10","1 : 1","20 : 1"]'::jsonb, '1 : 1 000 förminskar 1 000 gånger och 1 : 10 bara 10 gånger. 1 : 1 är verklig storlek, och 20 : 1 förstorar 20 gånger.'),
  ('fce2a08d-d2c8-56d5-9922-6b8cb9ddb341', 'e7cc59a3-c3d8-5eb3-8dba-6cbbac49e445', 1, 'val', 'Vad är typvärdet för 3, 8, 5, 3, 10, 3, 6?', '["3","5","10"]'::jsonb, '0'::jsonb, 'Typvärdet är det värde som finns flest gånger. 3 finns tre gånger.'),
  ('587fade2-5b42-5845-98f5-562c3c113b84', 'e7cc59a3-c3d8-5eb3-8dba-6cbbac49e445', 2, 'skriv', 'Vad är medelvärdet av 4, 6, 8 och 10?', null, '["7"]'::jsonb, 'Lägg ihop alla: 4 + 6 + 8 + 10 = 28. Dela med antalet, 4: 28 / 4 = 7.'),
  ('28fe4363-e106-50f5-83b6-d8a26d88d43f', 'e7cc59a3-c3d8-5eb3-8dba-6cbbac49e445', 3, 'val', 'Vad är medianen för 9, 2, 5, 11, 7?', '["7","5","6,8","11"]'::jsonb, '0'::jsonb, 'Sortera först: 2, 5, 7, 9, 11. Medianen är talet i mitten, 7.'),
  ('21dbdb9e-14a0-5971-87db-3fd79f0560f6', 'e7cc59a3-c3d8-5eb3-8dba-6cbbac49e445', 4, 'skriv', 'Vad är medianen för 3, 8, 10 och 1?', null, '["5,5"]'::jsonb, 'Sortera: 1, 3, 8, 10. Med ett jämnt antal tal är medianen mitt emellan de två mittersta: (3 + 8) / 2 = 5,5.'),
  ('11364956-4829-5693-b4ec-e63da6be2d81', 'e7cc59a3-c3d8-5eb3-8dba-6cbbac49e445', 5, 'val', 'Fem kompisar har 20, 25, 30, 25 och 400 kr. Vilket lägesmått påverkas mest av det stora värdet 400?', '["Medelvärdet","Medianen","Typvärdet"]'::jsonb, '0'::jsonb, 'Medelvärdet blir 100 kr, fast fyra av fem har högst 30 kr. Medianen och typvärdet är båda 25 kr, och ett enda stort värde flyttar dem inte.'),
  ('afb16c4c-a72f-5dcf-8ab1-17ffbcb18c7a', 'e7cc59a3-c3d8-5eb3-8dba-6cbbac49e445', 6, 'val', 'Medelvärdet av tre tal är 6. Två av talen är 4 och 5. Vilket är det tredje talet?', '["9","6","7","3"]'::jsonb, '0'::jsonb, 'Tre tal med medelvärdet 6 har summan 3 · 6 = 18. 18 − 4 − 5 = 9.'),
  ('154ff7cf-01fd-5f0c-8b78-f4270d5abba0', 'e7cc59a3-c3d8-5eb3-8dba-6cbbac49e445', 7, 'skriv', 'Ett lag gjorde 2, 0, 3, 1 och 4 mål i fem matcher. Hur många mål gjorde laget i medeltal per match?', null, '["2"]'::jsonb, 'Lägg ihop målen: 2 + 0 + 3 + 1 + 4 = 10. Dela med antalet matcher: 10 / 5 = 2.'),
  ('733edbb1-bffd-58db-bc93-a7478f20084b', 'e7cc59a3-c3d8-5eb3-8dba-6cbbac49e445', 8, 'ordna', 'Talen är 2, 2, 3, 7 och 11. Ordna lägesmåtten från minst till störst.', null, '["Typvärdet","Medianen","Medelvärdet"]'::jsonb, 'Typvärdet är 2, medianen 3 och medelvärdet (2 + 2 + 3 + 7 + 11) / 5 = 25 / 5 = 5.'),
  ('f6452d26-a6a5-5098-9b04-6a7e3219a1bb', '3bcbd3d1-5407-543d-84bd-ff96fe4367f1', 1, 'val', 'Förenkla 3(2x − 1) − 2(x − 4).', '["4x + 5","4x − 11","4x − 7","8x + 5"]'::jsonb, '0'::jsonb, 'Multiplicera in: 6x − 3 − 2x + 8, eftersom −2 · (−4) = 8. Slå sedan ihop: 4x + 5.'),
  ('1bbbf16b-e7e3-5311-9228-ae0597b28bd4', '3bcbd3d1-5407-543d-84bd-ff96fe4367f1', 2, 'skriv', 'Lös 4(x − 2) = 2x + 6. Vad är x?', null, '["7","x = 7","x=7","x= 7","x =7"]'::jsonb, 'Multiplicera in: 4x − 8 = 2x + 6. Dra bort 2x och lägg till 8: 2x = 14, så x = 7.'),
  ('d7a49a89-a9cf-5815-b598-97ae4aafa2a2', '3bcbd3d1-5407-543d-84bd-ff96fe4367f1', 3, 'val', 'Lös x/3 + 2 = 5. Vad är x?', '["9","1","21","3"]'::jsonb, '0'::jsonb, 'Dra bort 2: x/3 = 3. Multiplicera med 3: x = 9.'),
  ('4811834d-695e-5d74-a79a-e7f98cf8b652', '3bcbd3d1-5407-543d-84bd-ff96fe4367f1', 4, 'skriv', 'Lös 2x/5 = 6. Vad är x?', null, '["15","x = 15","x=15","x= 15","x =15"]'::jsonb, 'Multiplicera båda sidor med 5: 2x = 30. Dela med 2: x = 15.'),
  ('e721ebd8-e1c8-5f69-9267-7d0189e4bdff', '3bcbd3d1-5407-543d-84bd-ff96fe4367f1', 5, 'val', 'Formeln v = s / t ger hastigheten v när man färdas sträckan s på tiden t. Lös ut s.', '["s = v · t","s = v / t","s = t / v","s = v + t"]'::jsonb, '0'::jsonb, 'Multiplicera båda sidor med t: v · t = s.'),
  ('99bcc49b-3220-5884-904e-061f098ca8a4', '3bcbd3d1-5407-543d-84bd-ff96fe4367f1', 6, 'val', 'Förenkla x(x + 4) − x².', '["4x","2x² + 4x","x + 4","4x − x²"]'::jsonb, '0'::jsonb, 'Multiplicera in: x² + 4x − x². x² och −x² tar ut varandra, och kvar blir 4x.'),
  ('efe21c6c-a447-57a6-b29d-0ec971c7d7f2', '3bcbd3d1-5407-543d-84bd-ff96fe4367f1', 7, 'skriv', 'Lös 5 − 3x = 2x − 20. Vad är x?', null, '["5","x = 5","x=5","x= 5","x =5"]'::jsonb, 'Lägg till 3x och 20 på båda sidor: 25 = 5x, så x = 5.'),
  ('6aac8551-8a64-547b-9050-c2d06932c194', '3bcbd3d1-5407-543d-84bd-ff96fe4367f1', 8, 'ordna', 'Ordna stegen för att lösa (x + 4)/2 = 3x − 3.', null, '["(x + 4)/2 = 3x − 3","x + 4 = 6x − 6","10 = 5x","x = 2"]'::jsonb, 'Multiplicera båda sidor med 2 så att bråket försvinner. Samla sedan x på ena sidan och talen på den andra, och dela med 5.'),
  ('d526fee0-7eaa-5f94-ac76-ecfbba2438ab', '37dcb12e-d107-54fe-a15f-7dea4e9bd639', 1, 'val', 'Ett pris höjs med 10 % och sänks sedan med 10 %. Hur stort är det nya priset jämfört med det gamla?', '["Det är 1 % lägre","Det är detsamma","Det är 1 % högre","Det är 10 % lägre"]'::jsonb, '0'::jsonb, 'Förändringsfaktorerna multipliceras: 1,1 · 0,9 = 0,99. Det nya priset är 99 % av det gamla.'),
  ('f5dd3bb4-e67f-525b-a6a3-6dcd3d922dde', '37dcb12e-d107-54fe-a15f-7dea4e9bd639', 2, 'skriv', 'Du sätter in 10 000 kr på ett konto med 3 % ränta per år. Räntan läggs till en gång per år, och du tar inte ut något. Hur många kronor finns på kontot efter 2 år?', null, '["10 609"]'::jsonb, '10 000 · 1,03² = 10 000 · 1,0609 = 10 609 kr. Andra året får du ränta också på förra årets ränta.'),
  ('7d25f32e-e7a5-58e9-b95a-741f07f4f16e', '37dcb12e-d107-54fe-a15f-7dea4e9bd639', 3, 'val', '2 000 kr växer med 4 % per år. Vilket uttryck ger beloppet efter 5 år?', '["2 000 · 1,04⁵","2 000 · 1,04 · 5","2 000 · 1,2","2 000 · 0,04⁵"]'::jsonb, '0'::jsonb, 'Varje år multipliceras beloppet med 1,04. Fem år i rad blir 1,04 · 1,04 · 1,04 · 1,04 · 1,04 = 1,04⁵.'),
  ('c1bbb5fb-1d40-59f9-8003-17f1a5981355', '37dcb12e-d107-54fe-a15f-7dea4e9bd639', 4, 'val', 'En bil tappar 15 % av sitt värde varje år. Vilken förändringsfaktor gäller för två år?', '["0,85²","0,85 · 2","0,7","0,15²"]'::jsonb, '0'::jsonb, '0,85 per år, två år i rad: 0,85 · 0,85 = 0,85². Det är inte samma sak som att dra bort 30 %.'),
  ('8a45f550-0ace-5093-b1c0-ecb6da483155', '37dcb12e-d107-54fe-a15f-7dea4e9bd639', 5, 'skriv', 'En telefon kostar 5 000 kr. Priset sänks först med 20 % och sedan med 10 %. Hur många kronor kostar den nu?', null, '["3600"]'::jsonb, 'Förändringsfaktorerna är 0,8 och 0,9. 5 000 · 0,8 · 0,9 = 3 600 kr.'),
  ('0917683b-b71c-5d06-9488-a9c89d21fd5e', '37dcb12e-d107-54fe-a15f-7dea4e9bd639', 6, 'val', 'Ett värde ökar med 50 % två år i rad. Hur mycket har det ökat totalt?', '["125 %","100 %","150 %","225 %"]'::jsonb, '0'::jsonb, '1,5 · 1,5 = 2,25. Det nya värdet är 225 % av det gamla, alltså en ökning med 125 %.'),
  ('804ecb68-2253-5b80-aadd-270eb250014f', '37dcb12e-d107-54fe-a15f-7dea4e9bd639', 7, 'skriv', 'Priset på en vara ökar från 250 kr till 300 kr. Vilken är förändringsfaktorn?', null, '["1,2","6/5","6 / 5"]'::jsonb, 'Förändringsfaktorn är det nya värdet delat med det gamla: 300 / 250 = 1,2.'),
  ('96da0cf4-fa79-57db-bb3b-aa0a8e7537f2', '37dcb12e-d107-54fe-a15f-7dea4e9bd639', 8, 'ordna', 'Ordna stegen för att räkna ut vad 8 000 kr blir efter 2 år med 5 % ränta per år.', null, '["Förändringsfaktorn är 1,05","8 000 · 1,05²","8 000 · 1,1025","8 820 kr"]'::jsonb, '5 % ränta ger faktorn 1,05. Två år i rad blir 1,05² = 1,1025, och 8 000 · 1,1025 = 8 820 kr.'),
  ('db5a7c83-f64d-5b79-86b7-6fde07eaef2e', 'e87329d3-b648-51b7-a508-428906ebf4e7', 1, 'val', 'Vilken formel ger lutningen k för en linje genom punkterna (x₁, y₁) och (x₂, y₂)?', '["k = (y₂ − y₁) / (x₂ − x₁)","k = (x₂ − x₁) / (y₂ − y₁)","k = (y₂ + y₁) / (x₂ + x₁)","k = y₂ / x₂"]'::jsonb, '0'::jsonb, 'Lutningen är ändringen i y delat med ändringen i x, alltså Δy / Δx.'),
  ('3ba2570b-a29c-5ca7-a9e8-e72f0f14ea7c', 'e87329d3-b648-51b7-a508-428906ebf4e7', 2, 'skriv', 'En linje går genom (1, 3) och (4, 9). Vad är k?', null, '["2","k = 2","k=2","k= 2","k =2"]'::jsonb, 'k = (9 − 3) / (4 − 1) = 6 / 3 = 2.'),
  ('fd6e19ef-c3df-5472-8fe8-73fbe9ef7e1e', 'e87329d3-b648-51b7-a508-428906ebf4e7', 3, 'skriv', 'En linje går genom (−2, 5) och (2, −3). Vad är k?', null, '["-2","k = -2","k=-2","k= -2","k =-2","- 2","k = - 2"]'::jsonb, 'k = (−3 − 5) / (2 − (−2)) = −8 / 4 = −2. Linjen lutar nedåt.'),
  ('625cd29e-cc4b-5e39-83c8-d52f0a32d995', 'e87329d3-b648-51b7-a508-428906ebf4e7', 4, 'val', 'En linje har k = 3 och går genom punkten (2, 1). Vad är m?', '["−5","5","1","−1"]'::jsonb, '0'::jsonb, 'Sätt in punkten i y = 3x + m: 1 = 3 · 2 + m, alltså 1 = 6 + m och m = −5.'),
  ('a1585339-e6bf-5962-a024-5e4601baf1fb', 'e87329d3-b648-51b7-a508-428906ebf4e7', 5, 'val', 'Vilken linje går genom (0, 4) och (2, 0)?', '["y = −2x + 4","y = 2x + 4","y = −0,5x + 4","y = −2x + 2"]'::jsonb, '0'::jsonb, 'k = (0 − 4) / (2 − 0) = −2, och linjen skär y-axeln i (0, 4), så m = 4.'),
  ('6524147e-3113-5d43-8533-66a70f502a79', 'e87329d3-b648-51b7-a508-428906ebf4e7', 6, 'val', 'Två linjer är parallella. Den ena är y = 3x − 1. Vilken kan den andra vara?', '["y = 3x + 5","y = −3x − 1","y = 5x − 1"]'::jsonb, '0'::jsonb, 'Parallella linjer har samma lutning, alltså samma k-värde. Här är k = 3.'),
  ('4838461c-e648-50c6-a69f-088021d45a32', 'e87329d3-b648-51b7-a508-428906ebf4e7', 7, 'skriv', 'En taxiresa kostar 145 kr för 3 km och 205 kr för 9 km. Priset ökar lika mycket för varje km. Hur många kronor kostar varje km?', null, '["10"]'::jsonb, 'Lutningen är priset per km: (205 − 145) / (9 − 3) = 60 / 6 = 10 kr per km.'),
  ('adfc5f25-9d30-572a-884b-cc2d581d1133', 'e87329d3-b648-51b7-a508-428906ebf4e7', 8, 'ordna', 'Ta fram ekvationen för linjen genom (1, 5) och (3, 11). Ordna stegen.', null, '["k = (11 − 5) / (3 − 1) = 3","5 = 3 · 1 + m","m = 2","y = 3x + 2"]'::jsonb, 'Räkna först ut k. Sätt sedan in en av punkterna för att få m, och skriv till sist ekvationen.'),
  ('e036c84f-451d-52c7-81fe-1a2a8249658e', 'd983fef3-a831-54e6-a604-84cac55797ef', 1, 'val', 'Förenkla 2³ · 2⁴.', '["2⁷","2¹²","4⁷","4¹²"]'::jsonb, '0'::jsonb, 'Vid multiplikation med samma bas adderas exponenterna: 3 + 4 = 7.'),
  ('07850237-bd0a-5143-9c63-9a95fb3c5c6a', 'd983fef3-a831-54e6-a604-84cac55797ef', 2, 'val', 'Förenkla x⁸ / x².', '["x⁶","x⁴","x¹⁰","x¹⁶"]'::jsonb, '0'::jsonb, 'Vid division med samma bas subtraheras exponenterna: 8 − 2 = 6.'),
  ('a451f9fe-c62c-5fcc-9c96-8cd81120507c', 'd983fef3-a831-54e6-a604-84cac55797ef', 3, 'skriv', 'Vad är 5⁰?', null, '["1"]'::jsonb, 'Varje tal utom 0 upphöjt till 0 är 1. Det följer av att 5³ / 5³ = 5³⁻³ = 5⁰, och ett tal delat med sig självt är 1.'),
  ('0e310305-a4b6-5f2c-95e3-5508c3d5d50b', 'd983fef3-a831-54e6-a604-84cac55797ef', 4, 'skriv', 'Vad är 2⁻³? Svara som bråk.', null, '["1/8","1 / 8","0,125"]'::jsonb, 'En negativ exponent betyder ett delat med potensen: 2⁻³ = 1 / 2³ = 1/8.'),
  ('84c4e751-b79a-5657-bdc4-0d78dea5ef4c', 'd983fef3-a831-54e6-a604-84cac55797ef', 5, 'val', 'En bakteriekultur har 500 bakterier och fördubblas varje timme. Vilken funktion ger antalet y efter x timmar?', '["y = 500 · 2ˣ","y = 500 + 2x","y = 2 · 500ˣ","y = 500 · x²"]'::jsonb, '0'::jsonb, 'Startvärdet är 500, och varje timme multipliceras antalet med 2. Efter x timmar har det gjorts x gånger.'),
  ('4c2be257-0edf-52b1-bc58-205af53dac97', 'd983fef3-a831-54e6-a604-84cac55797ef', 6, 'val', 'Funktionen y = 300 · 0,9ˣ beskriver något som ändras varje år. Vad händer?', '["Det minskar med 10 % per år","Det minskar med 90 % per år","Det ökar med 9 % per år","Det minskar med 0,9 per år"]'::jsonb, '0'::jsonb, 'Förändringsfaktorn 0,9 betyder att 90 % finns kvar varje år, alltså en minskning med 10 %.'),
  ('666d10ad-2345-5d4d-b2aa-0dcc64aa7ca8', 'd983fef3-a831-54e6-a604-84cac55797ef', 7, 'skriv', 'y = 200 · 1,5ˣ. Vad är y när x = 2?', null, '["450","y = 450","y=450","y= 450","y =450"]'::jsonb, '1,5² = 1,5 · 1,5 = 2,25, och 200 · 2,25 = 450.'),
  ('121bacb2-18a7-58fa-b64d-c7e6cbea8e74', 'd983fef3-a831-54e6-a604-84cac55797ef', 8, 'ordna', 'Ordna från minst till störst.', null, '["2⁻²","5⁰","2³","3²"]'::jsonb, '2⁻² = 1/4, 5⁰ = 1, 2³ = 8 och 3² = 9.'),
  ('6a9ac31f-99e3-538a-997f-5b38e512853f', '912f706e-1ab2-558f-9eb2-734dce630894', 1, 'val', 'Du slår två tärningar. Hur stor är sannolikheten att båda visar en sexa?', '["1/36","1/12","1/3","1/6"]'::jsonb, '0'::jsonb, 'Tärningarna påverkar inte varandra, så sannolikheterna multipliceras: 1/6 · 1/6 = 1/36.'),
  ('c8b516ea-8fc2-5688-ba61-992c3c99c6d4', '912f706e-1ab2-558f-9eb2-734dce630894', 2, 'skriv', 'Du singlar slant tre gånger. Hur stor är sannolikheten att få krona alla tre gångerna? Svara som bråk.', null, '["1/8","1 / 8","0,125"]'::jsonb, '1/2 · 1/2 · 1/2 = 1/8.'),
  ('32cc50cd-77dd-5869-a5e6-3330a49f0348', '912f706e-1ab2-558f-9eb2-734dce630894', 3, 'val', 'I en påse finns 4 röda och 6 blå kulor. Du drar två kulor utan att lägga tillbaka den första. Hur stor är sannolikheten att båda är röda?', '["2/15","4/25","2/5"]'::jsonb, '0'::jsonb, 'Först 4 röda av 10, sedan 3 röda av de 9 som är kvar: 4/10 · 3/9 = 12/90 = 2/15.'),
  ('64fe71d6-a4c2-52ca-b090-449999092f00', '912f706e-1ab2-558f-9eb2-734dce630894', 4, 'skriv', 'Sannolikheten att en buss är sen är 0,1. Dagarna påverkar inte varandra. Hur stor är sannolikheten att bussen varken är sen i dag eller i morgon? Svara med ett decimaltal.', null, '["0,81","81/100","81 / 100"]'::jsonb, 'Sannolikheten att den inte är sen är 1 − 0,1 = 0,9 varje dag. Båda dagarna: 0,9 · 0,9 = 0,81.'),
  ('f93706c1-111a-550d-8b43-8071abad2986', '912f706e-1ab2-558f-9eb2-734dce630894', 5, 'val', 'Du slår en tärning tre gånger. Vilket uttryck ger sannolikheten att få minst en sexa?', '["1 − (5/6)³","3 · 1/6","(1/6)³","1 − (1/6)³"]'::jsonb, '0'::jsonb, 'Minst en sexa är motsatsen till ingen sexa alls. Ingen sexa på tre slag har sannolikheten (5/6)³, så svaret är 1 − (5/6)³.'),
  ('f7887336-b58c-5995-bbf5-b73c8a812808', '912f706e-1ab2-558f-9eb2-734dce630894', 6, 'val', 'Sannolikheten att vinna ett spel är 0,3. Spelen påverkar inte varandra. Hur stor är sannolikheten att vinna två gånger i rad?', '["0,09","0,6","0,3","0,49"]'::jsonb, '0'::jsonb, 'Två oberoende händelser: 0,3 · 0,3 = 0,09.'),
  ('067e6a87-cb57-5912-9dfd-fd3cfbb6523b', '912f706e-1ab2-558f-9eb2-734dce630894', 7, 'skriv', 'En kortlek har 52 kort, och 13 av dem är hjärter. Du drar ett kort utan att titta. Hur stor är sannolikheten att det är ett hjärter? Svara som bråk.', null, '["1/4","1 / 4","13/52","13 / 52","0,25"]'::jsonb, '13 av 52 kort är hjärter. 13/52 = 1/4.'),
  ('bb497159-c9f5-5f42-b1de-93d8ec4ad754', '912f706e-1ab2-558f-9eb2-734dce630894', 8, 'ordna', 'Ordna händelserna från minst till mest sannolik.', null, '["Två sexor på två tärningar","Krona tre gånger i rad","En sexa på en tärning","Krona på ett slantsingel"]'::jsonb, 'Sannolikheterna är 1/36 för två sexor, 1/8 för tre kronor, 1/6 för en sexa och 1/2 för en krona.'),
  ('21ba2e75-a5f9-576d-afdb-85d351004d69', '23349650-3d72-5f33-9812-422b22c05984', 1, 'val', 'Vilket tal kommer precis efter 12?', '["11","13","14"]'::jsonb, '1'::jsonb, 'När man räknar uppåt kommer 13 direkt efter 12.'),
  ('e4351d51-17e8-5a6d-8da0-520dd6e41d53', '23349650-3d72-5f33-9812-422b22c05984', 2, 'val', 'Vilket tal kommer precis före 10?', '["9","11","8"]'::jsonb, '0'::jsonb, 'Talet före är ett mindre. 10 − 1 = 9.'),
  ('4a36b6c1-e60c-52b2-98d9-3a87619b51df', '23349650-3d72-5f33-9812-422b22c05984', 3, 'skriv', 'Räkna vidare: 5, 6, 7, 8. Vilket tal kommer sedan?', null, '["9","nio"]'::jsonb, 'Varje tal är ett mer än talet före. Efter 8 kommer 9.'),
  ('16a9d262-d285-516d-ab69-86376cc8d9ca', '23349650-3d72-5f33-9812-422b22c05984', 4, 'val', 'Vilket tal är störst?', '["15","19","12","17"]'::jsonb, '1'::jsonb, 'Alla talen har ett tiotal. 19 har flest ental, 9 stycken, så 19 är störst.'),
  ('3787e02c-4b0b-584f-b371-d21cc1ef81c8', '23349650-3d72-5f33-9812-422b22c05984', 5, 'val', 'Vilket tal är minst?', '["14","4","11","20"]'::jsonb, '1'::jsonb, 'Talet 4 har inget tiotal, bara 4 ental. De andra talen är 10 eller mer.'),
  ('a8d4c3a5-13a4-5b1c-a698-644a1effc90d', '23349650-3d72-5f33-9812-422b22c05984', 6, 'skriv', 'Vilket tal står mitt emellan 6 och 8?', null, '["7","sju"]'::jsonb, 'Räkna 6, 7, 8. Talet 7 står i mitten.'),
  ('b694110f-09b6-5a7a-8e0f-ed3462ccadbf', '23349650-3d72-5f33-9812-422b22c05984', 7, 'ordna', 'Ordna talen från minst till störst.', null, '["3","8","11","16"]'::jsonb, 'Börja med det minsta talet, 3. Sedan kommer 8, 11 och sist 16.'),
  ('b2506ec3-e7f2-511b-b051-806cd0f731e7', '23349650-3d72-5f33-9812-422b22c05984', 8, 'skriv', 'Talet 14 är 1 tiotal och några ental. Hur många ental?', null, '["4","fyra","fyra ental"]'::jsonb, 'Talet 14 är 10 + 4. Det är 1 tiotal och 4 ental.'),
