  ('9aec3583-972c-56fd-a195-78198ae74d9e', 'b95b2ed1-c27e-503f-b688-42ec5d5a7af1', 3, 'val', 'Vilka två tal är tiokamrater?', '["5 och 5","4 och 5","6 och 3","2 och 7"]'::jsonb, '0'::jsonb, '5 + 5 = 10. De andra paren blir bara 9.'),
  ('ef058712-532d-54f0-ba10-5ed4833922ba', 'b95b2ed1-c27e-503f-b688-42ec5d5a7af1', 4, 'skriv', 'I en skål ligger 10 äpplen. Du tar 2. Hur många äpplen ligger kvar?', null, '["8","åtta","åtta äpplen"]'::jsonb, '2 och 8 är tiokamrater. Tar du 2 av 10 blir 8 kvar.'),
  ('d51a6d70-fc2e-5857-a997-d029f28fd218', 'b95b2ed1-c27e-503f-b688-42ec5d5a7af1', 5, 'val', 'Vad är 10 − 4?', '["6","4","14","5"]'::jsonb, '0'::jsonb, '4 och 6 är tiokamrater. Tar du bort 4 från 10 blir 6 kvar.'),
  ('1cfbb505-d439-526f-ac8d-cca469be52ef', 'b95b2ed1-c27e-503f-b688-42ec5d5a7af1', 6, 'skriv', 'Du har 3 kulor. Hur många kulor till behöver du för att ha 10?', null, '["7","sju","sju kulor"]'::jsonb, '3 och 7 är tiokamrater, för 3 + 7 = 10.'),
  ('aded8544-f39c-583b-aa81-28f198130e0f', 'b95b2ed1-c27e-503f-b688-42ec5d5a7af1', 7, 'ordna', 'Ordna så att svaren går från minst till störst.', null, '["10 − 8","10 − 5","10 − 3"]'::jsonb, '10 − 8 = 2, 10 − 5 = 5 och 10 − 3 = 7. Ju mer man tar bort, desto mindre blir kvar.'),
  ('51d5824d-b37f-54a4-9a43-7ecfcb40562c', 'b95b2ed1-c27e-503f-b688-42ec5d5a7af1', 8, 'val', 'Sara har 10 kronor. En glass kostar 9 kronor. Hur många kronor har hon kvar när hon köpt glassen?', '["1","9","19","2"]'::jsonb, '0'::jsonb, '9 och 1 är tiokamrater. 10 − 9 = 1.'),
  ('4e0878c0-4839-5456-b5c9-dacd99c06304', '161ba36b-364b-5db5-a9ec-33c06ceddcef', 1, 'skriv', 'Vad är 8 + 5?', null, '["13","tretton"]'::jsonb, 'Ta 2 av femman och gör 8 till 10. Sedan 10 + 3 = 13.'),
  ('a7b37f43-ece5-57eb-80c2-9e7bad606e93', '161ba36b-364b-5db5-a9ec-33c06ceddcef', 2, 'val', 'Vad är 15 − 4?', '["11","19","10","12"]'::jsonb, '0'::jsonb, 'Ta bort 4 ental från 15. 5 − 4 = 1, så svaret är 11.'),
  ('0e8af0ab-d50c-57ff-b64f-1897ac60f06f', '161ba36b-364b-5db5-a9ec-33c06ceddcef', 3, 'skriv', 'Emil har 9 kulor. Han får 6 till. Hur många kulor har han nu?', null, '["15","femton","femton kulor"]'::jsonb, 'Han får fler, så det är plus. 9 + 1 = 10, och 5 till blir 15.'),
  ('e45da948-1437-5edf-afae-c3aa3ac35dd1', '161ba36b-364b-5db5-a9ec-33c06ceddcef', 4, 'val', 'Vad är 12 − 5?', '["7","8","17","6"]'::jsonb, '0'::jsonb, 'Ta först bort 2, då blir det 10. Sedan 3 till: 10 − 3 = 7.'),
