  ('b3065fe4-ffe5-55a5-83e4-37e56132b59c', '5733d615-e58e-52b9-96e6-41a28aac6d58', 3, 'skriv', '6 barn delar lika på 29 kulor. Hur många kulor får varje barn?', null, '["4"]'::jsonb, '6 · 4 = 24, men 6 · 5 = 30 är för mycket. Varje barn får 4 kulor och 5 blir över.'),
  ('0fdc8240-7c07-543a-8cc5-3944755f5755', '5733d615-e58e-52b9-96e6-41a28aac6d58', 4, 'val', 'Vilken rest är omöjlig när man delar med 4?', '["0","1","3","4"]'::jsonb, '3'::jsonb, 'Resten måste alltid vara mindre än talet man delar med. Blir 4 över räcker det till en fyra till.'),
  ('54127854-13f8-5e4c-b7b9-182a551cfbd7', '5733d615-e58e-52b9-96e6-41a28aac6d58', 5, 'val', '30 elever ska åka bil. I varje bil får 4 elever plats. Hur många bilar behövs?', '["2","7","8"]'::jsonb, '2'::jsonb, '30 / 4 = 7 rest 2. Sju bilar räcker till 28 elever, och de 2 som är kvar behöver en bil till.'),
  ('94e287d8-fd35-5209-99eb-116247dada7b', '5733d615-e58e-52b9-96e6-41a28aac6d58', 6, 'skriv', '50 pennor läggs i askar med 8 pennor i varje. Hur många askar blir helt fulla?', null, '["6"]'::jsonb, '8 · 6 = 48, men 8 · 7 = 56 är för mycket. 6 askar blir fulla och 2 pennor blir över.'),
  ('7982789c-95c4-57b9-87e7-49e04f5857fb', '5733d615-e58e-52b9-96e6-41a28aac6d58', 7, 'ordna', 'Ordna divisionerna efter hur stor resten blir, minst rest först.', null, '["13 / 4","20 / 6","17 / 7","14 / 5"]'::jsonb, '13 / 4 = 3 rest 1, 20 / 6 = 3 rest 2, 17 / 7 = 2 rest 3 och 14 / 5 = 2 rest 4.'),
  ('ed002cc4-617b-532d-9f9e-a33ba60ee1f9', '5733d615-e58e-52b9-96e6-41a28aac6d58', 8, 'val', 'Vilken division går jämnt ut, utan rest?', '["36 / 5","42 / 8","45 / 9","50 / 7"]'::jsonb, '2'::jsonb, '9 · 5 = 45, så 45 / 9 = 5 och ingenting blir över.'),
