  ('b4660704-3163-500c-aab2-7ba9c564b515', 'f455fce2-09c8-5e2f-93b7-7b8bc4675d4b', 2, 'skriv', 'Hur många tiondelar är 1,3?', null, '["13"]'::jsonb, 'En hel är 10 tiondelar. 10 + 3 = 13 tiondelar.'),
  ('fc5e7d40-53f4-5bbf-a8f2-92bddc515e22', 'f455fce2-09c8-5e2f-93b7-7b8bc4675d4b', 3, 'val', 'Vilket tal är störst?', '["0,8","1,1","0,9","1,0"]'::jsonb, '1'::jsonb, '1,1 är en hel och en tiondel till. De andra talen är högst en hel.'),
  ('fe6232aa-4ba9-5f4e-ac41-c15c5a67ed6e', 'f455fce2-09c8-5e2f-93b7-7b8bc4675d4b', 4, 'skriv', 'Vad är 0,6 + 0,5?', null, '["1,1"]'::jsonb, '6 tiondelar + 5 tiondelar = 11 tiondelar. Det är en hel och en tiondel: 1,1.'),
  ('59f4731e-63bf-51ac-b77a-e05f683f2bb1', 'f455fce2-09c8-5e2f-93b7-7b8bc4675d4b', 5, 'val', 'Vilket tal ligger mitt emellan 2 och 3 på tallinjen?', '["2,5","2,2","2,05","25"]'::jsonb, '0'::jsonb, 'Mellan 2 och 3 finns tio tiondelar. Mitten är efter fem av dem: 2,5.'),
  ('dd1547bd-1814-5612-9898-f27279ed29e5', 'f455fce2-09c8-5e2f-93b7-7b8bc4675d4b', 6, 'skriv', 'Ett band är 1 meter långt. Du klipper av 0,4 meter. Hur många meter är kvar?', null, '["0,6"]'::jsonb, '1 meter är 10 tiondelar. 10 − 4 = 6 tiondelar, alltså 0,6 meter.'),
  ('63ce49a3-834d-54ae-8883-7c46062e2aa7', 'f455fce2-09c8-5e2f-93b7-7b8bc4675d4b', 7, 'ordna', 'Ordna talen från minst till störst.', null, '["0,3","0,8","1,2","1,7","2,1"]'::jsonb, 'Titta först på talet före kommat. Är det lika, jämför tiondelarna efter kommat.'),
  ('d2c4478c-f775-5640-ab5f-9d4b890cc284', 'f455fce2-09c8-5e2f-93b7-7b8bc4675d4b', 8, 'val', 'Vad är 0,3 + 0,7?', '["0,10","0,37","1"]'::jsonb, '2'::jsonb, '3 tiondelar + 7 tiondelar = 10 tiondelar. Tio tiondelar är en hel, alltså 1.'),
