  ('b28357c2-4347-5714-a0ec-ab25dbe63989', '8064cbec-fe30-5236-b5b2-967ec31a23bd', 2, 'skriv', 'En rektangel är 6 cm lång och 4 cm bred. Hur många centimeter är omkretsen?', null, '["20"]'::jsonb, 'Lägg ihop alla fyra sidor: 6 + 4 + 6 + 4 = 20 cm.'),
