  ('fb0c8127-6dfe-5b60-a4d0-a473b7956428', 'ce0af2bd-779c-5fca-9f05-d7fe79bfca86', 3, 'val', 'Klockan är 9.45. Vad är klockan om 30 minuter?', '["9.75","10.05","10.15","10.45"]'::jsonb, '2'::jsonb, 'Om 15 minuter är klockan 10.00, och 15 minuter till blir 10.15. En timme har 60 minuter, inte 100.'),
