  ('b3055ec7-58f8-50b4-b2df-026c69b6a064', 'ce0af2bd-779c-5fca-9f05-d7fe79bfca86', 8, 'val', 'Ett lag tränar 45 minuter tre gånger i veckan. Hur länge tränar de sammanlagt?', '["1 timme och 35 minuter","2 timmar","2 timmar och 15 minuter","2 timmar och 45 minuter"]'::jsonb, '2'::jsonb, '3 · 45 = 135 minuter. 120 minuter är 2 timmar, och 15 minuter blir kvar.'),
  ('3c03142d-7c26-52c6-847f-1b3fe9bb9bdf', '0b942b79-2562-56d2-9bad-756f5f0717a9', 1, 'val', 'En chokladkaka har 12 rutor. Du äter 5. Hur stor del av kakan har du ätit?', '["5/12","7/12","12/5","5/7"]'::jsonb, '0'::jsonb, 'Kakan har 12 lika stora rutor och 5 av dem är uppätna. Det är 5/12.'),
  ('c5346627-e351-53df-a13d-f55af5636dde', '0b942b79-2562-56d2-9bad-756f5f0717a9', 2, 'skriv', 'Vad är 1/3 av 18?', null, '["6"]'::jsonb, 'En tredjedel är en av tre lika delar. 18 / 3 = 6.'),
  ('653513f7-4a38-5588-ac97-c533ed5cd71c', '0b942b79-2562-56d2-9bad-756f5f0717a9', 3, 'val', 'Vad visar nämnaren, talet under strecket, i bråket 3/5?', '["Hur många lika delar helheten är delad i","Hur många delar man tar","Hur många helheter det finns"]'::jsonb, '0'::jsonb, 'I 3/5 är helheten delad i 5 lika delar, och man tar 3 av dem. Talet över strecket heter täljare.'),
  ('f1f57d06-3d44-5dee-ba5b-5c50ca9ed77a', '0b942b79-2562-56d2-9bad-756f5f0717a9', 4, 'skriv', 'Vad är 3/4 av 20?', null, '["15"]'::jsonb, 'Först 1/4 av 20: 20 / 4 = 5. Tre fjärdedelar är 3 · 5 = 15.'),
  ('48ef250f-2d28-5c45-ba50-e0037cfed69a', '0b942b79-2562-56d2-9bad-756f5f0717a9', 5, 'val', 'I en klass går 24 elever. 1/4 av dem cyklar till skolan. Hur många cyklar?', '["4","6","8","20"]'::jsonb, '1'::jsonb, '1/4 betyder en av fyra lika delar. 24 / 4 = 6 elever.'),
  ('cfb7d360-9bab-5603-96d2-158470441413', '0b942b79-2562-56d2-9bad-756f5f0717a9', 6, 'skriv', 'Hur många femtedelar behövs för att få en hel?', null, '["5"]'::jsonb, 'Delar du en hel i fem lika delar får du fem femtedelar: 5/5 = 1.'),
  ('273560c3-f789-5d77-92a9-4afe2da2f768', '0b942b79-2562-56d2-9bad-756f5f0717a9', 7, 'ordna', 'Ordna bråken från minst till störst.', null, '["1/10","1/5","1/3","1/2"]'::jsonb, 'När täljaren är 1 gäller: ju större nämnare, desto mindre bit. En tiondel är minst och en halv störst.'),
  ('53cfad26-7fa8-5ce0-8edd-0c378836254b', '0b942b79-2562-56d2-9bad-756f5f0717a9', 8, 'val', 'Hur stor del av en timme är 15 minuter?', '["1/4","1/15","1/3","15/100"]'::jsonb, '0'::jsonb, 'En timme är 60 minuter. 60 / 15 = 4, så 15 minuter är en fjärdedel av timmen.'),
  ('dab51721-57a3-5412-8cba-03cc1718a46e', '0e92544d-c44d-5791-914b-8a8ba5c5c7c1', 1, 'val', 'Vilket bråk är lika stort som 1/2?', '["3/6","2/3","1/4","3/5"]'::jsonb, '0'::jsonb, '3 är hälften av 6, så 3/6 är samma sak som 1/2.'),
