  ('ba636edb-7796-5b8c-b375-8ac5974500fc', '0e92544d-c44d-5791-914b-8a8ba5c5c7c1', 3, 'val', 'Vilket bråk är störst?', '["3/8","3/4","3/5","3/10"]'::jsonb, '1'::jsonb, 'Alla har täljaren 3. Fjärdedelar är större bitar än femtedelar, åttondelar och tiondelar.'),
  ('09b4360c-5b57-5cdc-b644-1f9692f8ef05', '0e92544d-c44d-5791-914b-8a8ba5c5c7c1', 4, 'skriv', 'Vilket tal saknas? 3/4 = ?/12', null, '["9"]'::jsonb, '4 · 3 = 12, så täljaren ska också gånger 3: 3 · 3 = 9.'),
  ('b9fc0a85-0c8f-5f56-b00d-40049cfe9bc8', '0e92544d-c44d-5791-914b-8a8ba5c5c7c1', 5, 'val', 'Vilket är störst, 2/3 eller 3/4?', '["2/3","3/4","De är lika stora"]'::jsonb, '1'::jsonb, 'Gör om till tolftedelar: 2/3 = 8/12 och 3/4 = 9/12. 9/12 är störst.'),
