  ('d33c66c3-18c5-5dee-a09b-8452fdf115b6', '0e92544d-c44d-5791-914b-8a8ba5c5c7c1', 7, 'ordna', 'Ordna bråken från minst till störst.', null, '["1/3","1/2","2/3","5/6"]'::jsonb, 'Gör om till sjättedelar: 1/3 = 2/6, 1/2 = 3/6 och 2/3 = 4/6. Störst är 5/6.'),
  ('57afc1e0-936f-5372-8bd1-c6e4b30febed', '0e92544d-c44d-5791-914b-8a8ba5c5c7c1', 8, 'skriv', 'Vilket tal saknas? 2/5 = 6/?', null, '["15"]'::jsonb, 'Täljaren har blivit 3 gånger så stor, 2 · 3 = 6. Då ska nämnaren också gånger 3: 5 · 3 = 15.'),
  ('17e60976-6081-55ab-8e6a-70159eb58a05', '482fc290-94ab-58a9-8cd3-d49596cd063f', 1, 'val', 'Vilket tal är störst?', '["0,5","0,45","0,39","0,09"]'::jsonb, '0'::jsonb, '0,5 är samma som 0,50. 50 hundradelar är mer än 45 hundradelar.'),
  ('9795360d-901e-5580-b765-c183fa63aa53', '482fc290-94ab-58a9-8cd3-d49596cd063f', 2, 'skriv', 'Hur skrivs 7 hundradelar som decimaltal?', null, '["0,07"]'::jsonb, 'Andra siffran efter kommat visar hundradelar. Därför skrivs 7 hundradelar 0,07.'),
  ('f9bf2327-1e1f-5ae7-8219-f010437092d2', '482fc290-94ab-58a9-8cd3-d49596cd063f', 3, 'val', 'Avrunda 3,47 till en decimal.', '["3,4","3,5","3,47","4"]'::jsonb, '1'::jsonb, 'Titta på hundradelssiffran: 7. Den är 5 eller mer, så vi avrundar uppåt till 3,5.'),
  ('ecd7b42e-0d47-5718-8fc4-3b778789bf12', '482fc290-94ab-58a9-8cd3-d49596cd063f', 4, 'skriv', 'Avrunda 12,38 till ett heltal.', null, '["12"]'::jsonb, 'Titta på tiondelssiffran: 3. Den är mindre än 5, så vi avrundar nedåt till 12.'),
  ('7e137405-fe9a-5096-80a0-14362e9b471a', '482fc290-94ab-58a9-8cd3-d49596cd063f', 5, 'val', 'En glass kostar 12,50 kr och en läsk 8,75 kr. Vad kostar de tillsammans?', '["20,25 kr","21,15 kr","21,25 kr","22,25 kr"]'::jsonb, '2'::jsonb, '12 + 8 = 20 kronor och 50 + 75 = 125 öre, som är 1,25 kr. 20 + 1,25 = 21,25 kr.'),
  ('44661551-7484-5670-98d2-7d4bfaf657fc', '482fc290-94ab-58a9-8cd3-d49596cd063f', 6, 'skriv', 'Vad är 1 − 0,35?', null, '["0,65"]'::jsonb, '1 är 100 hundradelar. 100 − 35 = 65 hundradelar, alltså 0,65.'),
  ('8418555d-d4f5-5b15-a359-e31a2c969b17', '482fc290-94ab-58a9-8cd3-d49596cd063f', 7, 'ordna', 'Ordna talen från minst till störst.', null, '["0,08","0,3","0,35","0,53","0,8"]'::jsonb, 'Skriv alla med två decimaler: 0,08, 0,30, 0,35, 0,53 och 0,80. Då är de lätta att jämföra.'),
  ('3878c1c2-e8da-5e3f-a678-14c979f0225d', '482fc290-94ab-58a9-8cd3-d49596cd063f', 8, 'val', 'Vilket tal ligger mellan 2,4 och 2,5?', '["2,45","2,54","2,39","2,6"]'::jsonb, '0'::jsonb, '2,4 är samma som 2,40 och 2,5 är samma som 2,50. 2,45 ligger mellan dem.'),
  ('9a8d9311-a722-5f86-8b0f-8c1e775a00b5', '6475e833-bdf3-5b7a-954f-3e6791648644', 1, 'val', 'Hur räknar man ut medelvärdet av några tal?', '["Lägg ihop talen och dela med hur många de är","Ta det största talet minus det minsta","Ta talet som står i mitten","Ta talet som finns flest gånger"]'::jsonb, '0'::jsonb, 'Medelvärdet är vad varje tal blir om man delar summan lika. Därför delar man summan med antalet tal.'),
  ('02635ad0-8e3c-57cd-a567-8f064e7fd6a8', '6475e833-bdf3-5b7a-954f-3e6791648644', 2, 'skriv', 'Vad är medelvärdet av 4, 6 och 8?', null, '["6"]'::jsonb, '4 + 6 + 8 = 18. Det är 3 tal, så 18 / 3 = 6.'),
  ('53dc2101-b4ef-5070-a1bd-a05a8437be76', '6475e833-bdf3-5b7a-954f-3e6791648644', 3, 'skriv', 'Fyra barn har 3, 5, 9 och 11 kulor. Vad är medelvärdet?', null, '["7"]'::jsonb, '3 + 5 + 9 + 11 = 28 kulor. Delat på 4 barn blir det 28 / 4 = 7.'),
  ('d223c5cc-9f92-503c-be2b-f14fb364779a', '6475e833-bdf3-5b7a-954f-3e6791648644', 4, 'val', 'Ella fick 7, 9 och 8 poäng i tre omgångar. Vad är medelvärdet?', '["7","8","9","24"]'::jsonb, '1'::jsonb, '7 + 9 + 8 = 24 poäng. 24 / 3 = 8.'),
  ('fc913fd1-7ca0-56bc-bb72-42a1e394dedf', '6475e833-bdf3-5b7a-954f-3e6791648644', 5, 'val', 'Medelvärdet av två tal är 10. Det ena talet är 6. Vilket är det andra?', '["4","10","14","16"]'::jsonb, '2'::jsonb, 'Två tal med medelvärdet 10 har summan 2 · 10 = 20. 20 − 6 = 14.'),
  ('2558185c-a81d-5c5b-babb-2b244f295053', '6475e833-bdf3-5b7a-954f-3e6791648644', 6, 'skriv', 'Det var 12, 15, 14 och 11 grader fyra dagar i rad. Hur många grader var medeltemperaturen?', null, '["13"]'::jsonb, '12 + 15 + 14 + 11 = 52. 52 / 4 = 13 grader.'),
  ('b7e14c0b-d814-5e77-8851-fd892f773fc9', '6475e833-bdf3-5b7a-954f-3e6791648644', 7, 'ordna', 'Ordna stegen när du räknar ut medelvärdet av 5, 7 och 9. En bricka blir över.', '["21 · 3 = 63"]'::jsonb, '["5 + 7 + 9 = 21","21 / 3 = 7","Medelvärdet är 7"]'::jsonb, 'Först lägger man ihop talen. Sedan delar man summan med antalet tal: 21 / 3 = 7.'),
  ('a7f43462-1de0-5656-8a82-5d86a21ee371', '6475e833-bdf3-5b7a-954f-3e6791648644', 8, 'val', 'Tre tal har medelvärdet 5. Vilka kan talen vara?', '["2, 5 och 8","5, 5 och 6","3, 4 och 5","1, 5 och 10"]'::jsonb, '0'::jsonb, 'Tre tal med medelvärdet 5 har summan 3 · 5 = 15. Bara 2 + 5 + 8 blir 15.'),
  ('32fc7716-63dd-53f5-ae29-10ccbffcc9ae', 'a7dc92ff-7558-5d19-beee-39376f61272c', 1, 'val', 'Vilket tal är minst?', '["−2","−7","0","3"]'::jsonb, '1'::jsonb, 'På tallinjen ligger −7 längst till vänster. Ju längre åt vänster, desto mindre är talet.'),
  ('f317ac5d-68a9-51c1-b6e4-d15b6941a256', 'a7dc92ff-7558-5d19-beee-39376f61272c', 2, 'skriv', 'Det är 3 grader varmt. Temperaturen sjunker 5 grader. Hur många grader är det nu?', null, '["−2","− 2","minus 2","minus två","minus 2 grader","minus två grader","2 minusgrader","två minusgrader","2 grader kallt","två grader kallt"]'::jsonb, 'Från 3 ner till 0 är 3 grader. Sedan 2 grader till under noll: −2 grader.'),
  ('74418092-ea00-57ab-922e-810a388af547', 'a7dc92ff-7558-5d19-beee-39376f61272c', 3, 'val', 'Det är −4 grader. Det blir 6 grader varmare. Hur varmt är det nu?', '["2 grader","−2 grader","10 grader","−10 grader"]'::jsonb, '0'::jsonb, 'Från −4 upp till 0 är 4 grader. 2 grader till gör att det blir 2 grader varmt.'),
  ('68c0a564-f4b8-5eeb-8426-da68176b2f35', 'a7dc92ff-7558-5d19-beee-39376f61272c', 4, 'skriv', 'Hur många grader skiljer det mellan −3 grader och 5 grader?', null, '["8"]'::jsonb, 'Från −3 till 0 är 3 grader och från 0 till 5 är 5 grader. 3 + 5 = 8.'),
  ('8d916b8f-455e-50db-8aab-b0a86d74b22f', 'a7dc92ff-7558-5d19-beee-39376f61272c', 5, 'val', 'Vilket tal ligger mitt emellan −4 och 2 på tallinjen?', '["−3","−2","−1","1"]'::jsonb, '2'::jsonb, 'Från −4 till 2 är det 6 steg. Hälften är 3 steg: −4 + 3 = −1.'),
  ('a131efac-ddcd-5d64-8d1b-71c0fa8c153c', 'a7dc92ff-7558-5d19-beee-39376f61272c', 6, 'skriv', 'Vad är 2 − 6?', null, '["−4","− 4","minus 4","minus fyra"]'::jsonb, 'Gå 6 steg åt vänster från 2 på tallinjen: 1, 0, −1, −2, −3, −4.'),
  ('8b866c38-59be-55ce-bc10-807071c22164', 'a7dc92ff-7558-5d19-beee-39376f61272c', 7, 'ordna', 'Ordna temperaturerna från kallast till varmast.', null, '["−9 grader","−5 grader","−3 grader","0 grader","4 grader"]'::jsonb, 'Ju längre under noll, desto kallare. −9 grader är kallast och 4 grader varmast.'),
  ('78adad91-eaaa-5b99-a2ee-4a358bf58bbc', 'a7dc92ff-7558-5d19-beee-39376f61272c', 8, 'val', 'Vilket stämmer?', '["−5 är mindre än −2","−5 är större än −2","−5 och −2 är lika stora"]'::jsonb, '0'::jsonb, '−5 ligger längre till vänster på tallinjen än −2. Det är också kallare när det är −5 grader.'),
  ('3ce8bc11-4971-560b-ae9e-2858f6ef026a', 'ad4ae54b-09b2-5df3-af94-1203c2a69541', 1, 'val', 'Hur mycket är 1 %?', '["En hundradel","En tiondel","En tusendel","En hel"]'::jsonb, '0'::jsonb, 'Procent betyder "av hundra". 1 % är alltså en hundradel av något.'),
  ('f289a0e4-9085-512a-80ec-3fd6367ec664', 'ad4ae54b-09b2-5df3-af94-1203c2a69541', 2, 'skriv', 'Vad är 50 % av 80?', null, '["40"]'::jsonb, '50 % är hälften. Hälften av 80 är 40.'),
  ('3356c317-a896-5a47-bf24-0e2034a93644', 'ad4ae54b-09b2-5df3-af94-1203c2a69541', 3, 'val', 'Vad är 25 % av 60?', '["15","25","30","35"]'::jsonb, '0'::jsonb, '25 % är en fjärdedel. 60 / 4 = 15.'),
  ('53a54c75-5630-55f2-aa1f-19f66d29b173', 'ad4ae54b-09b2-5df3-af94-1203c2a69541', 4, 'skriv', 'Vad är 10 % av 350?', null, '["35"]'::jsonb, '10 % är en tiondel. 350 / 10 = 35.'),
  ('2a3a16a3-6902-56b9-abd1-f68a60f2d223', 'ad4ae54b-09b2-5df3-af94-1203c2a69541', 5, 'val', 'En tröja kostar 200 kr. Den säljs med 25 % rabatt. Hur mycket billigare blir den?', '["25 kr","50 kr","150 kr","175 kr"]'::jsonb, '1'::jsonb, '25 % är en fjärdedel av priset. 200 / 4 = 50 kr billigare.'),
  ('613d40f5-85bc-55c1-8236-a5ff223d324d', 'ad4ae54b-09b2-5df3-af94-1203c2a69541', 6, 'skriv', 'I en klass går 20 elever. 10 % av dem är sjuka. Hur många elever är sjuka?', null, '["2"]'::jsonb, '10 % är en tiondel. 20 / 10 = 2 elever.'),
  ('1e059c4d-69fc-5739-bdff-9b75c39b5cc9', 'ad4ae54b-09b2-5df3-af94-1203c2a69541', 7, 'ordna', 'Ordna från minst till störst.', null, '["10 % av 100","25 % av 80","50 % av 50","10 % av 300"]'::jsonb, '10 % av 100 = 10, 25 % av 80 = 20, 50 % av 50 = 25 och 10 % av 300 = 30.'),
  ('048653a4-8529-50a3-90cc-314e75dfd101', 'ad4ae54b-09b2-5df3-af94-1203c2a69541', 8, 'val', 'Hur många procent är det hela?', '["1 %","10 %","50 %","100 %"]'::jsonb, '3'::jsonb, 'Det hela är 100 hundradelar. Därför är det hela 100 %.'),
  ('b1cafd3c-0cda-5e5d-bd36-0d90c19aeca4', '46412c4e-cafe-5708-9adb-dcffa619fce9', 1, 'val', 'Hur skrivs 1/4 i procent?', '["4 %","14 %","25 %","40 %"]'::jsonb, '2'::jsonb, '1/4 = 25/100, och 25 hundradelar är 25 %.'),
  ('d9e5bdd1-6757-5742-8133-acce1c5a1224', '46412c4e-cafe-5708-9adb-dcffa619fce9', 2, 'skriv', 'Hur många procent är 0,3?', null, '["30"]'::jsonb, '0,3 är samma som 0,30, alltså 30 hundradelar. Det är 30 %.'),
  ('049936b9-2d07-5eb3-9768-833a52e51f53', '46412c4e-cafe-5708-9adb-dcffa619fce9', 3, 'val', 'Vilket decimaltal är lika mycket som 75 %?', '["0,075","0,75","7,5","75"]'::jsonb, '1'::jsonb, '75 % är 75 hundradelar, och det skrivs 0,75.'),
  ('9be14d04-1811-53be-91cc-beb21b0db76e', '46412c4e-cafe-5708-9adb-dcffa619fce9', 4, 'skriv', 'Hur många procent är 1/2?', null, '["50"]'::jsonb, '1/2 = 50/100. Hälften är alltså 50 %.'),
  ('36ee3237-af6f-57c4-9f98-38bebeeae19a', '46412c4e-cafe-5708-9adb-dcffa619fce9', 5, 'val', 'Vilket bråk är lika mycket som 20 %?', '["1/5","1/20","1/2","2/5"]'::jsonb, '0'::jsonb, '20 % = 20/100. Dela både täljaren och nämnaren med 20 så får du 1/5.'),
  ('85379b90-9cdb-58a3-88b7-d9c8b00e7d75', '46412c4e-cafe-5708-9adb-dcffa619fce9', 6, 'skriv', 'Hur många procent är 0,05?', null, '["5"]'::jsonb, '0,05 är 5 hundradelar, alltså 5 %. Inte 50 %, för då hade det stått 0,50.'),
  ('99286ff5-6685-5c3f-9a60-2cd3f1faaf93', '46412c4e-cafe-5708-9adb-dcffa619fce9', 7, 'ordna', 'Ordna från minst till störst.', null, '["0,2","1/4","30 %","0,5","3/4"]'::jsonb, 'Gör om allt till procent: 0,2 = 20 %, 1/4 = 25 %, 30 %, 0,5 = 50 % och 3/4 = 75 %.'),
  ('16cbb6c9-c1f1-595d-8ece-9f431594b864', '46412c4e-cafe-5708-9adb-dcffa619fce9', 8, 'val', 'Vilket är INTE lika mycket som de andra?', '["1/2","0,5","50 %","5 %"]'::jsonb, '3'::jsonb, '1/2, 0,5 och 50 % är alla hälften. 5 % är bara fem hundradelar.'),
  ('69a2a710-88d2-54b7-841d-cfa4cc9dcb41', '73c73990-09ec-5bbc-8bed-b2502c7eaf84', 1, 'val', 'Vilken punkt har x-koordinaten 3 och y-koordinaten 5?', '["(3, 5)","(5, 3)","(3, 3)","(5, 5)"]'::jsonb, '0'::jsonb, 'En punkt skrivs (x, y), med x-koordinaten först. Därför är det (3, 5).'),
  ('a66a9772-12b9-5cde-82d5-0c9f81daf859', '73c73990-09ec-5bbc-8bed-b2502c7eaf84', 2, 'skriv', 'Vad kallas punkten (0, 0), där axlarna möts?', null, '["origo","nollpunkten"]'::jsonb, 'Punkten (0, 0) där x-axeln och y-axeln korsar varandra kallas origo.'),
  ('fa6dbcc4-acef-58bc-928b-64ad9b9b2920', '73c73990-09ec-5bbc-8bed-b2502c7eaf84', 3, 'val', 'Hur kommer du från origo till punkten (4, 2)?', '["4 steg åt höger och 2 steg uppåt","2 steg åt höger och 4 steg uppåt","4 steg uppåt och 2 steg åt vänster","4 steg åt vänster och 2 steg nedåt"]'::jsonb, '0'::jsonb, 'x-koordinaten 4 säger hur långt åt höger, och y-koordinaten 2 hur långt uppåt.'),
  ('1bcd76c8-f691-5866-911e-586495af571d', '73c73990-09ec-5bbc-8bed-b2502c7eaf84', 4, 'skriv', 'Du står i punkten (2, 3) och går 4 steg åt höger. Vilken x-koordinat har du nu?', null, '["6"]'::jsonb, 'Går du åt höger ändras bara x-koordinaten: 2 + 4 = 6. y-koordinaten är kvar på 3.'),
  ('e57fc422-0421-5239-affc-592e5074d012', '73c73990-09ec-5bbc-8bed-b2502c7eaf84', 5, 'val', 'Vilken punkt ligger på x-axeln?', '["(5, 0)","(0, 5)","(5, 5)","(1, 5)"]'::jsonb, '0'::jsonb, 'På x-axeln är y-koordinaten 0. Därför ligger (5, 0) på x-axeln, men (0, 5) på y-axeln.'),
  ('2d98322f-8179-5d3d-931e-3a390c29f647', '73c73990-09ec-5bbc-8bed-b2502c7eaf84', 6, 'skriv', 'Hur många steg är det mellan punkterna (1, 1) och (6, 1)?', null, '["5"]'::jsonb, 'Punkterna har samma y-koordinat, så de ligger på samma höjd. 6 − 1 = 5 steg.'),
  ('9fa87b46-1ec9-533d-b35e-3512d081e6ad', '73c73990-09ec-5bbc-8bed-b2502c7eaf84', 7, 'ordna', 'Ordna punkterna från den som ligger längst till vänster till den som ligger längst till höger.', null, '["(0, 4)","(2, 7)","(4, 4)","(6, 1)","(9, 3)"]'::jsonb, 'Hur långt åt höger en punkt ligger visas av x-koordinaten, det första talet. Ordna efter den: 0, 2, 4, 6 och 9.'),
  ('e23433b2-760c-58ef-ad5c-bfdae9c50f24', '73c73990-09ec-5bbc-8bed-b2502c7eaf84', 8, 'val', 'Punkterna (2, 1), (2, 4) och (2, 6) ligger på en rak linje. Hur går linjen?', '["Rakt upp och ner","Rakt åt sidan","Snett uppåt åt höger"]'::jsonb, '0'::jsonb, 'Alla punkterna har x-koordinaten 2. Då ligger de rakt ovanför varandra, på en lodrät linje.'),
  ('d5cced89-bada-5d1f-b922-5c4f0a1b771d', 'b45ffb95-24a2-5ee1-98d5-67f9d1618856', 1, 'val', 'Hur många grader är en rät vinkel?', '["45°","90°","180°","360°"]'::jsonb, '1'::jsonb, 'En rät vinkel är som hörnet på ett papper. Den är 90°.'),
  ('b28e9af1-884a-5de1-9357-10d50d4da9d6', 'b45ffb95-24a2-5ee1-98d5-67f9d1618856', 2, 'val', 'En vinkel är 130°. Vad kallas den?', '["Spetsig","Rät","Trubbig"]'::jsonb, '2'::jsonb, 'En trubbig vinkel är större än 90° men mindre än 180°. 130° är det.'),
  ('b3d88022-26f5-53bb-bd0a-e0edaada81c5', 'b45ffb95-24a2-5ee1-98d5-67f9d1618856', 3, 'skriv', 'Två vinklar i en triangel är 50° och 60°. Hur många grader är den tredje vinkeln?', null, '["70"]'::jsonb, 'Vinklarna i en triangel är tillsammans 180°. 180 − 50 − 60 = 70°.'),
  ('6b0f9444-16b4-5255-83e7-e74acaa6a02b', 'b45ffb95-24a2-5ee1-98d5-67f9d1618856', 4, 'val', 'Vilken vinkel är spetsig?', '["35°","90°","120°","180°"]'::jsonb, '0'::jsonb, 'En spetsig vinkel är mindre än 90°. Bara 35° är det.'),
  ('6f922ebd-e586-5e60-9513-caef7c958483', 'b45ffb95-24a2-5ee1-98d5-67f9d1618856', 5, 'skriv', 'Hur många grader är vinklarna i en triangel tillsammans?', null, '["180"]'::jsonb, 'Lägger man ihop de tre vinklarna i en triangel blir det alltid 180°, hur triangeln än ser ut.'),
  ('2e17dbf1-1337-5136-8ddb-db3e3524a7cd', 'b45ffb95-24a2-5ee1-98d5-67f9d1618856', 6, 'skriv', 'En triangel har en rät vinkel och en vinkel på 25°. Hur många grader är den tredje vinkeln?', null, '["65"]'::jsonb, 'En rät vinkel är 90°. 180 − 90 − 25 = 65°.'),
  ('80977e48-97e8-5604-9438-83f0cd6377a3', 'b45ffb95-24a2-5ee1-98d5-67f9d1618856', 7, 'ordna', 'Ordna vinklarna från minst till störst.', null, '["en spetsig vinkel","en rät vinkel","en trubbig vinkel"]'::jsonb, 'En spetsig vinkel är mindre än 90°, en rät är precis 90° och en trubbig är större än 90°.'),
  ('8efcf577-05ee-5d12-b062-f736e4549ffe', 'b45ffb95-24a2-5ee1-98d5-67f9d1618856', 8, 'val', 'Kan en triangel ha två trubbiga vinklar?', '["Nej, då blir vinklarna mer än 180° tillsammans","Ja, om triangeln är stor","Ja, om den tredje vinkeln är liten"]'::jsonb, '0'::jsonb, 'Två trubbiga vinklar är tillsammans mer än 180°. Då finns det ingen plats kvar för den tredje.'),
  ('286e5321-0afb-5ac3-816c-2da18bb3197d', 'c0bad143-76c4-5055-a635-7f23308f118e', 1, 'val', 'Vad är x om x + 7 = 12?', '["4","5","6","19"]'::jsonb, '1'::jsonb, 'Vilket tal plus 7 blir 12? 12 − 7 = 5, så x = 5.'),
  ('c67867b0-c680-5ede-bc53-7ca865456ae6', 'c0bad143-76c4-5055-a635-7f23308f118e', 2, 'skriv', 'Lös ekvationen 3x = 21. Vad är x?', null, '["7","x = 7","x=7","x =7","x= 7"]'::jsonb, '3x betyder 3 · x. 3 · 7 = 21, så x = 7.'),
  ('7a150dd4-37f9-533a-b55e-b8969e52fa21', 'c0bad143-76c4-5055-a635-7f23308f118e', 3, 'skriv', 'Lös ekvationen x − 8 = 15. Vad är x?', null, '["23","x = 23","x=23","x =23","x= 23"]'::jsonb, 'Tar man bort 8 från x blir det 15. Då är x = 15 + 8 = 23.'),
  ('35e71858-c681-5497-acb7-66b436365cb2', 'c0bad143-76c4-5055-a635-7f23308f118e', 4, 'val', 'Vad betyder 4x?', '["4 · x","4 + x","x − 4","x / 4"]'::jsonb, '0'::jsonb, 'När ett tal står direkt framför x betyder det gånger. 4x är 4 · x.'),
  ('ceaa8eeb-3350-588c-97e4-0428e1712838', 'c0bad143-76c4-5055-a635-7f23308f118e', 5, 'val', 'Vilken ekvation har lösningen x = 6?', '["x + 4 = 10","x + 6 = 6","2x = 3","x − 6 = 12"]'::jsonb, '0'::jsonb, 'Sätt in 6 i stället för x: 6 + 4 = 10 stämmer. I de andra blir det inte lika på båda sidor.'),
  ('f3569930-40b0-5484-8992-0b3100cadb24', 'c0bad143-76c4-5055-a635-7f23308f118e', 6, 'skriv', 'Lös ekvationen x / 4 = 5. Vad är x?', null, '["20","x = 20","x=20","x =20","x= 20"]'::jsonb, 'Ett tal delat med 4 blir 5. Då är talet 4 · 5 = 20.'),
  ('989edbdf-1b7b-574f-83bf-a672298bcab3', 'c0bad143-76c4-5055-a635-7f23308f118e', 7, 'ordna', 'Ordna stegen när du löser ekvationen x + 9 = 14. En bricka blir över.', '["x = 14 + 9"]'::jsonb, '["x + 9 = 14","x = 14 − 9","x = 5"]'::jsonb, 'För att få x ensamt tar man bort 9 på båda sidor: x = 14 − 9 = 5.'),
  ('74089c2f-efab-5c5c-8227-ad2de7247fd7', 'c0bad143-76c4-5055-a635-7f23308f118e', 8, 'val', 'Lisa tänker på ett tal x. Hon tar det gånger 5 och får 45. Vilken ekvation passar?', '["5x = 45","x + 5 = 45","x / 5 = 45","45x = 5"]'::jsonb, '0'::jsonb, 'Talet gånger 5 skrivs 5x, och det ska bli 45: 5x = 45. Då är x = 9.'),
  ('781d3da4-7983-5b5b-99a6-6ad2b52c1f5c', 'ff12635a-0e4f-5846-ab8d-a4e560e576a0', 1, 'val', 'Vilket organ pumpar runt blodet i kroppen?', '["Hjärtat","Lungorna","Levern","Njurarna"]'::jsonb, '0'::jsonb, 'Hjärtat är en muskel som drar ihop sig om och om igen och pumpar ut blodet i blodkärlen, även när du sover.'),
  ('42a6d1ad-d9ab-53ac-a4e8-c4735cb86d71', 'ff12635a-0e4f-5846-ab8d-a4e560e576a0', 2, 'val', 'I vilket organ kommer syret från luften in i blodet?', '["Lungorna","Hjärtat","Luftstrupen","Magsäcken"]'::jsonb, '0'::jsonb, 'Luftstrupen leder bara luften ner. I lungorna finns mängder av små lungblåsor med tunna väggar, och där går syret över till blodet.'),
  ('af2845db-8808-5efe-bc13-1142325aed25', 'ff12635a-0e4f-5846-ab8d-a4e560e576a0', 3, 'skriv', 'Vilket organ tänker och styr hela kroppen? Skriv organets namn.', null, '["hjärnan","hjärna"]'::jsonb, 'Hjärnan tar emot signaler från ögon, öron och hud och bestämmer vad kroppen ska göra.'),
  ('d2766f10-fd4d-5468-8893-8a5ba2062326', 'ff12635a-0e4f-5846-ab8d-a4e560e576a0', 4, 'val', 'Vilka organ silar blodet och gör urin?', '["Njurarna","Urinblåsan","Levern","Lungorna"]'::jsonb, '0'::jsonb, 'Njurarna silar bort slaggämnen och vatten som kroppen inte behöver. Det blir urin, som sedan samlas i urinblåsan.'),
  ('37d9aa52-dd4f-54bf-9ec9-c6f4c5b65db7', 'ff12635a-0e4f-5846-ab8d-a4e560e576a0', 5, 'skriv', 'Maten åker ner genom matstrupen till ett organ där den blandas med sur saft. Vad heter organet?', null, '["magsäcken","magsäck","magen","mage"]'::jsonb, 'I magsäcken blandas maten med sur magsaft, som börjar bryta ner den och dödar många bakterier.'),
  ('bcf7218b-d1c3-581e-9c51-ab9c63ca1063', 'ff12635a-0e4f-5846-ab8d-a4e560e576a0', 6, 'ordna', 'Ordna matens väg genom kroppen, från början till slut.', null, '["Munnen","Matstrupen","Magsäcken","Tunntarmen","Tjocktarmen"]'::jsonb, 'Maten tuggas i munnen och åker genom matstrupen till magsäcken. I tunntarmen tas näringen upp i blodet, och i tjocktarmen tas vatten upp.'),
  ('2b4b42ff-c420-5d30-8970-fb9b20cff3da', 'ff12635a-0e4f-5846-ab8d-a4e560e576a0', 7, 'val', 'Vad gör skelettet?', '["Håller upp kroppen och skyddar organen","Pumpar runt blodet","Tar upp näring ur maten","Renar blodet"]'::jsonb, '0'::jsonb, 'Skelettet är kroppens stomme. Skallen skyddar hjärnan och revbenen skyddar hjärtat och lungorna.'),
  ('3be6c6c8-381d-510c-b8a8-8f3aa1bc92d3', 'ff12635a-0e4f-5846-ab8d-a4e560e576a0', 8, 'skriv', 'Hjärnan skickar signaler till musklerna genom långa trådar i kroppen. Vad heter trådarna? Ett ord.', null, '["nerver","nerverna","nerv","nerven","nervtrådar","nervtrådarna","nervceller","nervcellerna","nervbanor","nervbanorna"]'::jsonb, 'Nerverna går ut i hela kroppen. De leder signaler från hjärnan till musklerna och från sinnena tillbaka till hjärnan.'),
  ('88084efa-cb7a-5ccf-84e7-9628910a9eeb', '1fc4bd90-a16f-5873-8bc6-d1ec208718a7', 1, 'val', 'Vad behöver en växt för att kunna göra sin egen näring?', '["Solljus, vatten och koldioxid","Bara näring från jorden","Socker och syre","Solljus och syre"]'::jsonb, '0'::jsonb, 'Med energi från solljuset gör växten socker av vatten och koldioxid. Det kallas fotosyntes.'),
  ('0f3677c1-e0fa-5546-8b44-85f704ddefea', '1fc4bd90-a16f-5873-8bc6-d1ec208718a7', 2, 'skriv', 'Vilken gas släpper växterna ut när de gör fotosyntes? Ett ord.', null, '["syre","syret","syrgas","O2","O₂"]'::jsonb, 'Vid fotosyntesen blir syre över. Det är det syret som människor och djur andas.'),
  ('69ea8add-78de-52c9-9bb1-d04fe824be70', '1fc4bd90-a16f-5873-8bc6-d1ec208718a7', 3, 'val', 'Vad kallas en växt i en näringskedja?', '["Producent","Konsument","Nedbrytare","Rovdjur"]'::jsonb, '0'::jsonb, 'Växter producerar, alltså tillverkar, sin egen näring med hjälp av solljus. Därför kallas de producenter.'),
  ('1a4822c1-67e2-5336-8e2b-f73e330a34bf', '1fc4bd90-a16f-5873-8bc6-d1ec208718a7', 4, 'ordna', 'Ordna näringskedjan. Börja med den som får sin energi direkt från solen.', null, '["Blad","Fjärilslarv","Blåmes","Sparvhök"]'::jsonb, 'Bladet får sin energi från solen. Larven äter bladet, blåmesen äter larven och sparvhöken jagar blåmesen.'),
  ('6ce75d94-363e-554a-a15c-6a83e186d74c', '1fc4bd90-a16f-5873-8bc6-d1ec208718a7', 5, 'val', 'Vilka organismer bryter ner döda växter och djur?', '["Svampar och bakterier","Gräs och träd","Ugglor och hökar","Harar och rådjur"]'::jsonb, '0'::jsonb, 'Svampar, bakterier och till exempel daggmaskar är nedbrytare. De gör det döda till näring i jorden, som växterna kan använda igen.'),
  ('2f2a666a-d6f6-5414-9a0b-39c3b1d207c4', '1fc4bd90-a16f-5873-8bc6-d1ec208718a7', 6, 'skriv', 'Ett djur som bara äter växter kallas växtätare. Vad kallas ett djur som äter både växter och andra djur? Ett ord.', null, '["allätare","allätaren","alätare","omnivor"]'::jsonb, 'Allätare, som grävlingen och människan, kan äta både växter och andra djur.'),
  ('2cd9c8a3-0e91-5007-a20b-7459771d9347', '1fc4bd90-a16f-5873-8bc6-d1ec208718a7', 7, 'val', 'Vad är ett ekosystem?', '["Alla organismer i ett område och miljön de lever i","Bara djuren som lever i ett område","Alla växter på hela jorden","Ett djur och det som det äter"]'::jsonb, '0'::jsonb, 'Ett ekosystem är både det levande (växter, djur, svampar) och det som inte lever (vatten, jord, ljus) i ett område, till exempel en sjö eller en skog.'),
  ('3cb51773-1c30-5150-8ff6-9e78b212502b', '1fc4bd90-a16f-5873-8bc6-d1ec208718a7', 8, 'skriv', 'Vad heter det gröna ämnet i bladen som fångar solljuset? Ett ord.', null, '["klorofyll","klorofyllet","klorofyl","bladgrönt","bladgröna","bladgröntet"]'::jsonb, 'Klorofyll, eller bladgrönt, fångar energin i solljuset så att växten kan göra fotosyntes. Det är därför bladen är gröna.'),
  ('4db313b5-eb75-52c0-9e22-6e00d132dc12', 'adfa4304-ca34-5636-9573-c184431360a7', 1, 'val', 'Vilka tre former kan vatten ha?', '["Fast, flytande och gas","Is, snö och regn","Flytande, moln och ånga","Kallt, varmt och kokande"]'::jsonb, '0'::jsonb, 'Is är vatten i fast form, vanligt vatten är flytande och vattenånga är gas. Det är samma ämne i alla tre formerna.'),
  ('d13a786c-a76b-56c0-9ff1-44ae075b0436', 'adfa4304-ca34-5636-9573-c184431360a7', 2, 'skriv', 'Vid hur många grader Celsius fryser rent vatten till is? Svara med ett tal.', null, '["0"]'::jsonb, 'Rent vatten fryser vid 0 °C. Saltvatten fryser först vid en lite lägre temperatur.'),
  ('977bdaab-7858-5046-9aab-1fc98e093d3f', 'adfa4304-ca34-5636-9573-c184431360a7', 3, 'skriv', 'Vid hur många grader Celsius kokar rent vatten vid normalt lufttryck? Svara med ett tal.', null, '["100"]'::jsonb, 'Vid normalt lufttryck kokar rent vatten vid 100 °C. Högt upp på ett berg, där lufttrycket är lägre, kokar det vid en lägre temperatur.'),
  ('52902051-e523-5df5-beda-c06c60e7b7c6', 'adfa4304-ca34-5636-9573-c184431360a7', 4, 'val', 'Vad heter det när en vattenpöl torkar upp i solen och vattnet blir till gas?', '["Avdunstning","Kondensation","Smältning","Stelning"]'::jsonb, '0'::jsonb, 'När vattnet värms lämnar vattenpartiklar ytan och blir vattenånga i luften. Det kallas avdunstning.'),
  ('8e762828-df7e-5965-a4b2-a6ffb9a110c9', 'adfa4304-ca34-5636-9573-c184431360a7', 5, 'val', 'Vad heter det när vattenånga kyls av och blir små droppar, som när en kall spegel blir immig?', '["Kondensation","Avdunstning","Smältning","Kokning"]'::jsonb, '0'::jsonb, 'Vattenångan i luften kyls av mot den kalla spegeln och blir flytande igen. Det kallas kondensation.'),
  ('10386f0b-05dd-5687-a40b-adb1b6b131b0', 'adfa4304-ca34-5636-9573-c184431360a7', 6, 'ordna', 'Ordna vattnets kretslopp. Börja med solen.', null, '["Solen värmer havet","Vattnet avdunstar","Ångan bildar moln","Det regnar","Vattnet rinner till havet"]'::jsonb, 'Solen driver kretsloppet. Vattnet avdunstar, ångan kyls av och bildar moln, det regnar, och vattnet rinner i bäckar och älvar tillbaka till havet.'),
  ('a0892104-1ffd-51d3-b213-9213682a125d', 'adfa4304-ca34-5636-9573-c184431360a7', 7, 'val', 'Vad händer med vattnets partiklar när is smälter?', '["De rör sig mer och kan glida förbi varandra","De blir större","De försvinner","De slutar röra sig"]'::jsonb, '0'::jsonb, 'I is sitter partiklarna fast på sina platser och vibrerar. När isen värms rör de sig mer och kan glida förbi varandra, och då är vattnet flytande.'),
  ('4fd9f233-dac4-54ab-ba63-af690d3fbc3a', 'adfa4304-ca34-5636-9573-c184431360a7', 8, 'skriv', 'Vad kallas vatten i gasform? Ett ord.', null, '["vattenånga","vattenångan","ånga","ångan"]'::jsonb, 'Vattenånga är osynlig. Det vita som syns över en kastrull med kokande vatten är små vattendroppar som redan har kondenserat.'),
  ('df3761f4-b10d-56f2-9f56-bc58926b021a', '607ba65f-35ab-5faf-8f3a-d5f4e79fbeb7', 1, 'val', 'Vilken laddning har en proton?', '["Positiv","Negativ","Ingen laddning"]'::jsonb, '0'::jsonb, 'Protonen är positivt laddad, elektronen negativt laddad och neutronen har ingen laddning alls.'),
  ('cce43f8f-595d-545e-8ba3-a88b44e5aea8', '607ba65f-35ab-5faf-8f3a-d5f4e79fbeb7', 2, 'val', 'Vilket kemiskt tecken har syre?', '["O","S","Si","Sy"]'::jsonb, '0'::jsonb, 'Syre heter oxygenium på latin, därför O. S är svavel och Si är kisel.'),
  ('159947a0-3576-50b4-9bb0-16b5871001c3', '607ba65f-35ab-5faf-8f3a-d5f4e79fbeb7', 3, 'skriv', 'En litiumatom har 3 protoner, 4 neutroner och 3 elektroner. Hur många partiklar finns i atomkärnan?', null, '["7"]'::jsonb, 'Kärnan består av protonerna och neutronerna: 3 + 4 = 7. Elektronerna rör sig i skal utanför kärnan.'),
  ('939a9eb8-6469-5b53-9b77-35d68c64ff21', '607ba65f-35ab-5faf-8f3a-d5f4e79fbeb7', 4, 'val', 'Vilket kemiskt tecken har kol?', '["C","K","Co","Ca"]'::jsonb, '0'::jsonb, 'C kommer av carbo, det latinska ordet för kol. K är kalium, Co är kobolt och Ca är kalcium.'),
  ('368f8b9c-3b61-5849-b3bd-67bde1967b5b', '607ba65f-35ab-5faf-8f3a-d5f4e79fbeb7', 5, 'skriv', 'En neutral atom har 8 protoner. Hur många elektroner har den?', null, '["8"]'::jsonb, 'I en neutral atom är det lika många negativa elektroner som positiva protoner, så laddningarna tar ut varandra. Atomen med 8 protoner är syre.'),
  ('dad3f1da-e6b6-502f-9e50-8cb282c5cf08', '607ba65f-35ab-5faf-8f3a-d5f4e79fbeb7', 6, 'skriv', 'Antalet protoner i kärnan avgör vilket grundämne en atom är. Vad kallas det talet? Ett ord.', null, '["atomnummer","atomnumret","atomnumer","atomnummret","atom nummer"]'::jsonb, 'Atomnumret är antalet protoner. Väte har atomnummer 1, kol 6 och syre 8, och det är i den ordningen grundämnena står i periodiska systemet.'),
  ('984c0992-5eef-53a8-81cd-51033092e5cd', '607ba65f-35ab-5faf-8f3a-d5f4e79fbeb7', 7, 'val', 'Vilket grundämne har det kemiska tecknet Fe?', '["Järn","Fluor","Fosfor","Silver"]'::jsonb, '0'::jsonb, 'Fe kommer av ferrum, det latinska ordet för järn. Fluor är F, fosfor är P och silver är Ag.'),
  ('3c145501-9a75-577d-9282-62db22b72698', '607ba65f-35ab-5faf-8f3a-d5f4e79fbeb7', 8, 'ordna', 'Ordna från minst till störst. Varje sak är en del av den som kommer efter.', null, '["Proton","Atomkärna","Atom","Molekyl"]'::jsonb, 'Protonerna sitter i atomkärnan, kärnan är atomens mitt, och atomer sitter ihop till molekyler.'),
  ('797e94cc-eb30-5b7e-b291-2dcc73bca5cc', 'b19a6975-4f1e-5934-ac50-e9a9dd1e62fc', 1, 'skriv', 'Vilket pH har en neutral lösning? Svara med ett tal.', null, '["7"]'::jsonb, 'pH-skalan går från 0 till 14. Under 7 är surt, över 7 är basiskt och pH 7, som rent vatten, är neutralt.'),
  ('61cf7e05-5ba5-5268-8bbf-30a1d571eec7', 'b19a6975-4f1e-5934-ac50-e9a9dd1e62fc', 2, 'val', 'En lösning har pH 3. Vad är den?', '["Sur","Neutral","Basisk"]'::jsonb, '0'::jsonb, 'Allt under pH 7 är surt, och ju längre under 7 pH-värdet är, desto surare är lösningen.'),
  ('f3a04482-0016-50c9-a631-9e01d6e42f59', 'b19a6975-4f1e-5934-ac50-e9a9dd1e62fc', 3, 'ordna', 'Ordna pH-värdena från surast till mest basisk.', null, '["pH 1","pH 5","pH 7","pH 9","pH 13"]'::jsonb, 'Ju lägre pH, desto surare. pH 7 är neutralt, och ju högre över 7, desto mer basiskt.'),
  ('06f986d6-e6f0-5dda-a571-cf48b941ecc4', 'b19a6975-4f1e-5934-ac50-e9a9dd1e62fc', 4, 'val', 'Vilka joner gör en lösning sur?', '["Vätejoner (H⁺)","Hydroxidjoner (OH⁻)","Natriumjoner (Na⁺)","Kloridjoner (Cl⁻)"]'::jsonb, '0'::jsonb, 'En syra lämnar ifrån sig vätejoner i vattnet. Ju fler vätejoner, desto lägre pH. Hydroxidjoner är det som gör en lösning basisk.'),
  ('c444e99f-54d5-5bbf-a7f6-2f8aa28ea7bb', 'b19a6975-4f1e-5934-ac50-e9a9dd1e62fc', 5, 'skriv', 'Ett ämne som byter färg och visar om en lösning är sur eller basisk kallas en … Vilket ord fattas?', null, '["indikator","indikatorn","indikatorer","pH-indikator","pH-indikatorn","syra-basindikator","indikatorlösning"]'::jsonb, 'En indikator har olika färg vid olika pH. BTB är till exempel gul i en sur lösning och blå i en basisk.'),
  ('9b56366f-0e3a-521c-8136-f9a8d668f8be', 'b19a6975-4f1e-5934-ac50-e9a9dd1e62fc', 6, 'val', 'Vilket av de här är basiskt?', '["Bikarbonat löst i vatten","Citronsaft","Ättika","Läsk"]'::jsonb, '0'::jsonb, 'Bikarbonat ger en svagt basisk lösning. Citronsaft, ättika och läsk innehåller syror och är sura.'),
  ('c5f6c219-49a2-53b8-9999-ddd7c202b378', 'b19a6975-4f1e-5934-ac50-e9a9dd1e62fc', 7, 'skriv', 'När en syra och en bas blandas i lagom mängder tar de ut varandra. Vad heter det? Ett ord.', null, '["neutralisation","neutralisering","neutralisationen","neutraliseringen","neutralisera","neutraliserar"]'::jsonb, 'Det kallas neutralisation. Syrans vätejoner och basens hydroxidjoner blir vatten, och kvar blir ett salt.'),
  ('f5c3c61a-51e7-50ee-a3d4-06aab1a41c98', 'b19a6975-4f1e-5934-ac50-e9a9dd1e62fc', 8, 'val', 'Vilken syra finns i magsaften i magsäcken?', '["Saltsyra","Svavelsyra","Ättiksyra","Citronsyra"]'::jsonb, '0'::jsonb, 'Magsaften innehåller saltsyra. Den hjälper till att bryta ner maten och dödar många bakterier.'),
  ('5be7448b-0c5d-5d30-8ee6-39213b4bbc7d', 'a9cf04d6-87ab-5efa-b2e5-f6e844b5f094', 1, 'val', 'Var i cellen finns det mesta av arvsmassan, DNA?', '["I cellkärnan","I cellmembranet","I cellväggen","I vakuolen"]'::jsonb, '0'::jsonb, 'Cellkärnan innehåller arvsmassan, som är cellens ritning. Därifrån styrs cellens arbete.'),
  ('3f3c6339-d6fd-562e-8746-2807365135c5', 'a9cf04d6-87ab-5efa-b2e5-f6e844b5f094', 2, 'skriv', 'Vad heter den tunna hinnan runt cellen som bestämmer vad som får komma in och ut? Ett ord.', null, '["cellmembran","cellmembranet","membran","membranet","cellhinna","cellhinnan","plasmamembran","plasmamembranet"]'::jsonb, 'Cellmembranet omger alla celler. Det släpper in det cellen behöver, som vatten och näring, och släpper ut avfall.'),
  ('d73f6455-7e6c-5f0e-8f58-cb21363e4a29', 'a9cf04d6-87ab-5efa-b2e5-f6e844b5f094', 3, 'val', 'Vilken av de här delarna har växtceller men inte djurceller?', '["Cellvägg","Cellkärna","Cellmembran","Mitokondrier"]'::jsonb, '0'::jsonb, 'Cellväggen är ett stadigt skal av cellulosa utanför cellmembranet, och den ger växten stadga. Djurceller har bara cellmembran.'),
  ('1254ef35-caf4-5678-b721-b184700c9bfb', 'a9cf04d6-87ab-5efa-b2e5-f6e844b5f094', 4, 'skriv', 'Vad heter det gröna ämnet som fångar solljuset i växternas celler? Ett ord.', null, '["klorofyll","klorofyllet","klorofyl","bladgrönt","bladgröna","bladgröntet"]'::jsonb, 'Klorofyll, eller bladgrönt, fångar energin i solljuset. Det är därför växter är gröna.'),
  ('a53a3ff1-1a85-5b06-8457-d431d3636809', 'a9cf04d6-87ab-5efa-b2e5-f6e844b5f094', 5, 'val', 'I vilka delar av växtcellen sker fotosyntesen?', '["I kloroplasterna","I mitokondrierna","I cellkärnan","I vakuolen"]'::jsonb, '0'::jsonb, 'Kloroplasterna är små gröna korn som innehåller klorofyll. Där fångas solljuset och socker byggs.'),
  ('d4a10dbb-eb44-5a0f-9928-dfa7da9c3790', 'a9cf04d6-87ab-5efa-b2e5-f6e844b5f094', 6, 'val', 'I vilka delar av cellen sker det mesta av cellandningen?', '["I mitokondrierna","I kloroplasterna","I cellkärnan","I cellväggen"]'::jsonb, '0'::jsonb, 'Mitokondrierna brukar kallas cellens kraftverk. Där frigörs energin ur socker med hjälp av syre.'),
  ('2a051f28-fc54-5ccb-9cd0-ab7adb800dfb', 'a9cf04d6-87ab-5efa-b2e5-f6e844b5f094', 7, 'ordna', 'Ordna från minst till störst.', null, '["Cell","Vävnad","Organ","Organsystem","Organism"]'::jsonb, 'Celler av samma sort bildar en vävnad, flera vävnader bildar ett organ, organ samarbetar i organsystem, och tillsammans blir de en organism.'),
  ('bcff4763-42e3-52d5-b7b2-6b83715f1e1c', 'a9cf04d6-87ab-5efa-b2e5-f6e844b5f094', 8, 'skriv', 'Organismer som bara består av en enda cell, som bakterier, kallas … organismer. Vilket ord fattas?', null, '["encelliga","encellig","en-celliga","encelliga organismer"]'::jsonb, 'Encelliga organismer klarar allt livet kräver i en enda cell. Människor, djur och de flesta växter är flercelliga.'),
  ('c39c8695-e09b-5788-8a4a-59c62a846b82', '194e3c8e-c378-5f2d-bef9-6535cf938bb0', 1, 'skriv', 'Vilken gas tar växterna upp ur luften när de gör fotosyntes? Ett ord.', null, '["koldioxid","koldioxiden","CO2","CO₂"]'::jsonb, 'Växten tar in koldioxid genom små öppningar i bladen. Tillsammans med vatten från rötterna blir den till socker.'),
  ('3ed2b064-2a41-5641-82b8-a6f0cc99b2b4', '194e3c8e-c378-5f2d-bef9-6535cf938bb0', 2, 'val', 'Varifrån får växten energin till fotosyntesen?', '["Från solljuset","Från jorden","Från vattnet","Från syret i luften"]'::jsonb, '0'::jsonb, 'Energin kommer från solljuset, som klorofyllet fångar. Ur jorden får växten bara vatten och mineralämnen.'),
  ('f304f9f0-913b-553c-955f-ca5384c7069f', '194e3c8e-c378-5f2d-bef9-6535cf938bb0', 3, 'val', 'Vilka ämnen bildas vid fotosyntesen?', '["Socker och syre","Koldioxid och vatten","Socker och koldioxid","Syre och vatten"]'::jsonb, '0'::jsonb, 'Växten bygger socker av koldioxid och vatten. Syret blir över och släpps ut i luften.'),
  ('541ca9d0-228b-5a7d-b8e1-0e4992b06142', '194e3c8e-c378-5f2d-bef9-6535cf938bb0', 4, 'skriv', 'Sockret som bildas vid fotosyntesen har ett eget namn. Vad heter det? Ett ord.', null, '["glukos","glukosen","glykos","druvsocker","druvsockret"]'::jsonb, 'Sockret heter glukos, eller druvsocker. Växten använder det som energi och bygger också stärkelse och cellulosa av det.'),
  ('05d5124e-84e1-5de0-923f-9a0e3c0ad588', '194e3c8e-c378-5f2d-bef9-6535cf938bb0', 5, 'skriv', 'Vilken gas behöver cellerna för att göra cellandning? Ett ord.', null, '["syre","syret","syrgas","O2","O₂"]'::jsonb, 'Vid cellandningen använder cellerna syre för att frigöra energin i sockret. Därför andas vi.'),
  ('ff318849-5cad-5a42-8801-2cf3cbe0cd2a', '194e3c8e-c378-5f2d-bef9-6535cf938bb0', 6, 'val', 'Vid cellandningen frigörs energi ur socker. Vilka ämnen bildas samtidigt?', '["Koldioxid och vatten","Socker och syre","Syre och vatten","Syre och koldioxid"]'::jsonb, '0'::jsonb, 'Glukos och syre blir koldioxid och vatten, och energi frigörs. Det är fotosyntesen baklänges.'),
  ('8461dd9e-e3c3-5d05-9303-3b3cdd39c853', '194e3c8e-c378-5f2d-bef9-6535cf938bb0', 7, 'val', 'Vilka organismer gör cellandning?', '["Både växter och djur","Bara djur","Bara växter","Bara växter på natten"]'::jsonb, '0'::jsonb, 'Alla celler behöver energi. Växter gör cellandning dygnet runt, precis som djur, och på dagen gör de dessutom fotosyntes.'),
  ('529a4380-5151-57fb-a107-15d77889dc2a', '194e3c8e-c378-5f2d-bef9-6535cf938bb0', 8, 'ordna', 'Bygg ordformeln för fotosyntesen.', '["syre + vatten"]'::jsonb, '["koldioxid + vatten","→","glukos + syre"]'::jsonb, 'Med energi från solljuset blir koldioxid och vatten till glukos och syre. Åt andra hållet är det cellandningens formel.'),
  ('e9d7ecc3-dd53-55a3-b485-056d815f33fc', '676c17fc-864b-5ee1-8994-27f21b459e33', 1, 'val', 'Vilken enhet mäts elektrisk spänning i?', '["volt (V)","ampere (A)","ohm (Ω)","watt (W)"]'::jsonb, '0'::jsonb, 'Spänning mäts i volt. Ström mäts i ampere, resistans i ohm och effekt i watt.'),
  ('06782f0f-a4f8-5a08-90c2-8222f62ecd2f', '676c17fc-864b-5ee1-8994-27f21b459e33', 2, 'val', 'Vad menas med resistans?', '["Hur mycket något hindrar strömmen","Hur mycket laddning som passerar per sekund","Hur mycket energi ett batteri kan lagra"]'::jsonb, '0'::jsonb, 'Resistans är hur svårt det är för strömmen att ta sig fram, och den mäts i ohm. Laddning per sekund är strömmen.'),
  ('366fa225-b208-53c5-aacb-9fbf30c85d0f', '676c17fc-864b-5ee1-8994-27f21b459e33', 3, 'skriv', 'Genom en lampa med resistansen 20 Ω går strömmen 0,5 A. Hur många volt är spänningen över lampan?', null, '["10"]'::jsonb, 'U = R · I = 20 · 0,5 = 10. Spänningen är 10 V.'),
  ('c104b26c-fa60-5c62-b6a8-c4fa91a92d31', '676c17fc-864b-5ee1-8994-27f21b459e33', 4, 'val', 'Du ska mäta strömmen genom en lampa med en amperemeter. Hur kopplar du den?', '["I serie med lampan","Parallellt med lampan","Direkt mellan batteriets poler"]'::jsonb, '0'::jsonb, 'All ström som går genom lampan måste också gå genom mätaren, så den kopplas i serie. Det är voltmetern som kopplas parallellt.'),
  ('feb46200-3676-512c-876b-fdc1ebcfb82f', '676c17fc-864b-5ee1-8994-27f21b459e33', 5, 'skriv', 'Ett batteri på 4,5 V kopplas till ett motstånd på 15 Ω. Hur många ampere blir strömmen?', null, '["0,3"]'::jsonb, 'I = U / R = 4,5 / 15 = 0,3 A.'),
  ('bb92ca65-ba54-5729-bb8f-88ae1073a68d', '676c17fc-864b-5ee1-8994-27f21b459e33', 6, 'val', 'Spänningen över ett motstånd fördubblas, och resistansen är densamma. Vad händer med strömmen?', '["Den fördubblas","Den halveras","Den blir densamma","Den blir fyra gånger större"]'::jsonb, '0'::jsonb, 'Enligt Ohms lag är I = U / R. Med samma resistans blir strömmen dubbelt så stor när spänningen blir dubbelt så stor.'),
  ('6c8c1057-c525-5684-9a4e-eec97ca32898', '676c17fc-864b-5ee1-8994-27f21b459e33', 7, 'skriv', 'Över ett motstånd är spänningen 12 V och strömmen 0,4 A. Hur många ohm är resistansen?', null, '["30"]'::jsonb, 'R = U / I = 12 / 0,4 = 30 Ω.'),
  ('dd211aa4-a353-5a0e-8dc9-2716f773b636', '676c17fc-864b-5ee1-8994-27f21b459e33', 8, 'ordna', 'Fyra lampor kopplas en i taget till samma batteri på 6 V. Strömmen genom varje lampa står på brickan. Ordna lamporna från minst till störst resistans.', null, '["Grön: 1 A","Röd: 0,5 A","Gul: 0,3 A","Blå: 0,2 A"]'::jsonb, 'R = U / I, så med samma spänning ger en större ström en mindre resistans: grön: 6 / 1 = 6 Ω, röd: 6 / 0,5 = 12 Ω, gul: 6 / 0,3 = 20 Ω, blå: 6 / 0,2 = 30 Ω.'),
  ('0a8a9118-a817-53cc-8f04-ea0f2ea085dc', 'a3c2ba91-a029-540a-9ecb-9fcb372ec4c5', 1, 'val', 'Hur börjar en mening?', '["Med stor bokstav","Med liten bokstav","Med en punkt"]'::jsonb, '0'::jsonb, 'Det första ordet i en mening har alltid stor bokstav.'),
  ('3161c4f4-87a5-506a-ad56-3496144728d9', 'a3c2ba91-a029-540a-9ecb-9fcb372ec4c5', 2, 'val', 'Vad ska stå sist? ”Vi ska bada i sjön”', '["punkt","frågetecken","komma"]'::jsonb, '0'::jsonb, 'Meningen berättar något. Då sätter man punkt sist.'),
  ('fead6b01-64d0-5ccf-8e0b-09d07bb0fd63', 'a3c2ba91-a029-540a-9ecb-9fcb372ec4c5', 3, 'val', 'Vad ska stå sist? ”Vill du leka med mig”', '["punkt","frågetecken","komma"]'::jsonb, '1'::jsonb, 'Meningen är en fråga. Efter en fråga sätter man frågetecken.'),
  ('f0004b21-dc48-57f1-b184-e40b6faadf20', 'a3c2ba91-a029-540a-9ecb-9fcb372ec4c5', 4, 'val', 'Vilket ord ska skrivas med stor bokstav?', '["stockholm","måndag","juli","skola"]'::jsonb, '0'::jsonb, 'Stockholm är namnet på en stad, och namn har stor bokstav. Dagar och månader har liten bokstav.'),
  ('aee95450-8521-596b-b0e7-c872e21afb49', 'a3c2ba91-a029-540a-9ecb-9fcb372ec4c5', 5, 'skriv', 'Ett ord saknar stor bokstav. Skriv ordet. ”Min hund heter bella.”', null, '["Bella"]'::jsonb, 'Bella är ett namn. Namn har alltid stor bokstav, var de än står.'),
  ('2ff25686-b375-5349-b5a9-5c3588fafbbf', 'a3c2ba91-a029-540a-9ecb-9fcb372ec4c5', 6, 'skriv', 'Hur många meningar är det? ”Det regnar. Vi är inne. Vi spelar spel.”', null, '["3","tre"]'::jsonb, 'Varje mening slutar med punkt. Det finns tre punkter, alltså tre meningar.'),
  ('3cd6db5e-c164-5919-973c-be0072ab845e', 'a3c2ba91-a029-540a-9ecb-9fcb372ec4c5', 7, 'ordna', 'Bygg meningen. Den börjar med stor bokstav och slutar med punkt.', null, '["Katten","sover","i","soffan."]'::jsonb, 'Katten har stor bokstav, så det ordet står först. Soffan har punkt, så det står sist.'),
  ('c5fd52e9-f8c5-5b92-a86c-71eaff319151', 'a3c2ba91-a029-540a-9ecb-9fcb372ec4c5', 8, 'ordna', 'Bygg frågan. En bricka hör inte dit.', '["du."]'::jsonb, '["Vad","heter","du?"]'::jsonb, 'Det är en fråga, så den slutar med frågetecken och inte med punkt.'),
  ('509e2925-9e2d-5544-aaad-805a6410325a', '5df03b97-7900-5082-b396-7d6cf9f2210e', 1, 'val', 'Vilken bokstav kommer efter k i alfabetet?', '["l","j","m"]'::jsonb, '0'::jsonb, 'Alfabetet går j, k, l, m. Direkt efter k kommer l.'),
  ('48d0db2d-8ba1-5c90-9398-ab118decdf84', '5df03b97-7900-5082-b396-7d6cf9f2210e', 2, 'skriv', 'Vilken bokstav står mellan r och t i alfabetet?', null, '["s"]'::jsonb, 'Alfabetet går r, s, t. Bokstaven mellan r och t är s.'),
  ('43861ce3-f32f-5704-a78e-75f12555cd95', '5df03b97-7900-5082-b396-7d6cf9f2210e', 3, 'skriv', 'Vilken bokstav kommer direkt efter z?', null, '["å"]'::jsonb, 'I det svenska alfabetet kommer å, ä och ö sist, efter z.'),
  ('a1410489-a5b8-58a8-93ca-315fe89943a5', '5df03b97-7900-5082-b396-7d6cf9f2210e', 4, 'val', 'Vilket ord kommer först i alfabetisk ordning?', '["boll","apa","cykel"]'::jsonb, '1'::jsonb, 'Titta på första bokstaven. A kommer före b och c.'),
  ('20b5561d-1bbf-5ef6-b76a-2516849d34df', '5df03b97-7900-5082-b396-7d6cf9f2210e', 5, 'val', 'Alla orden börjar på m. Vilket kommer först i alfabetisk ordning?', '["mus","mjölk","mamma"]'::jsonb, '2'::jsonb, 'När första bokstaven är samma tittar man på den andra: a, j och u. A kommer först, så mamma står först.'),
  ('d59b1468-aeb0-59e0-97af-170583c0f098', '5df03b97-7900-5082-b396-7d6cf9f2210e', 6, 'val', 'Vilket ord kommer sist i alfabetisk ordning?', '["zebra","öga","ål"]'::jsonb, '1'::jsonb, 'Ö är den allra sista bokstaven i alfabetet. Därför kommer öga efter både zebra och ål.'),
  ('18c8e208-1191-5e37-8d8a-42b52e50ce5b', '5df03b97-7900-5082-b396-7d6cf9f2210e', 7, 'ordna', 'Ordna orden i alfabetisk ordning.', null, '["boll","fisk","sol","zebra","äpple"]'::jsonb, 'B, f, s, z och sist ä. Å, ä och ö kommer efter z i alfabetet.'),
  ('fa464201-b00a-5de4-8a2b-5c1ffcf1404a', '5df03b97-7900-5082-b396-7d6cf9f2210e', 8, 'ordna', 'Ordna orden i alfabetisk ordning. Alla börjar på b, så titta på andra bokstaven.', null, '["bad","bil","bok","buss"]'::jsonb, 'Andra bokstäverna är a, i, o och u. I alfabetet kommer de i den ordningen.'),
  ('1f22723b-59dc-53f6-8b5a-1ae4c5bea5df', '9d5d51ad-7b5f-52c6-a22a-9420d8f5dfbf', 1, 'val', 'Vilken bokstav är en vokal?', '["e","k","s","m"]'::jsonb, '0'::jsonb, 'Vokalerna är a, e, i, o, u, y, å, ä och ö. E är en av dem.'),
  ('3f5cb499-dbf4-50f5-9101-8481eea764f6', '9d5d51ad-7b5f-52c6-a22a-9420d8f5dfbf', 2, 'val', 'Vilken bokstav är en konsonant?', '["r","a","y","ö"]'::jsonb, '0'::jsonb, 'A, y och ö är vokaler. R är en konsonant, som alla bokstäver som inte är vokaler.'),
  ('34e3b540-a8a5-5ad7-8c00-8cd52901036e', '9d5d51ad-7b5f-52c6-a22a-9420d8f5dfbf', 3, 'skriv', 'Hur många vokaler finns det i det svenska alfabetet?', null, '["9","nio"]'::jsonb, 'Vokalerna är a, e, i, o, u, y, å, ä och ö. Det är nio stycken.'),
  ('fb61ba72-1a07-51dc-8341-963554010cce', '9d5d51ad-7b5f-52c6-a22a-9420d8f5dfbf', 4, 'skriv', 'En vokal fattas. Vilken? a, e, i, o, u, y, å, ä', null, '["ö"]'::jsonb, 'Alla nio vokaler är a, e, i, o, u, y, å, ä och ö. Det var ö som fattades.'),
  ('84f7d1eb-c594-574e-a90b-a991aaa6988f', '9d5d51ad-7b5f-52c6-a22a-9420d8f5dfbf', 5, 'skriv', 'Hur många vokaler finns det i ordet ”tomat”?', null, '["2","två"]'::jsonb, 'T-o-m-a-t. O och a är vokaler, så det blir två. T och m är konsonanter.'),
  ('ce0f0a4e-5bd4-59bd-98f9-40c83eb837bf', '9d5d51ad-7b5f-52c6-a22a-9420d8f5dfbf', 6, 'val', 'Vilket ord börjar med en vokal?', '["äpple","banan","päron","melon"]'::jsonb, '0'::jsonb, 'Ä är en vokal. B, p och m är konsonanter.'),
  ('f4f4e875-86bd-58ed-b606-dd4f4546dda1', '9d5d51ad-7b5f-52c6-a22a-9420d8f5dfbf', 7, 'val', 'Vilket ord har bara en vokal?', '["katt","hunden","kanin","kamel"]'::jsonb, '0'::jsonb, 'I katt finns bara a. Hunden har u och e, kanin har a och i, kamel har a och e.'),
  ('f0fc0768-58ab-53b2-ad65-bbee6d55065f', '9d5d51ad-7b5f-52c6-a22a-9420d8f5dfbf', 8, 'ordna', 'Ordna vokalerna så som de står i alfabetet.', null, '["i","o","y","å","ö"]'::jsonb, 'I kommer före o och o före y. Å och ö står sist i alfabetet.'),
  ('10e0ad80-ee85-511b-b2b3-9a02be0adebd', '2704a2c4-a5c7-5ab5-9e71-735947e76aa0', 1, 'val', 'Vilket ord är ett substantiv?', '["bord","springa","glad"]'::jsonb, '0'::jsonb, 'Ett substantiv är namnet på en sak, ett djur eller en människa. Man kan säga ett bord.'),
  ('f2a9bfff-b7eb-56c8-9ba8-a5a8a95eedf4', '2704a2c4-a5c7-5ab5-9e71-735947e76aa0', 2, 'val', 'Vilket ord är ett verb?', '["hoppar","boll","stor"]'::jsonb, '0'::jsonb, 'Ett verb berättar vad någon gör: jag hoppar.'),
  ('ce25c1e5-93fc-5b9a-8f61-c42859e99e45', '2704a2c4-a5c7-5ab5-9e71-735947e76aa0', 3, 'val', 'Vilket ord säger vad Ali gör? ”Ali cyklar till skolan.”', '["cyklar","Ali","till","skolan"]'::jsonb, '0'::jsonb, 'Att cykla är det Ali gör. Ord som säger vad någon gör är verb.'),
  ('d2d27bf5-d347-5d16-8fc0-91ce5f27190e', '2704a2c4-a5c7-5ab5-9e71-735947e76aa0', 4, 'skriv', 'Skriv verbet i meningen: ”Hunden skäller.”', null, '["skäller"]'::jsonb, 'Skäller är det hunden gör. Därför är det ett verb.'),
  ('1d22ea29-a594-5d72-82a8-c3ab848c9bb6', '2704a2c4-a5c7-5ab5-9e71-735947e76aa0', 5, 'skriv', 'Skriv substantivet i meningen: ”Fågeln flyger.”', null, '["fågeln","fågel"]'::jsonb, 'Fågeln är ett djur. Namn på djur, saker och människor är substantiv.'),
  ('933cfe34-32d4-5abd-8a76-93e76193972f', '2704a2c4-a5c7-5ab5-9e71-735947e76aa0', 6, 'val', 'Framför vilket ord kan man sätta ”en” eller ”ett”?', '["penna","skriver","ritar"]'::jsonb, '0'::jsonb, 'Man säger en penna. Ord som kan ha en eller ett framför sig är substantiv.'),
  ('f02de9b4-3213-5bca-a1ab-db2effc23d92', '2704a2c4-a5c7-5ab5-9e71-735947e76aa0', 7, 'skriv', 'Hur många substantiv finns det i meningen? ”Pojken har en hund och en katt.”', null, '["3","tre"]'::jsonb, 'Pojken, hund och katt är substantiv. Har är ett verb.'),
  ('5fabb4bf-8f4e-545d-9bf7-de47714b01d8', '2704a2c4-a5c7-5ab5-9e71-735947e76aa0', 8, 'ordna', 'Bygg meningen.', null, '["Flickan","läser","en","bok."]'::jsonb, 'Flickan har stor bokstav och står först. Sedan kommer verbet läser, och bok har punkt och står sist.'),
  ('8fddfbc4-24ec-56bf-99b0-639f43fca993', '42e82a87-703a-5281-bdc6-97e95d1167c3', 1, 'val', 'Vilken ordklass är ordet ”snabb”?', '["adjektiv","verb","substantiv","pronomen"]'::jsonb, '0'::jsonb, 'Snabb beskriver hur något är, som i en snabb häst. Ord som beskriver är adjektiv.'),
  ('4207e3c2-7694-5264-ba1d-197c21479b43', '42e82a87-703a-5281-bdc6-97e95d1167c3', 2, 'val', 'Vilken ordklass är ordet ”hon”?', '["pronomen","substantiv","adjektiv","verb"]'::jsonb, '0'::jsonb, 'Hon står i stället för ett namn, till exempel Sara. Sådana ord är pronomen.'),
  ('ff514d5c-c4c1-5fc5-9de2-47363938c580', '42e82a87-703a-5281-bdc6-97e95d1167c3', 3, 'val', 'Vilket ord i meningen är ett adjektiv? ”Den gamla hunden sov länge.”', '["gamla","hunden","sov","länge"]'::jsonb, '0'::jsonb, 'Gamla beskriver hur hunden är, och det gör adjektiv. Länge säger något om sovandet, inte om hunden.'),
  ('40573d5c-95bf-5856-84e5-e45715ab1f3c', '42e82a87-703a-5281-bdc6-97e95d1167c3', 4, 'val', 'Vilket ord är ett verb?', '["simmar","simhall","simkunnig"]'::jsonb, '0'::jsonb, 'Simmar säger vad någon gör: hon simmar. Simhall är ett substantiv och simkunnig ett adjektiv.'),
  ('0d004dcc-e2a9-58a2-94c3-6b9f4eac0891', '42e82a87-703a-5281-bdc6-97e95d1167c3', 5, 'skriv', 'Skriv pronomenet i meningen: ”Efter maten diskade vi.”', null, '["vi"]'::jsonb, 'Vi står i stället för namnen på dem som diskade. Därför är vi ett pronomen.'),
  ('27408007-8348-56c6-a0a8-62c24022bad1', '42e82a87-703a-5281-bdc6-97e95d1167c3', 6, 'skriv', 'Skriv adjektivet i meningen: ”Sara köpte en blå jacka.”', null, '["blå"]'::jsonb, 'Blå beskriver hur jackan ser ut. Ord som beskriver är adjektiv.'),
  ('08626687-6535-558a-9b96-5761d16b85b6', '42e82a87-703a-5281-bdc6-97e95d1167c3', 7, 'skriv', 'Hur många substantiv finns det i meningen? ”Morfar lagade cykeln i garaget.”', null, '["3","tre"]'::jsonb, 'Morfar, cykeln och garaget är substantiv. Lagade är ett verb och i är en preposition.'),
  ('b11df781-dd16-5969-b224-4fa4f8528645', '42e82a87-703a-5281-bdc6-97e95d1167c3', 8, 'ordna', 'Ställ orden i den här ordningen: substantiv, verb, adjektiv, pronomen.', null, '["bok","läser","tjock","hon"]'::jsonb, 'Bok är en sak, läser är något man gör, tjock beskriver och hon står i stället för ett namn.'),
  ('6a9f9103-cee4-5937-aaf0-eb0e60612a34', '8e68b8c0-1106-573b-99f1-d76430a84964', 1, 'val', 'Vilket ord passar och är rätt stavat? ”Pengarna ligger i min …”', '["ficka","fikka","fika"]'::jsonb, '0'::jsonb, 'I ficka är i kort, och ett k-ljud efter en kort vokal skrivs ck. Fika är ett annat ord.'),
  ('ae4126e5-8c3b-58ea-b93d-fc086e14a656', '8e68b8c0-1106-573b-99f1-d76430a84964', 2, 'val', 'När stavas k-ljudet med ck?', '["Efter en kort vokal","Efter en lång vokal","I början av ett ord"]'::jsonb, '0'::jsonb, 'Efter en kort vokal skrivs k-ljudet ck, som i klocka och sticka. Efter en lång vokal räcker ett k, som i kaka.'),
  ('dbfca278-ecaa-546c-a5e7-a846cd2b7a6f', '8e68b8c0-1106-573b-99f1-d76430a84964', 3, 'val', 'I vilket ord är vokalen kort?', '["tack","tak","mat","fin"]'::jsonb, '0'::jsonb, 'Två konsonanter efter vokalen, som ck i tack, visar att vokalen är kort. I tak, mat och fin är vokalen lång.'),
  ('4f243910-e55b-5a3b-a89a-b2683146632a', '8e68b8c0-1106-573b-99f1-d76430a84964', 4, 'val', 'Vilket ord är felstavat?', '["hoppa","glass","pena","socker"]'::jsonb, '2'::jsonb, 'E är kort i penna, så n ska dubbleras. Rätt stavning är penna.'),
  ('9b6eb5b2-c32d-53c2-ac08-922b6cc5a6c3', '8e68b8c0-1106-573b-99f1-d76430a84964', 5, 'skriv', 'Ordet är felstavat: ”vaten”. Skriv det rätt.', null, '["vatten"]'::jsonb, 'A är kort i vatten. Efter en kort vokal dubbleras konsonanten, så det blir tt.'),
  ('e0476a1f-bf1c-50c5-94a3-0a59081a4aa2', '8e68b8c0-1106-573b-99f1-d76430a84964', 6, 'skriv', 'Ett ord är felstavat: ”Mormor bakar med mjöl och soker.” Skriv ordet rätt.', null, '["socker"]'::jsonb, 'O är kort i socker. Ett k-ljud efter en kort vokal skrivs ck.'),
  ('96fc3af0-f3f4-5eb6-afff-8aaed5e2e2bb', '8e68b8c0-1106-573b-99f1-d76430a84964', 7, 'skriv', 'Ordet är felstavat: ”titar”. Skriv det rätt.', null, '["tittar"]'::jsonb, 'I är kort i tittar, så t ska dubbleras.'),
  ('237b2dfa-6ea4-5c2f-bb3d-4f3deb4da009', '8e68b8c0-1106-573b-99f1-d76430a84964', 8, 'ordna', 'Bygg meningen. En bricka är felstavad och hör inte dit.', '["vaten"]'::jsonb, '["Pappa","dricker","vatten","och","kaffe."]'::jsonb, 'Vatten stavas med tt eftersom a är kort. I dricker skrivs k-ljudet ck av samma skäl.'),
  ('c6c810c9-a116-52a9-b315-0090ddf461ac', '8587bd64-b845-5416-aa94-d732726c55d6', 1, 'val', 'Vad är en synonym?', '["Ett ord som betyder nästan samma sak som ett annat","Ett ord som betyder motsatsen till ett annat","Ett ord som rimmar på ett annat"]'::jsonb, '0'::jsonb, 'Synonymer betyder nästan samma sak, som prata och tala. Ord med motsatt betydelse kallas motsatsord.'),
  ('0c1e4d9b-c713-5f5f-8c61-b3b94b806e06', '8587bd64-b845-5416-aa94-d732726c55d6', 2, 'val', 'Vilket ord är en synonym till ”tala”?', '["prata","tiga","lyssna","skriva"]'::jsonb, '0'::jsonb, 'Tala och prata betyder nästan samma sak. Tiga är tvärtom, ett motsatsord.'),
  ('73ad44b2-b383-52b0-b264-3948ef3e31b1', '8587bd64-b845-5416-aa94-d732726c55d6', 3, 'val', 'Vilket ord betyder nästan samma sak som ”börja”?', '["starta","sluta","vänta"]'::jsonb, '0'::jsonb, 'Man kan säga att filmen börjar eller att filmen startar. Sluta är motsatsen.'),
  ('6edd5d01-a737-5035-b50a-ba91c54001f3', '8587bd64-b845-5416-aa94-d732726c55d6', 4, 'val', 'Vilket ord är ett motsatsord till ”tidig”?', '["sen","snabb","morgon"]'::jsonb, '0'::jsonb, 'Den som inte kommer tidigt kommer sent. Tidig och sen är motsatser.'),
  ('dc0a8d03-e2c1-553f-91e6-c51bd34062f9', '8587bd64-b845-5416-aa94-d732726c55d6', 5, 'skriv', 'Skriv motsatsordet till ”tung”.', null, '["lätt"]'::jsonb, 'Det som inte är tungt är lätt att bära. Tung och lätt är motsatser.'),
  ('76ada539-7641-5ca1-90ed-acb82ee79855', '8587bd64-b845-5416-aa94-d732726c55d6', 6, 'skriv', 'Skriv motsatsordet till ”vinna”.', null, '["förlora"]'::jsonb, 'I en match vinner det ena laget och det andra förlorar.'),
  ('2015e763-3a45-5ef6-bd89-12486cc0d2bf', '8587bd64-b845-5416-aa94-d732726c55d6', 7, 'skriv', 'Skriv motsatsordet till ”stark”, som i ”Hon är stark.”', null, '["svag","klen"]'::jsonb, 'Den som inte är stark är svag. Stark och svag är motsatser.'),
  ('dc7dfe58-bb85-5c71-ac54-628e7f24dee2', '8587bd64-b845-5416-aa94-d732726c55d6', 8, 'ordna', 'Ordna orden från minst till störst.', null, '["pytteliten","liten","stor","enorm"]'::jsonb, 'Pytteliten är mindre än liten, och enorm är större än stor.'),
  ('ffa740a9-1c60-5192-9374-0023ef0c9b72', '69a6a133-f007-5b94-9ab6-2f4c7bbada37', 1, 'ordna', 'Bygg meningen.', null, '["Efter","skolan","spelar","vi","fotboll."]'::jsonb, 'Efter skolan är meningens första del. Då kommer verbet spelar direkt efter, och sedan vi.'),
  ('a83a8706-e90c-5efd-b4e5-ef113dd3b4d2', '69a6a133-f007-5b94-9ab6-2f4c7bbada37', 2, 'ordna', 'Bygg frågan.', null, '["Har","du","ätit","frukost?"]'::jsonb, 'I en fråga som man svarar ja eller nej på står verbet först: Har du …?'),
  ('66a1e2a7-51a2-5e5c-a8c1-185f583fa70f', '69a6a133-f007-5b94-9ab6-2f4c7bbada37', 3, 'ordna', 'Bygg en fråga som börjar med frågeordet var.', null, '["Var","bor","din","kusin?"]'::jsonb, 'Efter frågeordet kommer verbet bor, och sedan den man frågar om: din kusin.'),
  ('e49b1708-140d-5162-a91d-a0d4ee0c83de', '69a6a133-f007-5b94-9ab6-2f4c7bbada37', 4, 'ordna', 'Bygg meningen. Den har en bisats som säger när.', null, '["Vi","går","hem","när","filmen","är","slut."]'::jsonb, 'Vi går hem är huvudsatsen. När filmen är slut är en bisats som säger när vi går.'),
  ('f0b321f6-3746-5638-8c1f-b5f4d6960221', '69a6a133-f007-5b94-9ab6-2f4c7bbada37', 5, 'val', 'Vilken mening har rätt ordföljd?', '["Nu ska vi baka.","Nu vi ska baka.","Nu ska baka vi."]'::jsonb, '0'::jsonb, 'Verbet ska står på andra plats, direkt efter nu. Sedan kommer vi och sist baka.'),
  ('0ad85bbc-3d5b-55ef-819d-9888a60c76ca', '69a6a133-f007-5b94-9ab6-2f4c7bbada37', 6, 'val', 'Vilken mening är rätt?', '["Det är en film som jag inte har sett.","Det är en film som jag har inte sett.","Det är en film som jag har sett inte."]'::jsonb, '0'::jsonb, 'Som jag inte har sett är en bisats. I en bisats står inte före verbet.'),
  ('3c8c1b55-1282-5dcd-b5cc-3126c7b2a5d2', '69a6a133-f007-5b94-9ab6-2f4c7bbada37', 7, 'skriv', 'Gör en mening av orden ”vi”, ”Sedan” och ”äter”. Vilket ord hamnar i mitten?', null, '["äter"]'::jsonb, 'Sedan äter vi. När meningen börjar med sedan kommer verbet på andra plats.'),
  ('9c24bda2-e4b9-5c8f-b1e6-2af0b513a031', '69a6a133-f007-5b94-9ab6-2f4c7bbada37', 8, 'skriv', 'Vilket ord inleder bisatsen? ”Jag stannar inne eftersom det regnar.”', null, '["eftersom"]'::jsonb, 'Eftersom det regnar är en bisats. Den kan inte stå ensam som en hel mening.'),
  ('01ae7a1d-1730-5eb2-afef-064bce362482', '6fda5877-1c08-530d-96ff-f8724e258f4f', 1, 'val', 'Hur skrivs ordet rätt? ”Vi ska se en … på lördag.”', '["fotbollsmatch","fotbolls match","fotboll match"]'::jsonb, '0'::jsonb, 'Fotbollsmatch är ett sammansatt ord: fotboll + s + match. Sammansatta ord skrivs ihop.'),
  ('95212450-04af-5d36-a19e-e39724f82b78', '6fda5877-1c08-530d-96ff-f8724e258f4f', 2, 'val', 'Vilket ord betyder en lärare som undervisar i engelska?', '["engelsklärare","engelsk lärare","engelska lärare"]'::jsonb, '0'::jsonb, 'Engelsklärare är ett sammansatt ord och skrivs ihop. En engelsk lärare är en lärare som kommer från England.'),
  ('9c8938c4-9c1c-5154-8741-49c9f1ab3074', '6fda5877-1c08-530d-96ff-f8724e258f4f', 3, 'val', 'Det är förbjudet att röka här. Vilken skylt är rätt?', '["Rökfritt","Rök fritt","Rök-fritt"]'::jsonb, '0'::jsonb, 'Rökfritt betyder att ingen får röka. Rök fritt, i två ord, betyder tvärtom att man får röka hur mycket man vill.'),
  ('dc72608a-366f-5c03-8507-5bdcf68f6e7c', '6fda5877-1c08-530d-96ff-f8724e258f4f', 4, 'val', 'Vilket är rätt skrivet?', '["till exempel","tillexempel","till-exempel"]'::jsonb, '0'::jsonb, 'Till exempel är inget sammansatt ord utan två ord som hör ihop. De skrivs isär.'),
  ('54da1bfa-5fb3-52e2-86c2-051ad86857bb', '6fda5877-1c08-530d-96ff-f8724e258f4f', 5, 'skriv', 'Skriv det särskrivna ordet rätt: ”Vi åt lamm kotletter.”', null, '["lammkotletter"]'::jsonb, 'Kotletter av lamm heter lammkotletter. Ett sammansatt ord skrivs ihop.'),
  ('9f494e0c-bdc4-55be-9861-5e6ddf566a55', '6fda5877-1c08-530d-96ff-f8724e258f4f', 6, 'skriv', 'Skriv det särskrivna ordet rätt: ”Hon är en duktig fotbolls spelare.”', null, '["fotbollsspelare"]'::jsonb, 'Fotboll + s + spelare blir fotbollsspelare i ett ord. Därför står två s i rad.'),
  ('2daf3752-c503-5879-b002-c440c1a270bd', '6fda5877-1c08-530d-96ff-f8724e258f4f', 7, 'skriv', 'Skriv det särskrivna ordet rätt: ”Stek pannan är varm.”', null, '["stekpannan"]'::jsonb, 'Stek pannan låter som en uppmaning att steka pannan. Pannan man steker i heter stekpannan.'),
  ('eb340f45-d32c-538a-9061-c9feb9bda2f9', '6fda5877-1c08-530d-96ff-f8724e258f4f', 8, 'ordna', 'Bygg meningen. Två brickor hör inte dit.', '["fotbolls","tränare."]'::jsonb, '["Min","storebror","är","fotbollstränare."]'::jsonb, 'Fotbollstränare är ett sammansatt ord och skrivs ihop, precis som storebror.'),
  ('89664e85-6852-56e5-b9dc-18e7805713c9', 'a04c8155-fcd8-5ff6-a27d-48852330ef57', 1, 'val', 'Hur kan man testa om det ska vara de eller dem?', '["Byt ut ordet mot vi eller oss","Se om ordet står först i meningen","Se om det handlar om flera personer"]'::jsonb, '0'::jsonb, 'De fungerar som vi och dem som oss. Passar vi ska det vara de, passar oss ska det vara dem.'),
  ('341a0902-0e05-5018-9737-1da6c8978cae', 'a04c8155-fcd8-5ff6-a27d-48852330ef57', 2, 'skriv', 'De eller dem? ”Mamma träffade … på bussen.”', null, '["dem"]'::jsonb, 'Man säger ”mamma träffade oss”, inte ”mamma träffade vi”. Oss motsvarar dem.'),
  ('1c28a498-ed0e-5b50-b6d1-5d410d2ea152', 'a04c8155-fcd8-5ff6-a27d-48852330ef57', 3, 'skriv', 'De eller dem? ”… bor i huset bredvid.”', null, '["de"]'::jsonb, 'Man säger ”vi bor i huset bredvid”, inte ”oss bor”. Där vi passar ska det vara de.'),
  ('2f3d23d8-7642-52be-a95f-d93bf0a81c7b', 'a04c8155-fcd8-5ff6-a27d-48852330ef57', 4, 'skriv', 'De eller dem? ”Mina kusiner ringde och sa att … var sena.”', null, '["de"]'::jsonb, 'Man säger ”sa att vi var sena”, inte ”sa att oss var sena”. Därför de.'),
  ('861e95ce-3f3b-5acc-954e-939a471ee1e7', 'a04c8155-fcd8-5ff6-a27d-48852330ef57', 5, 'val', 'I vilken mening är de eller dem rätt använt?', '["Läraren berömde dem.","Dem som vill får följa med.","Jag gav de en present."]'::jsonb, '0'::jsonb, 'Läraren berömde oss, alltså dem. I de andra meningarna ska det vara ”De som vill” och ”Jag gav dem”.'),
  ('0047e5d5-481f-53c0-829c-05bffee83e65', 'a04c8155-fcd8-5ff6-a27d-48852330ef57', 6, 'val', 'Vilket ord ska stå i luckan? ”Har du sett … nya eleverna?”', '["de","dem","den"]'::jsonb, '0'::jsonb, 'Här är de en artikel, som i de stora husen. Framför ett adjektiv och ett substantiv i bestämd form plural står alltid de.'),
  ('fa7ec4ac-c957-5e0a-9ff0-88c8f3993a6d', 'a04c8155-fcd8-5ff6-a27d-48852330ef57', 7, 'val', 'Varför ska det stå dem i ”Vi väntade på dem.”?', '["Man kan byta mot oss: väntade på oss","Ordet står sist i meningen","Det handlar om flera personer"]'::jsonb, '0'::jsonb, 'Oss passar, och oss motsvarar dem. Var ordet står i meningen avgör ingenting.'),
  ('b2c962a3-5bde-5143-8a77-8a1b8c527fd2', 'a04c8155-fcd8-5ff6-a27d-48852330ef57', 8, 'ordna', 'Bygg meningen. En bricka hör inte dit.', '["Dem"]'::jsonb, '["De","som","är","klara","får","gå","hem."]'::jsonb, 'Man kan säga ”vi som är klara får gå hem”. Vi passar, alltså de.'),
  ('8cdb517e-715a-5d82-bd68-1b95d53ca81e', 'f4b3e290-818f-550b-95e7-4aae5136e6bc', 1, 'val', 'Vilket ord är predikat i meningen ”Hunden jagar katten.”?', '["jagar","Hunden","katten"]'::jsonb, '0'::jsonb, 'Predikatet är verbet som säger vad som händer. Här är det jagar.'),
  ('e725b2d3-c518-5c19-9211-69a04c621973', 'f4b3e290-818f-550b-95e7-4aae5136e6bc', 2, 'val', 'Vilket ord är subjekt i meningen ”På lördag spelar Omar match.”?', '["Omar","spelar","lördag","match"]'::jsonb, '0'::jsonb, 'Fråga ”vem spelar?”. Svaret är Omar. Subjektet står inte alltid först i meningen.'),
  ('fc8e981a-dff9-55ca-85cf-bc42d056de6d', 'f4b3e290-818f-550b-95e7-4aae5136e6bc', 3, 'val', 'Hur hittar man subjektet i en sats?', '["Hitta predikatet och fråga vem eller vad som gör det","Ta ordet som står först i meningen","Ta det sista substantivet i meningen"]'::jsonb, '0'::jsonb, 'Först predikatet, till exempel spelar. Sedan frågan ”vem spelar?”. Svaret på frågan är subjektet.'),
  ('1366dd84-386d-5b54-a248-1cccb5fcfd8d', 'f4b3e290-818f-550b-95e7-4aae5136e6bc', 4, 'val', 'Vad av detta saknar predikat?', '["En kall morgon i januari.","Det snöade hela natten.","Vi frös."]'::jsonb, '0'::jsonb, 'En kall morgon i januari har inget verb. Utan predikat blir det ingen sats.'),
  ('2419286f-72e5-504c-9935-70aa063e1efd', 'f4b3e290-818f-550b-95e7-4aae5136e6bc', 5, 'skriv', 'Skriv predikatet i meningen: ”Barnen byggde en koja i skogen.”', null, '["byggde"]'::jsonb, 'Byggde är verbet som säger vad barnen gjorde. Det är predikatet.'),
  ('7d6ef88c-e843-5532-896c-9651b311e4b5', 'f4b3e290-818f-550b-95e7-4aae5136e6bc', 6, 'skriv', 'Skriv subjektet i frågan: ”Varför skrattar Elsa?”', null, '["Elsa"]'::jsonb, 'Fråga ”vem skrattar?”. Svaret är Elsa. I frågor står subjektet ofta efter predikatet.'),
  ('38e5b55b-98dc-502c-82d0-2cc22d4332f6', 'f4b3e290-818f-550b-95e7-4aae5136e6bc', 7, 'skriv', 'Hur många predikat finns det i meningen? ”Vi åt middag och sedan diskade vi.”', null, '["2","två"]'::jsonb, 'Meningen har två satser, och varje sats har ett eget predikat: åt och diskade.'),
  ('965dddb0-fef6-5ad2-a1e6-6769e33c85e4', 'f4b3e290-818f-550b-95e7-4aae5136e6bc', 8, 'ordna', 'Bygg frågan.', null, '["Spelar","din","syster","fotboll?"]'::jsonb, 'I en ja- eller nej-fråga står predikatet spelar först, och subjektet din syster kommer direkt efter.'),
  ('e97d5623-8c40-5e4c-8299-65838992bffa', 'a589b6fe-0383-5792-bee1-d81b6f657bfa', 1, 'val', 'I vilken mening står kolonet rätt?', '["Vi behöver tre saker till kalaset: ballonger, tårta och saft.","Vi behöver tre saker: till kalaset ballonger, tårta och saft.","Vi behöver: tre saker till kalaset ballonger, tårta och saft."]'::jsonb, '0'::jsonb, 'Kolon står före uppräkningen, direkt efter orden som säger att något ska räknas upp.'),
  ('f8e05872-5a58-5843-b6dc-fd77aee49c25', 'a589b6fe-0383-5792-bee1-d81b6f657bfa', 2, 'val', 'Vilken mening har rätt skiljetecken?', '["Vi köpte äpplen, päron och bananer.","Vi köpte äpplen päron och bananer.","Vi köpte, äpplen päron och bananer."]'::jsonb, '0'::jsonb, 'I en uppräkning står komma mellan orden. Före och behövs normalt inget komma.'),
  ('697c300b-7eb4-5230-ac1f-4648a790b040', 'a589b6fe-0383-5792-bee1-d81b6f657bfa', 3, 'val', 'Vilken replik är rätt skriven?', '["– Jag är hungrig, sa Elin.","– Jag är hungrig. Sa Elin.","– Jag är hungrig sa Elin."]'::jsonb, '0'::jsonb, 'Efter repliken står komma, och sa skrivs med liten bokstav eftersom meningen fortsätter.'),
  ('8c994035-a285-501d-91f8-e049e1e6c04f', 'a589b6fe-0383-5792-bee1-d81b6f657bfa', 4, 'val', 'Repliken är en fråga. Hur ska den skrivas?', '["– Vill du ha glass? frågade Tim.","– Vill du ha glass?, frågade Tim.","– Vill du ha glass, frågade Tim?"]'::jsonb, '0'::jsonb, 'Frågetecknet står direkt efter frågan. Då behövs inget komma, och frågade skrivs med liten bokstav.'),
  ('7ed6e7f7-b2b9-52cd-b29c-86fbfc83eff9', 'a589b6fe-0383-5792-bee1-d81b6f657bfa', 5, 'skriv', 'Vad heter tecknet efter ”saker” i meningen ”Ta med tre saker: matsäck, vatten och regnjacka.”?', null, '["kolon"]'::jsonb, 'Tecknet med två prickar är kolon. Det står ofta före en uppräkning eller en förklaring.'),
  ('c2d7bfff-7252-50d1-8dfa-e982e99a539b', 'a589b6fe-0383-5792-bee1-d81b6f657bfa', 6, 'skriv', 'Hur många kommatecken behövs i meningen? ”Vi såg älgar rådjur harar och en räv.”', null, '["2","två"]'::jsonb, 'Det blir ”älgar, rådjur, harar och en räv”. Komma står mellan orden i uppräkningen men normalt inte före och.'),
  ('316dadee-5329-5175-8828-39daabd790de', 'a589b6fe-0383-5792-bee1-d81b6f657bfa', 7, 'skriv', 'Vad heter tecknen som står runt ett citat, som runt ”Hej”?', null, '["citattecken","citationstecken","anföringstecken","citattecknen","citationstecknen","anföringstecknen","gåsögon"]'::jsonb, 'Citattecken, som också kallas anföringstecken och i vardagligt tal gåsögon, visar var det någon sagt eller skrivit börjar och slutar.'),
  ('4c79599a-1566-5740-b4a2-3251319486d8', 'a589b6fe-0383-5792-bee1-d81b6f657bfa', 8, 'ordna', 'Bygg repliken.', null, '["–","Var","är","mina","skor?","frågade","Ali."]'::jsonb, 'Talstrecket står först. Frågetecknet avslutar frågan, och sedan kommer frågade Ali med punkt sist.')
